window.BIOMASTER = window.BIOMASTER || {};
window.BIOMASTER.TF_BANK = [{"id":"TF-001","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nước & Hóa học Tế bào","stem":"Nước chiếm khoảng $70 - 90\\%$ khối lượng tế bào sống và đóng vai trò dung môi vạn năng nhờ tính phân cực cùng mạng lưới liên kết hiđrô giữa các phân tử. Khi phân tích các đặc tính lý-hóa của nước trong sinh học tế bào, mỗi nhận định sau đây Đúng hay Sai?","statements":[{"key":"a","text":"Liên kết hiđrô giữa các phân tử nước là liên kết yếu hình thành giữa nguyên tử hiđrô mang một phần điện tích dương ($\\delta^+$) của phân tử này với nguyên tử oxi mang một phần điện tích âm ($\\delta^-$) của phân tử khác.","ans":true,"exp":"Tính phân cực của liên kết cộng hóa trị O-H tạo lực hút tĩnh điện yếu gọi là liên kết hiđrô giữa các phân tử nước lân cận."},{"key":"b","text":"Nhờ hệ thống liên kết hiđrô dày đặc, nước có nhiệt dung riêng rất cao giúp tế bào và cơ thể sinh vật tránh được sự biến động nhiệt độ đột ngột.","ans":true,"exp":"Cần lượng nhiệt lớn để phá vỡ mạng liên kết hiđrô trước khi làm tăng động năng phân tử nước, giúp ổn định thân nhiệt và môi trường nước."},{"key":"c","text":"Ở trạng thái rắn (nước đá), các phân tử nước xếp xít nhau hơn trạng thái lỏng nên khối lượng riêng của băng lớn hơn nước lỏng và chìm xuống đáy ao hồ vào mùa đông.","ans":false,"exp":"Khi đóng băng ($0^\\circ\\text{C}$), các liên kết hiđrô cố định thành mạng tinh thể tứ diện thưa rỗng làm thể tích tăng, tỷ trọng nhẹ hơn nước lỏng nên băng nổi lên trên cách nhiệt cho thủy sinh vật."},{"key":"d","text":"Nước là môi trường trực tiếp cho các phản ứng thủy phân (như thủy phân tinh bột, protein) cũng như tham gia trực tiếp làm chất cho electron trong quang phân ly nước.","ans":true,"exp":"Nước vừa là dung môi vừa là chất tham gia trực tiếp các phản ứng sinh hóa thiết yếu của tế bào."}],"summaryExp":""},{"id":"TF-002","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cấu trúc Màng sinh chất","stem":"Theo mô hình khảm động (Fluid Mosaic Model) của Singer và Nicolson (1972), màng sinh chất cấu tạo chủ yếu từ lớp kép photpholipit và các phân tử protein cùng cacbohiđrat, cholesterol. Xét các nhận định sau về cấu trúc và tính chất màng tế bào động vật:","statements":[{"key":"a","text":"Các phân tử photpholipit có đầu ưa nước hướng ra ngoài tiếp xúc môi trường nước và hai đuôi axit béo kỵ nước quay vào trong lõi màng.","ans":true,"exp":"Tính chất lưỡng cực của photpholipit khiến chúng tự lắp ráp thành lớp kép kín bền vững trong môi trường nước."},{"key":"b","text":"Các phân tử cholesterol xen kẽ giữa lớp kép photpholipit giúp ổn định tính lỏng của màng: hạn chế chuyển động quá mức khi nhiệt độ cao và ngăn màng đông cứng kết tinh khi nhiệt độ hạ thấp.","ans":true,"exp":"Cholesterol đóng vai trò chất đệm điều hòa độ linh động màng sinh chất ở tế bào động vật."},{"key":"c","text":"Ở tế bào nhân thực, tất cả các protein xuyên màng chỉ bám hờ trên bề mặt ngoài bằng lực hút tĩnh điện yếu chứ không xuyên qua vùng lõi kỵ nước của lớp kép.","ans":false,"exp":"Protein xuyên màng (protein tích hợp) có vùng kỵ nước nằm lọt sâu trong lõi axit béo xuyên suốt lớp kép photpholipit để làm kênh, chất mang hoặc thụ thể."},{"key":"d","text":"Khi thả tế bào hồng cầu người bình thường vào dung dịch muối $NaCl$ nồng độ $1.8\\%$ (ưu trương), nước sẽ đi từ trong tế bào ra ngoài khiến hồng cầu bị co rút nhăn nheo.","ans":true,"exp":"Nước muối sinh lý đẳng trương là $0.9\\%$; dung dịch $1.8\\%$ là ưu trương nên nước thẩm thấu ra ngoài làm hồng cầu teo lại."}],"summaryExp":""},{"id":"TF-003","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hệ thống Bào quan Tế bào nhân thực","stem":"Một nhà sinh học tế bào theo dõi con đường tổng hợp và tiết một loại enzyme tiêu hóa protein ngoại bào (như Pepsinogen ở tế bào tuyến dạ dày) bằng phương pháp đánh dấu đồng vị phóng xạ $^{3}H$-Leucine (axit amin). Xét các nhận định sau:","statements":[{"key":"a","text":"Chuỗi polipeptit sơ khai của enzyme tiết được tổng hợp bởi các ribosome bám trên bề mặt mạng lưới nội chất hạt (RER).","ans":true,"exp":"Protein xuất bào, protein màng và enzyme lizôxôm được dịch mã tại ribosome trên lưới nội chất hạt rồi đẩy vào xoang RER."},{"key":"b","text":"Mạng lưới nội chất trơn (SER) chịu trách nhiệm tổng hợp chuỗi mARN để truyền ra tế bào chất dịch mã tạo enzyme protein tiết.","ans":false,"exp":"mARN được tổng hợp trong nhân tế bào; SER không có ribosome mà chuyên tổng hợp lipid, phospholipid, hormone steroid và khử độc."},{"key":"c","text":"Từ lưới nội chất hạt, protein được gói trong túi vận chuyển chuyển tới bộ máy Golgi để hoàn thiện cấu trúc (như gắn nhóm đường), phân loại và đóng gói vào túi tiết.","ans":true,"exp":"Bộ máy Golgi nhận túi từ mặt cis, sửa đổi hóa học và xuất túi tiết ở mặt trans đưa đến màng sinh chất."},{"key":"d","text":"Quá trình giải phóng enzyme ra khỏi màng tế bào theo cơ chế xuất bào (exocytosis) cần tiêu tốn năng lượng ATP và sự trợ giúp của khung xương tế bào.","ans":true,"exp":"Xuất bào là hình thức vận chuyển tích cực khối lớn sử dụng ATP và vi ống khung xương tế bào."}],"summaryExp":""},{"id":"TF-004","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thuyết Nội cộng sinh - Ty thể & Lục lạp","stem":"Thuyết nội cộng sinh (Endosymbiosis) giải thích nguồn gốc của ty thể và lục lạp ở tế bào nhân thực hiện đại là hậu quả của việc tế bào nhân thực cổ đại thực bào các vi khuẩn hiếu khí và vi khuẩn lam quang hợp nhưng không tiêu hóa chúng. Những bằng chứng nào sau đây ủng hộ thuyết này?","statements":[{"key":"a","text":"Cả ty thể và lục lạp đều chứa phân tử ADN dạng vòng kép trần (không liên kết với protein histon) tương tự nhiễm sắc thể của vi khuẩn.","ans":true,"exp":"Hệ gen riêng dạng vòng trần là đặc điểm di truyền cổ điển có nguồn gốc vi khuẩn."},{"key":"b","text":"Ribosome bên trong chất nền ty thể và stroma lục lạp thuộc loại $70S$, nhạy cảm với một số kháng sinh ức chế vi khuẩn như chloramphenicol giống ribosome sinh vật nhân sơ.","ans":true,"exp":"Tế bào chất nhân thực dùng ribosome $80S$, nhưng ty thể/lục lạp dùng ribosome $70S$ đặc trưng của vi khuẩn."},{"key":"c","text":"Màng ngoài của ty thể hoàn toàn không chứa photpholipit, còn màng trong hoàn toàn phẳng không gấp nếp mà chứa thành phần peptidoglycan dày giống vi khuẩn Gram dương.","ans":false,"exp":"Cả 2 màng ty thể đều là màng photpholipit; màng trong gấp nếp thành mào (cristae) chứa nhiều cardiolipin (giống màng vi khuẩn) và không có lớp peptidoglycan dày."},{"key":"d","text":"Ty thể và lục lạp tự phân chia bên trong tế bào bằng nguyên phân có hình thành thoi vô sắc từ trung thể của nhân tế bào.","ans":false,"exp":"Hai bào quan này tự nhân đôi độc lập bằng cách phân đôi giống vi khuẩn chứ không dùng thoi vô sắc hay phụ thuộc kỳ nguyên phân."}],"summaryExp":""},{"id":"TF-005","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Động học Enzyme & Chất ức chế","stem":"Một nhà sinh hóa học đo tốc độ ban đầu ($V_0$) của một enzyme tuân theo phương trình Michaelis-Menten theo nồng độ cơ chất $[S]$ ở 3 nghiệm thức: (I) Không có chất ức chế ($V_{\\max} = 100\\text{ \\mu mol/phút}$, $K_m = 2\\text{ mM}$); (II) Bổ sung chất ức chế X; (III) Bổ sung chất ức chế Y. Kết quả thu được cho thấy chất X làm $V_{\\max}$ vẫn bằng $100$ nhưng $K_m^{\\text{app}} = 6\\text{ mM}$; chất Y làm $V_{\\max}^{\\text{app}} = 50$ nhưng $K_m$ vẫn bằng $2\\text{ mM}$. Mỗi phân tích sau Đúng hay Sai?","statements":[{"key":"a","text":"Chất X là chất ức chế cạnh tranh thuận nghịch, có cấu trúc tương tự cơ chất và cạnh tranh trực tiếp vào trung tâm hoạt động của enzyme.","ans":true,"exp":"Chất ức chế cạnh tranh có thể bị đẩy lùi nếu tăng nồng độ $[S]$ rất cao nên $V_{\\max}$ giữ nguyên ($100$), nhưng cần nồng độ cơ chất cao hơn nên $K_m$ biểu kiến tăng ($2 \\to 6\\text{ mM}$)."},{"key":"b","text":"Khi tăng nồng độ cơ chất $[S]$ lên thật cao (ví dụ $500\\text{ mM}$), tác động ức chế của chất Y sẽ bị loại bỏ hoàn toàn đưa tốc độ phản ứng chạm mức $100\\text{ \\mu mol/phút}$.","ans":false,"exp":"Chất Y là chất ức chế KHÔNG cạnh tranh (gắn vào vị trí ngoài trung tâm hoạt động làm biến dạng không gian TTHĐ nên giảm $V_{\\max}$ còn $50$ bất kể $[S]$ cao cỡ nào)."},{"key":"c","text":"Trong trường hợp bổ sung chất ức chế X, nếu giữ nồng độ cơ chất đúng bằng $6\\text{ mM}$ thì tốc độ phản ứng đo được là $50\\text{ \\mu mol/phút}$.","ans":true,"exp":"Theo định nghĩa, $K_m^{\\text{app}}$ chính là nồng độ cơ chất để vận tốc đạt $\\frac{1}{2} V_{\\max} = 50\\text{ \\mu mol/phút}$."},{"key":"d","text":"Cơ chế điều hòa hoạt động enzyme bằng phân tử hiệu ứng dị lập thể không cạnh tranh gắn ở vùng điều hòa hoàn toàn không làm thay đổi cấu hình không gian ba chiều của phân tử enzyme.","ans":false,"exp":"Chất ức chế/hoạt hóa dị lập thể hoạt động đúng bằng cách gây biến đổi cấu hình không gian (allosteric transition) của toàn bộ phân tử enzyme."}],"summaryExp":""},{"id":"TF-006","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điều hòa Con đường Chuyển hóa","stem":"Xét con đường chuyển hóa phân nhánh trong vi khuẩn: $A \\xrightarrow{E_1} B \\xrightarrow{E_2} C$, sau đó tại $C$ chia hai nhánh: $C \\xrightarrow{E_3} D \\xrightarrow{E_4} X$ (sản phẩm $X$) và $C \\xrightarrow{E_5} F \\xrightarrow{E_6} Y$ (sản phẩm $Y$). Khi nồng độ sản phẩm cuối $X$ tích tụ dư thừa trong tế bào, phân tích logic điều hòa ức chế ngược sau đây Đúng hay Sai?","statements":[{"key":"a","text":"Để tối ưu hóa năng lượng, sản phẩm $X$ dư thừa sẽ trực tiếp ức chế hoàn toàn enzyme $E_1$ khiến cả sản phẩm $Y$ cũng ngừng tổng hợp hoàn toàn dù tế bào đang thiếu $Y$.","ans":false,"exp":"Ở con đường phân nhánh, sản phẩm cuối $X$ chủ yếu ức chế ngược đặc hiệu enzyme đứng ngay đầu nhánh riêng ($E_3$) để $C$ chuyển hướng tạo $Y$ chứ không cắt $E_1$ làm thiếu hụt $Y$."},{"key":"b","text":"Sự tăng cao nồng độ $X$ gây ức chế ngược enzyme $E_3$ giúp ngăn lãng phí $C$ tạo thêm $X$ và đồng thời tạo điều kiện đẩy dòng cơ chất $C$ đi qua nhánh $E_5$ tạo $Y$.","ans":true,"exp":"Cơ chế phản hồi đặc hiệu nhánh giúp điều phối thông lượng chuyển hóa cân bằng giữa hai sản phẩm cuối."},{"key":"c","text":"Nếu tế bào bị dư thừa đồng thời CẢ hai sản phẩm $X$ và $Y$, sự phối hợp ức chế ngược của cả $X$ và $Y$ lên $E_1$ (hoặc lên 2 isozyme của $E_1$) sẽ làm dừng chuỗi từ đầu chất $A$.","ans":true,"exp":"Khi cả hai nhánh đều bão hòa, ức chế phối hợp tại bước cam kết đầu tiên $E_1$ giúp tiết kiệm cơ chất $A$ tối đa."},{"key":"d","text":"Nếu đột biến làm hỏng trung tâm dị lập thể của enzyme $E_3$ khiến $X$ không thể bám ức chế $E_3$, vi khuẩn có thể sản xuất liên tục quá mức sản phẩm $X$ ngay cả khi $X$ đã dư thừa.","ans":true,"exp":"Mất khả năng ức chế ngược (feedback-resistant mutant) chính là nguyên lý kỹ thuật sinh học tạo các chủng vi khuẩn tăng sản xuất axit amin công nghiệp như Lysine, Glutamate."}],"summaryExp":""},{"id":"TF-007","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hô hấp Hiếu khí Tế bào","stem":"Xét toàn bộ quá trình phân giải hoàn toàn $1$ phân tử Glucose ($C_6H_{12}O_6$) trong hô hấp hiếu khí ở tế bào nhân thực bình thường (không có chất độc ức chế chuỗi truyền điện tử). Mỗi nhận định sau Đúng hay Sai?","statements":[{"key":"a","text":"Giai đoạn đường phân diễn ra tại bào tương, phân cắt $1$ phân tử glucose tạo ra $2$ axit pyruvic, tích lũy ròng $2\\text{ ATP}$ (phosphoryl hóa mức cơ chất) và $2\\text{ NADH}$.","ans":true,"exp":"Đường phân tiêu tốn $2\\text{ ATP}$ pha đầu tư và thu $4\\text{ ATP}$ pha thu hoạch $\\rightarrow$ ròng $2\\text{ ATP}$, kèm $2\\text{ NADH}$ và $2$ pyruvat."},{"key":"b","text":"Toàn bộ lượng khí $CO_2$ giải phóng từ $6$ nguyên tử cacbon của phân tử glucose đều được thải ra ở bước chuyển hóa Pyruvat $\\rightarrow$ Acetyl-CoA và Chu trình Krebs bên trong chất nền ty thể.","ans":true,"exp":"$2$ $CO_2$ thoát ở phản ứng khử cacboxyl oxy hóa pyruvat thành acetyl-CoA và $4$ $CO_2$ thoát ra trong 2 vòng Krebs ($2 + 4 = 6$ cacbon)."},{"key":"c","text":"Trong chuỗi truyền electron ở màng trong ty thể, chất nhận điện tử cuối cùng trực tiếp từ phức hệ IV (Cytochrome c oxidase) là phân tử $CO_2$ để biến thành glucozơ.","ans":false,"exp":"Chất nhận điện tử cuối cùng có độ âm điện rất cao là khí oxi phân tử ($O_2$); nhận $4e^-$ và $4H^+$ tạo thành nước $H_2O$."},{"key":"d","text":"Nếu bổ sung chất DNP (2,4-dinitrophenol — chất làm màng trong ty thể bị rò rỉ cho proton $H^+$ đi xuyên tự do qua lớp kép photpholipit không qua ATP synthase), tốc độ tiêu thụ $O_2$ và sinh nhiệt tăng mạnh nhưng sản lượng ATP giảm tụt nghiêm trọng.","ans":true,"exp":"DNP tháo khớp (uncoupler) phá hủy chênh lệch gradient proton ($\\Delta pH$), khiến năng lượng chuỗi chuyền electron giải phóng hết thành nhiệt thay vì tổng hợp ATP."}],"summaryExp":""},{"id":"TF-008","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Lên men & Hô hấp kị khí","stem":"Hai nhóm vi sinh vật thực hiện quá trình phân giải kị khí đường glucose (không có $O_2$): Nấm men bia (*Saccharomyces cerevisiae*) thực hiện lên men rượu và Vi khuẩn sữa (*Lactobacillus*) thực hiện lên men lactic. Xét các nhận định sau:","statements":[{"key":"a","text":"Điểm chung thiết yếu của cả hai loại lên men là đều bắt đầu bằng giai đoạn đường phân tạo $2\\text{ ATP}$ ròng và dùng chất hữu cơ nội sinh làm chất nhận điện tử để tái sinh $NAD^+$ từ $NADH$.","ans":true,"exp":"Nếu không tái oxy hóa $NADH \\rightarrow NAD^+$, đường phân cũng sẽ lập tức đình trệ do cạn nguồn $NAD^+$."},{"key":"b","text":"Quá trình lên men ở nấm men có bước khử cacboxyl loại đi $1$ phân tử $CO_2$ trên mỗi axit pyruvic để biến thành acetaldehyd trước khi khử thành etanol, giúp bánh mì nở phồng.","ans":true,"exp":"Bọt khí $CO_2$ thoát ra làm phồng bột mì và sủi bọt khi lên men rượu bia."},{"key":"c","text":"Lên men lactic đồng hình ở *Lactobacillus* tạo ra lượng $CO_2$ nhiều gấp đôi so với lên men etanol ở nấm men cho mỗi mol glucose.","ans":false,"exp":"Lên men lactic khử trực tiếp axit pyruvic ($C_3H_4O_3$) thành axit lactic ($C_3H_6O_3$) nhờ $NADH$ nên KHÔNG giải phóng $CO_2$."},{"key":"d","text":"Trong cơ xương người khi chạy nước rút cường độ tối đa thiếu oxy, tế bào cơ chuyển sang lên men etanol tạo cồn tích tụ gây mỏi cơ.","ans":false,"exp":"Tế bào cơ người lên men LACTIC tạo axit lactic (sau đó gan thu hồi theo chu trình Cori chuyển ngược thành glucose), chứ không tạo etanol."}],"summaryExp":""},{"id":"TF-009","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Pha sáng Quang hợp trên Tilacoit","stem":"Nghiên cứu phức hệ màng tilacoit trong lục lạp thực vật bậc cao đang được chiếu ánh sáng trắng bình thường ở môi trường đủ nước. Xét các nhận định sau về chuỗi truyền điện tử và hóa thẩm trong pha sáng:","statements":[{"key":"a","text":"Electron bị bật ra khỏi cặp diệp lục a ở trung tâm phản ứng $P_{680}$ (PS II) được bù đắp trực tiếp bằng electron tách ra từ sự quang phân ly phân tử nước.","ans":true,"exp":"Hệ oxy hóa nước gắn với PS II giúp $P_{680}^+$ có thế oxi hóa khử cực dương lấy lại electron từ $H_2O$ và giải phóng $O_2$."},{"key":"b","text":"Khi dòng electron đi qua phức hệ cytochrome $b_6 f$, các ion $H^+$ được bơm tích cực từ lòng xoang tilacoit ra ngoài chất nền stroma làm pH trong xoang tilacoit tăng cao hơn hẳn pH ở stroma.","ans":false,"exp":"Ngược lại: $H^+$ được bơm từ STROMA VÀO XOANG TILACOIT (cộng thêm $H^+$ từ quang phân ly nước sinh ra ngay trong xoang) làm xoang tilacoit có pH axit ($\\approx 5$) THẤP hơn stroma ($\\approx 8$)."},{"key":"c","text":"Sự khuếch tán xuôi chiều gradient điện hóa của ion $H^+$ từ xoang tilacoit đi xuyên qua phức hệ kênh $ATP\\text{ synthase}$ ($CF_0 - CF_1$) quay về stroma xúc tác gắn $P_i$ vào $ADP$ tạo thành $ATP$.","ans":true,"exp":"Đây là cơ chế photphoryl hóa quang hợp theo thuyết hóa thẩm của Peter Mitchell."},{"key":"d","text":"Nếu dùng thuốc diệt cỏ DCMU ngăn chặn sự truyền electron từ $Q_A$ sang $Q_B$ tại PS II, quá trình giải phóng khí $O_2$ từ lục lạp lập tức bị ức chế mạnh.","ans":true,"exp":"Khi $Q_B$ bị khóa, PS II không giải phóng được electron nên $P_{680}$ kẹt ở trạng thái khử, ngừng nhận electron từ nước $\\rightarrow$ ngừng tạo $O_2$."}],"summaryExp":""},{"id":"TF-010","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc Đại phân tử Sinh học","stem":"Xét $4$ nhóm đại phân tử hữu cơ chính cấu tạo nên mọi tế bào sống: Cacbohiđrat, Lipit, Protein và Axit nucleic. Mỗi phát biểu sau đây Đúng hay Sai?","statements":[{"key":"a","text":"Tinh bột, glycogen và xenlulôzơ đều là các chuỗi polixaccarit cấu tạo từ cùng một loại đơn phân duy nhất là $\\alpha$ hoặc $\\beta$-glucose liên kết với nhau qua liên kết glicôzit.","ans":true,"exp":"Tinh bột và glycogen ghép từ $\\alpha$-glucose dễ thủy phân dự trữ năng lượng; xenlulôzơ ghép thẳng từ $\\beta$-glucose (liên kết $\\beta$-1,4) tạo sợi bền chắc làm thành tế bào thực vật."},{"key":"b","text":"Protein có chức năng xúc tác sinh học cực kỳ đa dạng nhờ được tạo nên từ $20$ loại đơn phân axit amin khác nhau về nhóm gốc $R$, xếp theo trình tự đặc thù và cuộn xoắn thành cấu trúc bậc 3 không gian chính xác.","ans":true,"exp":"Trình tự axit amin (bậc 1) quyết định tương tác gấp cuộn thành cấu hình không gian bậc 3, 4 quyết định chức năng sinh học."},{"key":"c","text":"Trong tế bào chất có nhiệt độ tăng lên tới $90^\\circ\\text{C}$, mọi protein enzyme thông thường bị biến tính làm đứt gãy sạch toàn bộ liên kết peptit trong mạch chính bậc 1.","ans":false,"exp":"Biến tính do nhiệt phá vỡ các liên kết yếu (liên kết hiđrô, tương tác kỵ nước, cầu ion) làm hỏng cấu trúc bậc 2, 3, 4 nhưng KHÔNG đủ năng lượng phá vỡ liên kết peptit cộng hóa trị ở mạch bậc 1."},{"key":"d","text":"Lipit (như triglixerit, photpholipit, steroid) đều không có cấu tạo theo nguyên tắc đa phân từ một đơn phân giống nhau lặp lại như protein hay axit nucleic, nhưng chúng có chung tính chất kỵ nước cao.","ans":true,"exp":"Lipit không phải là polymer thực thụ có đơn phân lặp lại mà là nhóm phân tử đa dạng chung đặc tính không tan trong nước."}],"summaryExp":""},{"id":"TF-011","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vận chuyển các chất qua Màng sinh chất","stem":"Tại biểu mô ruột non người, tế bào biểu mô hấp thụ đường Glucose từ lòng ruột (nơi nồng độ Glucose có thể thấp hơn bên trong tế bào biểu mô) bằng protein đồng vận chuyển SGLT1 phụ thuộc vào chênh lệch nồng độ $Na^+$, được duy trì nhờ bơm $Na^+/K^+$ đặt ở màng đáy-bên. Xét các nhận định sau:","statements":[{"key":"a","text":"Glucose được đưa từ lòng ruột vào tế bào biểu mô ruột theo phương thức khuếch tán thụ động đơn thuần không hề tiêu tốn gián tiếp ATP.","ans":false,"exp":"Đi ngược chiều nồng độ glucose bằng đồng vận chuyển dựa trên gradient $Na^+$ là vận chuyển chủ động THỨ CẤP, gián tiếp tiêu tốn ATP ở bơm $Na^+/K^+$ ATPase."},{"key":"b","text":"Protein SGLT1 cho phép $Na^+$ khuếch tán xuôi dốc điện hóa từ lòng ruột vào trong tế bào đồng thời kéo theo Glucose đi cùng chiều vào tế bào (cơ chế symport).","ans":true,"exp":"Năng lượng từ dòng chảy xuôi chiều $Na^+$ giải phóng ra làm động lực đưa glucose ngược dốc vào tế bào."},{"key":"c","text":"Nếu nhỏ chất Ouabain ức chế đặc hiệu bơm $Na^+/K^+$ ATPase ở mặt đáy-bên tế bào biểu mô ruột, quá trình hấp thụ chủ động glucose ở mặt đỉnh qua SGLT1 cũng sẽ sớm bị đình trệ.","ans":true,"exp":"Khi bơm $Na^+/K^+$ ngừng chạy, nồng độ $Na^+$ nội bào tăng lên xóa mất gradient $Na^+$ qua màng đỉnh khiến SGLT1 hết động lực hoạt động."},{"key":"d","text":"Thụ thể LDL trên màng tế bào gan bắt giữ hạt lipoprotein kích thước lớn bằng phương thức nhập bào qua trung gian thụ thể (Receptor-mediated endocytosis).","ans":true,"exp":"Hạt LDL mang cholesterol quá lớn không qua được kênh màng nên được thu nhận đặc hiệu qua hố phủ clathrin."}],"summaryExp":""},{"id":"TF-012","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Truyền tin Tế bào","stem":"Hormone Adrenalin (tan trong nước, không tự đi qua được lớp kép photpholipit) gắn vào thụ thể $\\beta$-adrenergic trên màng tế bào gan kích hoạt con đường truyền tin nội bào gây phân giải glycogen thành glucose giải phóng vào máu. Xét các nhận định sau về chuỗi truyền tin này:","statements":[{"key":"a","text":"Thụ thể $\\beta$-adrenergic là một loại thụ thể kết cặp protein G (GPCR); khi Adrenalin gắn vào, protein $G_s$ giải phóng GDP để gắn GTP và hoạt hóa enzyme màng Adenylyl cyclase.","ans":true,"exp":"Đây là cơ chế kinh điển của họ thụ thể GPCR xuyên màng 7 lần."},{"key":"b","text":"Enzyme Adenylyl cyclase chuyển hóa ATP nội bào thành chất truyền tin thứ hai là cAMP (AMP vòng); chỉ một phân tử hormone gắn vào có thể kích hoạt tạo ra hàng nghìn phân tử cAMP giúp khuếch đại tín hiệu mạnh mẽ.","ans":true,"exp":"Mỗi bước hoạt hóa enzyme dây chuyền (GPCR $\\to$ Adenylyl cyclase $\\to$ PKA $\\to$ Phosphorylase kinase) nhân bội số lượng phân tử phản ứng."},{"key":"c","text":"Hormone sinh dục Testosterone và Estrogen bản chất steroid tan trong dầu cũng bắt buộc phải sử dụng thụ thể GPCR trên màng ngoài và cAMP do không thể chui qua lớp kép photpholipit.","ans":false,"exp":"Ngược lại: hormone steroid nhỏ và ưa lipit (kỵ nước) khuếch tán dễ dàng xuyên qua lõi kỵ nước của màng sinh chất để gắn vào THỤ THỂ NỘI BÀO trong bào tương hoặc nhân."},{"key":"d","text":"Sau khi kết thúc kích thích, enzyme Phosphodiesterase nhanh chóng thủy phân cAMP thành AMP mất hoạt tính để tắt tín hiệu tế bào kịp thời.","ans":true,"exp":"Hệ thống ngắt tín hiệu (cùng với tính tự thủy phân GTP của protein G) đảm bảo tế bào sẵn sàng đáp ứng tín hiệu mới."}],"summaryExp":""},{"id":"TF-013","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vi sinh vật - Cấu trúc Tế bào Nhân sơ","stem":"Khi tiến hành nhuộm Gram hai chủng vi khuẩn phân lập được (*Staphylococcus aureus* bắt màu tím đặc trưng và *Escherichia coli* bắt màu hồng đỏ), phân tích sự khác biệt cấu trúc thành tế bào giải thích cho kết quả này:","statements":[{"key":"a","text":"Chủng *S. aureus* là vi khuẩn Gram dương có lớp thành peptidoglycan rất dày nằm bên ngoài cùng, giữ chặt phức hợp tím kết tinh – iod trong bước tẩy cồn.","ans":true,"exp":"Lưới peptidoglycan dày co lại khi rửa cồn giữ phức hợp màu tím crystal violet - iod."},{"key":"b","text":"Chủng *E. coli* là vi khuẩn Gram âm không hề chứa thành phần peptidoglycan nào trong thành tế bào.","ans":false,"exp":"Vi khuẩn Gram âm vẫn CÓ lớp peptidoglycan nhưng rất mỏng nằm trong khoang chu chất bên dưới lớp màng ngoài lipopolysaccharide (LPS)."},{"key":"c","text":"Thành phần Lipopolysaccharide (LPS) nằm ở lớp màng ngoài của vi khuẩn Gram âm chứa phần Lipid A có thể hoạt động như nội độc tố gây sốt và sốc nhiễm khuẩn ở người.","ans":true,"exp":"LPS vừa bảo vệ vi khuẩn Gram âm khỏi thuốc nhuộm, lysozyme, một số kháng sinh (như penicillin G) vừa là nội độc tố đặc trưng."},{"key":"d","text":"Kháng sinh Penicillin ức chế enzyme nối chéo peptidoglycan nên phát huy hiệu quả diệt khuẩn rõ rệt nhất trên vi khuẩn đang sinh trưởng phân chia mạnh.","ans":true,"exp":"Vi khuẩn đang tăng trưởng cần tổng hợp liên tục vách peptidoglycan mới; khi bị khóa nối chéo vách trở nên yếu ớt dẫn tới ly giải thẩm thấu."}],"summaryExp":""},{"id":"TF-014","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh trưởng Quần thể Vi sinh vật","stem":"Nuôi cấy $10^3$ tế bào vi khuẩn *E. coli* vào bình tam giác chứa $100\\text{ ml}$ môi trường dinh dưỡng tổng hợp kín không bổ sung thêm chất dinh dưỡng mới (nuôi cấy không liên tục) chứa đồng thời hỗn hợp đường Glucose và Lactose. Quan sát đồ thị sinh trưởng của quần thể vi khuẩn:","statements":[{"key":"a","text":"Ở pha tiềm phát (pha lag), số lượng tế bào vi khuẩn chưa tăng rõ rệt vì chúng đang thích nghi môi trường và tổng hợp các enzyme cần thiết cho trao đổi chất.","ans":true,"exp":"Pha lag là thời kỳ tổng hợp ARN, protein, enzyme chuẩn bị cho bước phân bào nhanh."},{"key":"b","text":"Trong giai đoạn sinh trưởng kép (diauxic), vi khuẩn tiêu thụ hết Lactose trước rồi tạm nghỉ để tổng hợp enzyme tiêu hóa Glucose vì đường đôi luôn ưu tiên hơn đường đơn.","ans":false,"exp":"Vi khuẩn ưu tiên sử dụng GLUCOSE trước (đường đơn dễ chuyển hóa, gây ức chế cảm ứng operon Lac); khi cạn sạch Glucose mới có pha nghỉ thứ 2 để bật operon Lac dùng Lactose."},{"key":"c","text":"Giả sử trong pha lũy thừa có thời gian thế hệ $g = 20\\text{ phút}$, sau đúng $2$ giờ kể từ đầu pha lũy thừa, một dòng tế bào khởi điểm gồm $10^3$ tế bào sẽ nhân lên thành $6.4 \\times 10^4$ tế bào.","ans":true,"exp":"$2\\text{ giờ} = 120\\text{ phút} \\Rightarrow n = 120 / 20 = 6$ lần phân chia. Số tế bào $N_t = 10^3 \\times 2^6 = 64 \\times 10^3 = 6.4 \\times 10^4$."},{"key":"d","text":"Ở pha cân bằng của nuôi cấy không liên tục, quá trình phân bào ở mọi vi khuẩn đã dừng hẳn bằng $0$ tuyệt đối và không có bất kỳ tế bào nào chết.","ans":false,"exp":"Ở pha cân bằng tốc độ sinh mới bằng tốc độ chết đi ($\\approx$ nhau) nên số tế bào sống đạt cực đại ổn định trước khi chuyển sang pha suy vong."}],"summaryExp":""},{"id":"TF-015","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh học Virus & Phage","stem":"So sánh chu trình nhân lên của $3$ loại virus khác nhau: Phage $T_4$ (chỉ có chu trình tan), Phage $\\lambda$ (có chu trình tan và tiềm tan) và Retrovirus HIV (gây suy giảm miễn dịch ở người). Xét các nhận định sau:","statements":[{"key":"a","text":"Khi phage $\\lambda$ đi vào chu trình tiềm tan, toàn bộ axit nucleic của phage được dịch mã ngay tạo hàng trăm vỏ capsid làm vỡ tan tế bào chủ *E. coli* chỉ sau $30$ phút.","ans":false,"exp":"Trong chu trình tiềm tan, ADN của phage $\\lambda$ gắn xen vào nhiễm sắc thể tế bào chủ ở trạng thái tiền phage (prophage) lặng lẽ nhân đôi cùng tế bào chủ nhiều thế hệ mà chưa làm tan tế bào."},{"key":"b","text":"Vật chất di truyền của virus HIV gồm $2$ phân tử ARN mạch đơn dương và được đóng gói sẵn enzyme phiên mã ngược (Reverse Transcriptase) trong lõi hạt virus.","ans":true,"exp":"Tế bào người không có enzyme phiên mã ngược nên HIV buộc phải mang sẵn enzyme này trong capsid để tổng hợp cDNA mạch kép từ khuôn ARN ngay sau khi xâm nhập."},{"key":"c","text":"Phage $T_4$ bơm phân tử ADN vào tế bào vi khuẩn chủ còn giữ lớp vỏ protein rỗng bên ngoài, trong khi virus HIV có màng bao ngoài dung hợp với màng sinh chất để đưa cả lõi nucleocapsid vào tế bào $CD4^+$.","ans":true,"exp":"Virus có gai gp120/gp41 gắn đồng thụ thể $CD4/CCR5$ rồi hòa màng; ngược lại phage bơm axit nucleic xuyên thành peptidoglycan."},{"key":"d","text":"Sử dụng thuốc AZT (chất tương tự thymidin thiếu nhóm $3'-OH$) có thể ức chế chọn lọc quá trình tổng hợp sợi ADN mới của HIV nhờ chặn kéo dài mạch ở enzyme phiên mã ngược.","ans":true,"exp":"AZT là chất ức chế phiên mã ngược tương tự nucleoside (NRTI) làm dừng tổng hợp proviral cDNA sớm."}],"summaryExp":""},{"id":"TF-016","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc Hóa học ADN","stem":"Một đoạn phân tử ADN mạch kép tuyến tính theo mô hình Watson - Crick gồm $3000$ cặp nucleotit, trong đó số nucleotit loại Guanin ($G$) chiếm $30\\%$ tổng số nucleotit của cả phân tử. Xét các nhận định định lượng và cấu trúc sau:","statements":[{"key":"a","text":"Tổng số nucleotit của đoạn ADN là $6000$ với chiều dài bằng $10200\\text{ \\AA}$ ($1.02\\text{ \\mu m}$).","ans":true,"exp":"Tổng $N = 3000 \\times 2 = 6000$ nu; chiều dài $L = 3000 \\times 3.4 = 10200\\text{ \\AA}$."},{"key":"b","text":"Số nucleotit loại Adenin ($A$) trong đoạn ADN này bằng $1200$ và tổng số liên kết hiđrô giữa hai mạch đơn bằng $7800$.","ans":true,"exp":"$G = 30\\% \\Rightarrow A = 20\\% = 0.2 \\times 6000 = 1200$; $G = 1800$. Số liên kết hiđrô $H = 2A + 3G = 2(1200) + 3(1800) = 2400 + 5400 = 7800$."},{"key":"c","text":"Khi tăng nhiệt độ dung dịch chứa đoạn ADN trên để tách biến tính $2$ mạch đơn, phân tử nào có tỷ lệ $\\frac{A+T}{G+C}$ càng cao thì nhiệt độ nóng chảy $T_m$ càng cao.","ans":false,"exp":"Cặp $G \\equiv C$ có $3$ liên kết hiđrô bền vững hơn cặp $A = T$ ($2$ liên kết), nên hàm lượng $G+C$ càng cao thì $T_m$ càng cao (tỷ lệ $(A+T)/(G+C)$ cao làm $T_m$ THẤP xuống)."},{"key":"d","text":"Hai mạch polinucleotit của đoạn ADN chạy song song ngược chiều nhau (một mạch $5' \\rightarrow 3'$, mạch bổ sung $3' \\rightarrow 5'$), liên kết với nhau bằng lực hiđrô đặc hiệu $A=T, G \\equiv C$.","ans":true,"exp":"Tính đối song và nguyên tắc bổ sung là nền tảng giúp tái bản ADN chính xác."}],"summaryExp":""},{"id":"TF-017","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cơ chế Tái bản ADN (Sơ vs Thực)","stem":"Quan sát chạc chữ Y tái bản (Replication fork) của quá trình nhân đôi phân tử ADN ở tế bào vi khuẩn *E. coli* và ở tế bào người. Mỗi nhận định sau đây Đúng hay Sai?","statements":[{"key":"a","text":"Ở cả sinh vật nhân sơ và nhân thực, enzyme $ADN\\text{ polymerase}$ chỉ có thể lắp ráp nucleotit tự do theo chiều $5' \\rightarrow 3'$ và bắt buộc phải có sẵn đầu $3'-OH$ tự do từ một đoạn mồi ARN ngắn.","ans":true,"exp":"Đặc tính bất biến của tất cả các enzyme ADN polymerase được biết đến trên sinh giới là xúc tác tổng hợp chiều $5' \\rightarrow 3'$ cần nhóm $3'-OH$ mồi."},{"key":"b","text":"Trên mạch khuôn có chiều $3' \\rightarrow 5'$ (tính theo hướng mở chạc chữ Y), mạch mới được tổng hợp gián đoạn thành từng đoạn Okazaki nhờ hàng loạt đoạn mồi ARN.","ans":false,"exp":"Trên mạch khuôn $3' \\rightarrow 5'$ theo hướng di chuyển của chạc chữ Y, mạch mới được tổng hợp LIÊN TỤC theo chiều $5' \\rightarrow 3'$ (mạch ra chậm mới tổng hợp gián đoạn trên khuôn $5' \\rightarrow 3'$)."},{"key":"c","text":"Ở sinh vật nhân sơ *E. coli*, enzyme $ADN\\text{ polymerase I}$ vừa cắt bỏ các đoạn mồi ARN bằng hoạt tính exonuclease $5' \\rightarrow 3'$ vừa lấp đầy khoảng trống bằng deoxyribonucleotit.","ans":true,"exp":"Sau khi ADN pol III tổng hợp đoạn Okazaki, ADN pol I thay mồi bằng ADN và Ligase nối khe hở photphodieste cuối cùng."},{"key":"d","text":"Trong mọi tế bào sinh dưỡng (xôma) đã biệt hóa của cơ thể người trưởng thành, enzyme Telomerase hoạt động cực mạnh giúp các đầu mút NST kéo dài mãi mãi không bao giờ bị ngắn đi.","ans":false,"exp":"Ở tế bào xôma trưởng thành, gen Telomerase bị tắt nên telomere ngắn dần sau mỗi lần phân bào (liên quan lão hóa tế bào); telomerase chỉ hoạt động mạnh ở tế bào mầm sinh dục, tế bào gốc và $>85\\%$ tế bào ung thư."}],"summaryExp":""},{"id":"TF-018","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thí nghiệm Meselson - Stahl","stem":"Trong thí nghiệm kinh điển chứng minh nguyên tắc bán bảo toàn của tái bản ADN: người ta nuôi vi khuẩn *E. coli* qua nhiều thế hệ trong môi trường chứa đồng vị nitơ nặng $^{15}N$ để toàn bộ ADN ban đầu đều là băng nặng ($^{15}N - ^{15}N$). Sau đó rửa sạch rồi chuyển vi khuẩn sang môi trường chỉ chứa đồng vị nhẹ $^{14}N$ và cho phân chia đồng bộ qua $3$ thế hệ liên tiếp (thu được $8$ lần số lượng phân tử ADN ban đầu). Mỗi nhận định sau Đúng hay Sai?","statements":[{"key":"a","text":"Sau $1$ thế hệ nhân đôi trong môi trường $^{14}N$, ly tâm phân tách ADN thu được hai băng rõ rệt bằng nhau gồm $50\\%$ ADN băng nặng ($^{15}N - ^{15}N$) và $50\\%$ ADN băng nhẹ ($^{14}N - ^{14}N$).","ans":false,"exp":"Sau thế hệ $1$, tất cả $100\\%$ phân tử ADN con đều là băng LAI trung bình ($^{15}N - ^{14}N$), loại bỏ thuyết bảo toàn."},{"key":"b","text":"Sau $2$ thế hệ nhân đôi trong môi trường $^{14}N$, tỷ lệ phân tử ADN mang cấu trúc lai ($^{15}N - ^{14}N$) chiếm $50\\%$ tổng số phân tử ADN tạo thành.","ans":true,"exp":"Trong $4$ phân tử ADN ở $F_2$: $2$ phân tử vẫn giữ $2$ mạch gốc $^{15}N$ nên ở dạng lai $^{15}N-^{14}N$ ($50\\%$), và $2$ phân tử hoàn toàn nhẹ $^{14}N-^{14}N$ ($50\\%$)."},{"key":"c","text":"Sau $3$ thế hệ nhân đôi trong môi trường $^{14}N$, trong tổng số mạch đơn polinucleotit của tất cả các phân tử ADN thu được, số mạch đơn chỉ chứa $^{15}N$ chiếm $25\\%$.","ans":false,"exp":"Tổng số phân tử ADN $= 2^3 = 8$ phân tử $= 16$ mạch đơn, trong đó chỉ có đúng $2$ mạch đơn ban đầu chứa $^{15}N$ $\\Rightarrow$ tỷ lệ mạch đơn chứa $^{15}N = \\frac{2}{16} = 12.5\\%$ (còn tỷ lệ PHÂN TỬ ADN lai mới là $2/8 = 25\\%$)."},{"key":"d","text":"Nếu tiếp tục nhân đôi đến thế hệ thứ $5$ trong môi trường $^{14}N$, tổng số phân tử ADN hoàn toàn chỉ chứa $^{14}N$ (băng nhẹ) gấp $15$ lần số phân tử ADN lai ($^{15}N - ^{14}N$).","ans":true,"exp":"Tại thế hệ $5$: có $2^5 = 32$ phân tử, trong đó $2$ phân tử lai và $32 - 2 = 30$ phân tử nhẹ hoàn toàn. Tỷ số $30 / 2 = 15$ lần!"}],"summaryExp":""},{"id":"TF-019","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sửa sai ADN & Bệnh di truyền Sửa sai","stem":"Độ chính xác cực cao của sao chép ADN ($\\sim 10^{-9}$ sai sót mỗi cặp bazơ) là nhờ hệ thống kiểm sửa nhiều lớp của tế bào. Xét các nhận định sau về cơ chế sửa sai ADN:","statements":[{"key":"a","text":"Khi $ADN\\text{ polymerase}$ đang tổng hợp mạch mới chiều $5' \\rightarrow 3'$ vô tình gắn nhầm một nucleotit không đúng cặp bổ sung, enzyme có thể lùi lại cắt bỏ nucleotit sai bằng hoạt tính exonuclease $3' \\rightarrow 5'$ (đọc sửa ngay lập tức).","ans":true,"exp":"Hoạt tính đọc sửa (proofreading $3' \\to 5'$) giảm tỷ lệ sai sót từ $\\sim 10^{-5}$ xuống còn $\\sim 10^{-7}$ ngay tại chạc nhân đôi."},{"key":"b","text":"Hệ thống sửa chữa bắt cặp sai (Mismatch Repair - MMR) hoạt động sau khi nhân đôi xong, phân biệt mạch mới tổng hợp để sửa lại theo khuôn mạch cũ nhằm tránh biến sai sót thành đột biến cố định.","ans":true,"exp":"Ở *E. coli*, MMR dựa vào dấu methyl hóa gốc A ở trình tự `GATC` của mạch khuôn mẹ (mạch mới vừa tổng hợp chưa bị methyl hóa ngay) để nhận diện mạch mới."},{"key":"c","text":"Tia cực tím (UV) từ ánh sáng mặt trời thường gây đột biến tạo liên kết cộng hóa trị giữa hai bazơ nitơ Timin đứng cạnh nhau trên cùng một mạch (Dimer Timin); tế bào người sửa sai tổn thương cồng kềnh này bằng cơ chế cắt bỏ nucleotit (NER).","ans":true,"exp":"Thiếu hụt hệ enzyme NER di truyền gây bệnh khô da sắc tố (*Xeroderma pigmentosum*), bệnh nhân cực nhạy cảm tia UV và dễ ung thư da sớm."},{"key":"d","text":"Các bazơ nitơ bị hỏng trong ADN luôn bắt buộc phải cắt bỏ toàn bộ chiều dài cả một nhiễm sắc thể rồi mới gắn ghép lại từng nucleotit.","ans":false,"exp":"Cơ chế sửa cắt bỏ bazơ (BER) hoặc NER chỉ cắt bỏ $1$ bazơ hỏng hoặc đoạn ngắn khoảng $12 - 30$ nucleotit chứa tổn thương và dùng mạch đối diện làm khuôn tổng hợp bù."}],"summaryExp":""},{"id":"TF-020","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phiên mã & Chế biến mARN Nhân thực","stem":"Quá trình phiên mã tổng hợp $mARN$ trưởng thành ở tế bào nhân thực khác biệt sâu sắc về không gian và các bước biến đổi sau phiên mã so với vi khuẩn. Xét các nhận định sau:","statements":[{"key":"a","text":"Ở tế bào nhân thực, quá trình phiên mã và dịch mã xảy ra đồng thời tại một chỗ vì phân tử tiền-$mARN$ ngay khi đang phiên mã dở trong nhân đã được ribosome trong nhân bám vào dịch mã.","ans":false,"exp":"Tế bào nhân thực có màng nhân ngăn cách: phiên mã và chế biến $mARN$ xảy ra trong nhân, sau đó $mARN$ trưởng thành mới đi qua lỗ màng nhân ra tế bào chất dịch mã (khác nhân sơ ghép đôi đồng thời)."},{"key":"b","text":"Đầu $5'$ của tiền-$mARN$ do $ARN\\text{ polymerase II}$ tổng hợp được gắn một mũ 7-metylguanozin giúp bảo vệ $mARN$ khỏi enzyme phân giải và hỗ trợ tiểu phần nhỏ ribosome nhận diện khởi đầu dịch mã.","ans":true,"exp":"Mũ $5'$-cap được gắn rất sớm ngay khi chuỗi ARN vừa vươn dài vài chục nucleotit."},{"key":"c","text":"Đuôi $3'$-polyA gồm khoảng $50 - 250$ nucleotit loại Adenin được gắn sau phiên mã bởi enzyme Poly(A) polymerase mà không cần có trình tự dT tương ứng trên mạch khuôn ADN.","ans":true,"exp":"Đuôi polyA tăng độ bền của $mARN$ trong bào tương và tạo thuận lợi cho xuất bào qua màng nhân."},{"key":"d","text":"Nhờ cơ chế cắt ghép thay thế (Alternative Splicing) tổ hợp lại các đoạn exon khác nhau từ cùng một phân tử tiền-$mARN$, một gen nhân thực có thể tạo ra nhiều chuỗi polipeptit có chức năng biến đổi khác nhau ở các mô.","ans":true,"exp":"Splicing thay thế giải thích vì sao hệ gen người chỉ có $\\approx 20\\,000$ gen mã hóa protein nhưng lại tạo ra hàng trăm nghìn loại protein khác nhau."}],"summaryExp":""},{"id":"TF-021","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Mã Di truyền","stem":"Phân tích đặc điểm và cấu trúc bảng mã di truyền chuẩn trên phân tử $mARN$ của sinh giới:","statements":[{"key":"a","text":"Mã di truyền có tính thoái hóa, tức là nhiều bộ ba khác nhau có thể cùng mã hóa cho một loại axit amin (ngoại trừ $AUG$ cho Methionine và $UGG$ cho Tryptophan mỗi chất chỉ có duy nhất $1$ codon).","ans":true,"exp":"Trong $61$ codon mã hóa cho $20$ axit amin, phần lớn axit amin được mã hóa bởi $2, 3, 4$ hoặc $6$ bộ ba đồng nghĩa."},{"key":"b","text":"Bộ ba $AUG$ vừa là mã mở đầu quy định Methionine (hay formylmethionine ở sinh vật nhân sơ), vừa có thể xuất hiện ở giữa gen để mã hóa thêm các phân tử Methionine nội chuỗi.","ans":true,"exp":"$AUG$ đầu khung đọc được tARN khởi đầu đặc hiệu nhận diện; $AUG$ phía trong được tARN mang Met nội chuỗi kéo dài nhận diện."},{"key":"c","text":"Cả $64$ bộ ba trên $mARN$ đều tương ứng với ít nhất $1$ phân tử $tARN$ mang axit amin trong tế bào sống bình thường.","ans":false,"exp":"Có $3$ bộ ba kết thúc (`5'-UAA-3'`, `5'-UAG-3'`, `5'-UGA-3'`) không mã hóa axit amin và không có $tARN$ bình thường tương ứng mà được các yếu tố giải phóng (Release factor) nhận diện."},{"key":"d","text":"Mã di truyền có tính đặc hiệu tuyệt đối nghĩa là một loại axit amin chỉ có thể do duy nhất một codon quy định trên toàn hệ gen.","ans":false,"exp":"Đó là nhầm khái niệm 'tính thoái hóa' với 'tính đặc hiệu': tính đặc hiệu nghĩa là $1$ bộ ba chỉ mã hóa cho $1$ loại axit amin (không nhập nhằng), chứ $1$ axit amin có thể có nhiều bộ ba."}],"summaryExp":""},{"id":"TF-022","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cơ chế Dịch mã & Ribosome","stem":"Xét hoạt động của phức hệ ribosome trong giai đoạn dịch mã tổng hợp chuỗi polipeptit trên $mARN$ của tế bào sống:","statements":[{"key":"a","text":"Trên khung cấu trúc $3$ vị trí của ribosome theo thứ tự đi qua của $tARN$, $tARN$ mới mang axit amin tiến vào vị trí <strong>A</strong>, tạo liên kết peptit rồi trượt sang vị trí <strong>P</strong>, và thoát ra qua vị trí <strong>E</strong>.","ans":true,"exp":"Trình tự chuẩn tại ribosome trong bước kéo dài là A (Aminoacyl) $\\rightarrow$ P (Peptidyl) $\\rightarrow$ E (Exit)."},{"key":"b","text":"Liên kết giữa bộ ba đối mã (anticodon) trên $tARN$ và bộ ba mã sao (codon) trên $mARN$ tuân theo nguyên tắc bổ sung đối song; ví dụ codon `5'-GCA-3'` khớp với anticodon `3'-CGU-5'`.","ans":true,"exp":"$mARN$ đọc theo chiều $5' \\rightarrow 3'$, còn $tARN$ áp sát đối song theo chiều $3' \\rightarrow 5'$."},{"key":"c","text":"Hoạt tính enzyme Peptidyl transferase xúc tác hình thành liên kết peptit nối các axit amin trong tiểu phần lớn ribosome thực chất do phân tử <strong>$rARN$</strong> (ribozyme) chứ không phải do protein ribosome đảm nhiệm.","ans":true,"exp":"Khám phá cấu trúc tinh thể khẳng định trung tâm peptidyl transferase là lõi $rARN$ ($23S$ ở nhân sơ, $28S$ ở nhân thực) — bằng chứng lớn ủng hộ Thế giới ARN."},{"key":"d","text":"Trên một phân tử $mARN$, nhiều ribosome trượt nối tiếp nhau thành chuỗi Polysome để từ $1$ khuôn $mARN$ tổng hợp ra đồng thời nhiều loại protein hoàn toàn khác hẳn trình tự nhau.","ans":false,"exp":"Polysome giúp tăng năng suất tổng hợp CÙNG MỘT LOẠI chuỗi polipeptit giống hệt nhau trên một bản sao $mARN$ trong thời gian ngắn."}],"summaryExp":""},{"id":"TF-023","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Điều hòa Hoạt động Gen - Operon Lac","stem":"Xét cơ chế điều hòa cảm ứng dương và âm tính của Operon Lac ở vi khuẩn *E. coli* (gồm vùng khởi động $P$, vùng vận hành $O$, các gen cấu trúc $lacZ, lacY, lacA$, cùng gen điều hòa $lacI$ nằm gần đó). Xét các kịch bản đột biến và môi trường sau:","statements":[{"key":"a","text":"Gen điều hòa $lacI$ nằm ngoài operon nhưng sản phẩm protein ức chế do nó mã hóa gắn vào vùng vận hành $O$ khi môi trường KHÔNG có đường Lactose, ngăn cản $ARN\\text{ polymerase}$ trượt qua phiên mã.","ans":true,"exp":"Không có chất cảm ứng allolactose, protein ức chế liên kết bền chặt vào operator $O$ khóa chặt operon ở trạng thái tắt."},{"key":"b","text":"Khi môi trường không có cả Glucose lẫn Lactose, nồng độ cAMP nội bào tăng vọt giúp phức hệ $cAMP-CAP$ bám vào vùng $P$, đủ sức làm các gen $lacZ, lacY, lacA$ phiên mã rầm rộ ngay cả khi vắng mặt Lactose.","ans":false,"exp":"Dù $cAMP-CAP$ gắn vào $P$ để hoạt hóa dương, nhưng vì KHÔNG CÓ Lactose nên protein ức chế $LacI$ vẫn đang bám chặt chẹn ngang vùng $O$ khiến phiên mã vẫn bị khóa chặt!"},{"key":"c","text":"Nếu vi khuẩn mang đột biến mất hoàn toàn khả năng gắn protein ức chế ở vùng vận hành ($lacO^c$ — đột biến vận hành cơ định), operon Lac sẽ luôn bật phiên mã liên tục cả khi môi trường có hay không có Lactose.","ans":true,"exp":"$O^c$ là đột biến tác động cis (chỉ tác động lên operon nằm cùng phân tử ADN đó), mất điểm bám repressor nên biểu hiện liên tục."},{"key":"d","text":"Khi có đột biến vô nghĩa ở gen $lacZ$ tạo bộ ba kết thúc sớm, gen $lacZ$ không tạo được $\\beta$-galactosidase có hoạt tính nhưng các gen phía sau ($lacY, lacA$) vẫn được phiên mã thành một $mARN$ polycistronic khi có Lactose (nếu không xét hiệu ứng phân cực nặng).","ans":true,"exp":"Operon Lac phiên mã chung $1$ phân tử $mARN$ cho cả $lacZ-lacY-lacA$, nên khi dịch mã ribosome tới mã dừng sớm ở $lacZ$ sẽ rụng xuống nhưng vẫn khởi đầu dịch mã được độc lập tại $AUG$ đầu gen $lacY$ và $lacA$."}],"summaryExp":""},{"id":"TF-024","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến Điểm Gen cấu trúc","stem":"Phân tích hậu quả phân tử của các dạng đột biến điểm (liên quan $1$ cặp nucleotit) xảy ra trong vùng mã hóa exon của một gen quy định chuỗi polipeptit:","statements":[{"key":"a","text":"Mọi đột biến thay thế một cặp nucleotit đều làm thay đổi toàn bộ trình tự axit amin kể từ vị trí đột biến trở về sau cho đến tận cuối chuỗi polipeptit.","ans":false,"exp":"Thay thế $1$ cặp nu chỉ tác động tối đa lên $1$ bộ ba (có thể gây đột biến đồng nghĩa không đổi aa, nhầm nghĩa đổi $1$ aa, hoặc vô nghĩa); chỉ mất/thêm không chia hết cho $3$ mới gây dịch khung toàn phần sau đó."},{"key":"b","text":"Đột biến thay thế `A-T` thành `T-A` ở codon thứ $6$ của gen $\\beta$-globin người làm đổi bộ ba `GAG` (Glutamate) thành `GUG` (Valine), gây bệnh thiếu máu hồng cầu hình liềm.","ans":true,"exp":"Đây là ví dụ kinh điển của đột biến nhầm nghĩa (missense mutation) gây biến đổi sâu sắc tính tan của hemoglobin khi thiếu oxy."},{"key":"c","text":"Đột biến vô nghĩa (Nonsense mutation) biến một bộ ba mã hóa axit amin ở giữa gen thành bộ ba kết thúc (`UAA`, `UAG`, `UGA`), tạo ra chuỗi polipeptit ngắn bất thường và thường mất chức năng.","ans":true,"exp":"Càng xuất hiện mã dừng sớm gần đầu $5'$, chuỗi polipeptit bị cắt cụt càng nhiều và thường bị thoái biến nhanh."},{"key":"d","text":"Nếu thêm $1$ cặp nucleotit vào ngay sau codon khởi đầu `AUG` và mất $1$ cặp nucleotit cách đó $6$ nucleotit về phía $3'$, khung đọc đoạn phía sau cả hai vị trí sẽ được phục hồi nguyên vẹn.","ans":true,"exp":"Tổng cộng thêm $1$ và mất $1$ ($+1 - 1 = 0$) nên chỉ làm xáo trộn $2-3$ axit amin nằm giữa hai điểm đột biến, còn toàn bộ phần đuôi gen giữ nguyên khung đọc cũ."}],"summaryExp":""},{"id":"TF-025","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Biểu sinh học (Epigenetics)","stem":"Di truyền biểu sinh nghiên cứu các biến đổi di truyền được qua phân bào nhưng KHÔNG làm thay đổi trình tự nucleotit trong phân tử ADN, chủ yếu thông qua methyl hóa ADN và biến đổi hóa học đuôi protein histon. Xét các nhận định sau:","statements":[{"key":"a","text":"Sự methyl hóa dày đặc các bazơ Cytosine tại đảo `CpG` trong vùng promoter của gen nhân thực thường thu hút phức hệ nén chất nhiễm sắc và làm TẮT phiên mã gen đó.","ans":true,"exp":"Hypermethyl hóa promoter là cơ chế khóa gen dài hạn (ví dụ tắt gen ức chế khối u trong tế bào ung thư hoặc bất hoạt NST X)."},{"key":"b","text":"Acetyl hóa các gốc axit amin Lysine trên đuôi protein Histon (nhờ enzyme HAT) làm trung hòa điện tích dương của histon, làm lực hút với ADN (mang điện âm) lỏng lẻo hơn, tạo chất nhiễm sắc thưa dãn thuận lợi cho phiên mã.","ans":true,"exp":"Euchromatin (nhiễm sắc chất hoạt động phiên mã) giàu nhóm acetyl trên đuôi histon hơn heterochromatin."},{"key":"c","text":"Hiện tượng bất hoạt một nhiễm sắc thể X ở tế bào sinh dưỡng động vật có vú cái (hình thành thể Barr) khiến cả hai NST X trong mỗi tế bào đều hoạt động tăng công suất gấp đôi so với nam giới $XY$.","ans":false,"exp":"Chỉ CÓ MỘT NST X hoạt động trong mỗi tế bào xôma cái, còn một NST X bị đóng xoắn bất hoạt biểu sinh thành thể Barr để cân bằng liều lượng gen giữa $XX$ và $XY$."},{"key":"d","text":"Các dấu ấn biểu sinh (như trong hiện tượng in dấu hệ gen - Genomic Imprinting ở chuột với gen *Igf2*) được thiết lập khác nhau tùy vào giao tử có nguồn gốc từ bố hay mẹ và được duy trì ổn định suốt đời cá thể con.","ans":true,"exp":"Ở động vật có vú, alen *Igf2* nhận từ bố mới được biểu hiện còn bản sao từ mẹ bị im lặng biểu sinh do khác biệt methyl hóa vùng kiểm soát ICR."}],"summaryExp":""},{"id":"TF-026","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Can thiệp ARN (RNAi - siRNA/miRNA)","stem":"Cơ chế can thiệp ARN (RNA interference - RNAi, phát hiện giúp Fire và Mello đoạt giải Nobel Y học 2006) đóng vai trò trung tâm trong điều hòa biểu hiện gen sau phiên mã và bảo vệ tế bào chống virus chứa ARN mạch kép. Xét các nhận định sau:","statements":[{"key":"a","text":"Enzyme Dicer trong tế bào chất cắt phân tử ARN mạch kép (dsRNA) dài thành các đoạn ARN can thiệp nhỏ ($siRNA$) hay $miRNA$ dài khoảng $21-23$ cặp nucleotit.","ans":true,"exp":"Dicer thuộc họ ribonuclease III cắt chính xác các đoạn dsRNA thành duplex ngắn $21-23\\text{ bp}$ có đầu lồi $2$ nu ở $3'$."},{"key":"b","text":"Mạch dẫn đường (guide strand) của $siRNA$ hoặc $miRNA$ gắn vào phức hệ protein Argonaute tạo phức hệ RISC, sau đó bám bổ sung vào phân tử $mARN$ mục tiêu để cắt phân hủy $mARN$ hoặc chặn ribosome dịch mã.","ans":true,"exp":"Nếu khớp bổ sung hoàn hảo thường dẫn đến cắt đứt $mARN$; nếu khớp một phần vùng $3'-UTR$ (thường gặp ở $miRNA$ động vật) sẽ kìm hãm dịch mã và làm mất ổn định $mARN$."},{"key":"c","text":"Cơ chế RNAi tác động trực tiếp làm cắt đứt trình tự phân tử ADN hai mạch bên trong nhân trước khi phiên mã xảy ra.","ans":false,"exp":"RNAi chủ yếu tác động ở giai đoạn SAU PHIÊN MÃ (post-transcriptional) nhắm vào các phân tử $mARN$ đích trong bào tương chứ không cắt ADN mạch kép."},{"key":"d","text":"Tất cả phân tử $miRNA$ đều được vi khuẩn tổng hợp từ các operon nhỏ và không hề có mặt ở động vật hay thực vật đa bào.","ans":false,"exp":"miRNA cực kỳ phổ biến và thiết yếu ở cả thực vật và động vật bậc cao (người có hàng nghìn gen mã hóa miRNA tham gia phát triển phôi và bệnh lý)."}],"summaryExp":""},{"id":"TF-027","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Kỹ thuật PCR & Điện di Gel","stem":"Một phòng xét nghiệm sử dụng kỹ thuật phản ứng chuỗi trùng hợp (PCR) để khuếch đại một đoạn gen đặc trưng dài $600\\text{ bp}$ từ mẫu ADN ban đầu chỉ có $10$ bản sao mạch kép tinh sạch, chạy $30$ chu kỳ nhiệt hoàn chỉnh. Sau đó sản phẩm được nạp lên giếng gel agarose $1.5\\%$ để điện di kiểm tra. Xét các nhận định sau:","statements":[{"key":"a","text":"Mỗi chu kỳ nhiệt của phản ứng PCR chuẩn gồm 3 bước theo thứ tự: Biến tính tách mạch ở $\\approx 94-95^\\circ\\text{C}$ $\\rightarrow$ Bắt cặp mồi đặc hiệu ở $\\approx 50-65^\\circ\\text{C}$ $\\rightarrow$ Kéo dài mạch mới ở $\\approx 72^\\circ\\text{C}$.","ans":true,"exp":"Nhiệt độ tối ưu của enzyme chịu nhiệt $Taq\\text{ polymerase}$ phân lập từ suối nước nóng *Thermus aquaticus* là khoảng $72^\\circ\\text{C}$."},{"key":"b","text":"Sau $30$ chu kỳ PCR lý thuyết, hỗn hợp phản ứng chỉ chứa tối đa $10 \\times 30 = 300$ phân tử ADN đoạn đích.","ans":false,"exp":"Số bản sao ADN tăng theo cấp số nhân $N_0 \\times 2^n$: với $n=30$ chu kỳ, số lượng đạt cỡ $10 \\times 2^{30} \\approx 1.07 \\times 10^{10}$ bản sao!"},{"key":"c","text":"Khi chạy điện di trong điện trường một chiều, phân tử ADN mang điện tích âm (do các nhóm photphat $PO_4^{3-}$ trên khung đường-photphat) nên sẽ di chuyển từ cực ÂM về phía cực DƯƠNG.","ans":true,"exp":"Mật độ điện tích âm trên đơn vị độ dài của ADN gần như đồng nhất nên tốc độ di chuyển chỉ phụ thuộc kích thước mảnh ADN và nồng độ gel."},{"key":"d","text":"Nếu trong cùng một giếng có trộn cả mảnh $600\\text{ bp}$ và một mảnh nhiễu dài $2400\\text{ bp}$, mảnh $600\\text{ bp}$ xuyên qua các lỗ mạng agarose nhanh hơn nên tạo băng nằm gần cực DƯƠNG hơn so với mảnh $2400\\text{ bp}$.","ans":true,"exp":"Phân tử ngắn hơn ít bị mạng lưới gel cản trở nên chạy nhanh và xa hơn về phía cực dương."}],"summaryExp":""},{"id":"TF-028","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Enzyme Cắt giới hạn & Bản đồ Plasmid","stem":"Một phân tử ADN <strong>plasmid dạng vòng</strong> tinh sạch dài $10\\text{ kb}$ được xử lý cắt hoàn toàn bằng các enzyme giới hạn (Restriction Enzymes) $EcoRI$ và $BamHI$, sau đó điện di xác định kích thước mảnh thu được: (1) Cắt chỉ với $EcoRI$ thu $2$ băng kích thước $3\\text{ kb}$ và $7\\text{ kb}$; (2) Cắt chỉ với $BamHI$ thu $1$ băng duy nhất kích thước $10\\text{ kb}$; (3) Cắt đồng thời cả $EcoRI$ và $BamHI$ thu $3$ băng kích thước $1\\text{ kb}$, $3\\text{ kb}$ và $6\\text{ kb}$. Xét các kết luận sau:","statements":[{"key":"a","text":"Plasmid vòng ban đầu sở hữu đúng $2$ vị trí cắt của $EcoRI$ và đúng $1$ vị trí cắt của $BamHI$.","ans":true,"exp":"Với ADN vòng, $k$ vị trí cắt tạo đúng $k$ mảnh: $EcoRI$ cho $2$ mảnh ($2$ điểm cắt cách nhau $3$ và $7\\text{ kb}$); $BamHI$ cho $1$ mảnh thẳng $10\\text{ kb}$ ($1$ điểm cắt)."},{"key":"b","text":"Vị trí cắt của $BamHI$ nằm ngay trên mảnh $7\\text{ kb}$ (tạo bởi $EcoRI$), chia mảnh $7\\text{ kb}$ này thành hai đoạn $1\\text{ kb}$ và $6\\text{ kb}$ còn giữ nguyên mảnh $3\\text{ kb}$.","ans":true,"exp":"Khi cắt chung cho $1, 3, 6\\text{ kb}$ (tổng vẫn $= 10\\text{ kb}$), dễ thấy $3\\text{ kb}$ giữ nguyên và $7\\text{ kb}$ bị chẻ thành $1 + 6\\text{ kb}$."},{"key":"c","text":"Enzyme cắt giới hạn nhận diện các trình tự ADN hoàn toàn ngẫu nhiên không có tính đối xứng hai chiều nên không bao giờ tạo được đầu dính bổ sung.","ans":false,"exp":"Các enzyme giới hạn loại II nhận diện trình tự đối xứng gương (Palindrome, ví dụ EcoRI `5'-GAATTC-3'`) và thường cắt lệch tạo đầu dính (sticky ends) giúp dễ dàng nối chéo với gen lạ."},{"key":"d","text":"Nếu cắt một đoạn ADN <strong>mạch thẳng</strong> dài $10\\text{ kb}$ bằng một enzyme có $2$ vị trí nhận diện trên đoạn đó thì sẽ thu được tối đa $3$ mảnh ADN rời nhau.","ans":true,"exp":"Với phân tử thẳng, $k$ vị trí cắt chia thành $k + 1 = 3$ đoạn."}],"summaryExp":""},{"id":"TF-029","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Công nghệ ADN Tái tổ hợp","stem":"Để sản xuất hàng loạt hormone Insulin người quy mô công nghiệp bằng vi khuẩn *E. coli* biến đổi gen, các nhà khoa học không lấy trực tiếp đoạn ADN gen gốc từ nhân tế bào tuyến tụy để ghép vào plasmid biểu hiện, mà tách $mARN$ trưởng thành của Insulin từ tế bào $\\beta$ đảo tụy rồi phiên mã ngược tạo bản sao $cADN$ đưa vào vector plasmid mang gen chỉ thị kháng ampicillin ($amp^R$) và gen $lacZ$. Xét các nhận định sau:","statements":[{"key":"a","text":"Có thể dùng trực tiếp đoạn ADN nhân tế bào người chèn nguyên vẹn vào plasmid *E. coli* mà vi khuẩn vẫn tự cắt bỏ các intron chính xác để dịch mã ra đúng chuỗi Insulin người.","ans":false,"exp":"Vi khuẩn *E. coli* là sinh vật nhân sơ KHÔNG có bộ máy spliceosome để cắt bỏ các đoạn intron của gen nhân thực, dẫn tới dịch mã sai hoàn toàn nếu dùng ADN gốc; do đó phải dùng $cADN$ vốn đã loại bỏ sẵn intron."},{"key":"b","text":"Quá trình tổng hợp $cADN$ (ADN bổ sung) từ khuôn $mARN$ trưởng thành trong ống nghiệm cần sự xúc tác của enzyme phiên mã ngược Reverse Transcriptase.","ans":true,"exp":"Reverse Transcriptase phiên mã ngược $mARN$ thành mạch $cADN$ đơn, sau đó dùng ADN polymerase tổng hợp thành sợi kép chèn vào vector."},{"key":"c","text":"Trong thí nghiệm sàng lọc xanh-trắng trên đĩa thạch chứa Ampicillin và chất X-gal (cơ chất đổi màu xanh dương dưới tác dụng của enzyme từ gen $lacZ$), những khuẩn lạc có màu TRẮNG thường là các dòng vi khuẩn mang plasmid tái tổ hợp (chèn thành công gen mục tiêu vào giữa vùng đa điểm cắt nằm trong gen $lacZ$).","ans":true,"exp":"Chèn đoạn $cADN$ làm gián đoạn bất hoạt gen $lacZ$ (tạo $\\beta$-galactosidase hỏng không chuyển X-gal thành xanh nên khuẩn lạc giữ màu trắng), trong khi gen $amp^R$ vẫn bảo toàn giúp tế bào sống trên đĩa Ampicillin."},{"key":"d","text":"Vì vi khuẩn phát triển thành dòng khuẩn lạc màu XANH DƯƠNG trên đĩa thạch trên là những vi khuẩn đã chết hết không mang plasmid kháng ampicillin.","ans":false,"exp":"Khuẩn lạc màu XANH DƯƠNG vẫn sống trên Ampicillin tức là đã tiếp nhận plasmid khép vòng rỗng (có $amp^R$ và gen $lacZ$ còn nguyên vẹn chưa bị chèn gen lạ)."}],"summaryExp":""},{"id":"TF-030","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Công nghệ Chỉnh sửa Gen CRISPR-Cas9","stem":"Hệ thống chỉnh sửa hệ gen CRISPR-Cas9 có nguồn gốc từ hệ miễn dịch thích nghi của vi khuẩn chống lại thể thực khuẩn, hiện được cải tiến gồm 2 thành phần chính đưa vào tế bào nhân thực: enzyme nuclease $Cas9$ và một phân tử ARN dẫn đường tổng hợp ($sgRNA$). Xét các nhận định sau:","statements":[{"key":"a","text":"Enzyme $Cas9$ có thể cắt đứt $2$ mạch ADN tại bất kỳ vị trí nào khớp bổ sung với $sgRNA$ mà không cần bất kỳ điều kiện trình tự đặc biệt nào liền kề trên bộ gen đích.","ans":false,"exp":"$Cas9$ (ví dụ *SpCas9*) BẮT BUỘC phải nhận diện trình tự ngắn gọi là motif PAM (ví dụ `5'-NGG-3'`) nằm ngay sát đầu $3'$ của đoạn DNA đích để mở xoắn và cắt."},{"key":"b","text":"Phân tử $sgRNA$ chứa vùng trình tự khoảng $20$ nucleotit thiết kế bổ sung đặc hiệu với đoạn gen mục tiêu giúp định hướng chính xác enzyme $Cas9$ tới đúng một vị trí mong muốn trong hàng tỷ cặp bazơ.","ans":true,"exp":"Khả năng lập trình lại mục tiêu dễ dàng chỉ bằng thay đoạn $20\\text{ nt}$ của $sgRNA$ giúp CRISPR vượt trội hoàn toàn so với ZFN hay TALEN."},{"key":"c","text":"Sau khi $Cas9$ tạo vết cắt đứt gãy mạch kép ($DSB$) tại đích, nếu tế bào sửa chữa theo con đường nối đầu không tương đồng (NHEJ) thường phát sinh lỗi thêm/mất vài nucleotit gây đột biến dịch khung làm bất hoạt (knockout) gen đó.","ans":true,"exp":"NHEJ hoạt động nhanh nhưng dễ sai sót (indels), được tận dụng để tắt gen mục tiêu hiệu quả."},{"key":"d","text":"Nếu cung cấp đồng thời một mạch khuôn ADN sửa đổi có hai đầu tương đồng với vùng cắt, tế bào có thể dùng cơ chế sửa chữa tái tổ hợp tương đồng (HDR) để gắn chèn chính xác trình tự mới thay thế alen bệnh.","ans":true,"exp":"Con đường HDR sửa sai chính xác cao (nổi trội ở pha $S/G_2$) cho phép sửa chữa đột biến điểm hoặc chèn đoạn gen định vị (knock-in)."}],"summaryExp":""},{"id":"TF-031","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chu kỳ Tế bào & Điểm Kiểm soát","stem":"Chu kỳ phân chia của một tế bào nhân thực động vật có vú được giám sát nghiêm ngặt bởi các điểm kiểm soát (Checkpoints) và phức hệ enzyme $Cyclin - Cdk$. Xét các nhận định sau:","statements":[{"key":"a","text":"Tại điểm kiểm soát $G_1$ (điểm giới hạn ở cuối $G_1$), nếu ADN bị đứt gãy nghiêm trọng do tia X, protein ức chế khối u $p53$ tích tụ kích hoạt gen $p21$ ức chế $Cdk$, làm tế bào tạm dừng ở $G_1$ để sửa sai ADN hoặc kích hoạt tự chết theo chương trình (Apoptosis).","ans":true,"exp":"$p53$ được mệnh danh là 'người bảo vệ hệ gen', ngăn không cho tế bào mang ADN hỏng bước vào pha $S$ nhân đôi."},{"key":"b","text":"Phức hệ MPF (Cyclin B - Cdk1) đạt nồng độ hoạt tính đỉnh cao ở cuối pha $G_2$ để thúc đẩy tế bào bước vào pha $M$ (nguyên phân: tan màng nhân, co xoắn NST và hình thành thoi phân bào).","ans":true,"exp":"Đến cuối kỳ giữa/đầu kỳ sau, phức hệ APC/C đánh dấu ubiquitin phân hủy Cyclin B khiến Cdk1 tắt hoạt tính để tế bào thoát khỏi nguyên phân."},{"key":"c","text":"Hầu hết các tế bào thần kinh trưởng thành trong não người duy trì ở trạng thái biệt hóa sâu không còn phân chia, được xếp vào pha nghỉ $G_0$ (tách khỏi chu kỳ tế bào ở điểm kiểm soát $G_1$).","ans":true,"exp":"Tế bào vào $G_0$ vẫn chuyển hóa và truyền xung điện mạnh mẽ nhưng ngừng nhân đôi ADN và phân bào."},{"key":"d","text":"Điểm kiểm soát $M$ (kỳ giữa $\\rightarrow$ kỳ sau) đảm bảo nhân đôi xong mọi ty thể, còn nếu có một NST kép chưa kịp bám vào tơ vô sắc thì NST đó sẽ lập tức bị tách ngay ra đẩy bừa về hai cực.","ans":false,"exp":"Điểm kiểm soát thoi vô sắc (kỳ giữa-kỳ sau) giữ chặt các crômatit bằng cách ức chế $APC/C$ nếu thậm chí chỉ MỘT tâm động chưa gắn vi ống hai cực đúng cách, ngăn ngừa lệch bội."}],"summaryExp":""},{"id":"TF-032","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nguyên phân & Hàm lượng ADN","stem":"Theo dõi $1$ tế bào lưỡng bội bình thường của ruồi giấm ($2n = 8$) có hàm lượng ADN nhân ở pha $G_1$ quy ước là $2c$ tiến hành $1$ lần nguyên phân chuẩn. Xét các nhận định sau về số NST, số crômatit và hàm lượng ADN qua các kỳ:","statements":[{"key":"a","text":"Ở pha $G_2$ (ngay sau khi hoàn tất nhân đôi ở pha $S$), nhân tế bào vẫn có $8$ NST nhưng mỗi NST ở trạng thái KÉP gồm $2$ crômatit chị em dính nhau ở tâm động, tổng là $16$ crômatit và hàm lượng ADN bằng $4c$.","ans":true,"exp":"Nhân đôi ADN ở pha $S$ nhân đôi hàm lượng ADN ($2c \\to 4c$) và chuyển $8$ NST đơn thành $8$ NST kép."},{"key":"b","text":"Tại kỳ giữa nguyên phân, tất cả $8$ NST kép co xoắn cực đại và xếp thành HAI hàng song song đối xứng nhau trên mặt phẳng xích đạo của thoi phân bào.","ans":false,"exp":"Trong NGUYÊN PHÂN, các NST kép xếp thành MỘT hàng trên mặt phẳng xích đạo ở kỳ giữa (xếp HAI hàng kép của từng cặp tương đồng chỉ xảy ra ở kỳ giữa GIẢM PHÂN I!)."},{"key":"c","text":"Tại kỳ sau nguyên phân, mỗi cặp crômatit chị em tách rời hoàn toàn ở tâm động để tiến về 2 cực: khi đó trong một tế bào đang chia có $16$ NST đơn, $0$ crômatit và tổng ADN vẫn là $4c$.","ans":true,"exp":"Khi 2 crômatit tách nhau ở kỳ sau, mỗi chiếc lập tức được tính là $1$ NST đơn độc lập nên số lượng trong 1 tế bào chưa cắt tế bào chất là $4n = 16$ NST đơn."},{"key":"d","text":"Kết thúc nguyên phân (sau phân chia tế bào chất), mỗi trong $2$ tế bào con nhận được đúng $8$ NST đơn và hàm lượng ADN phục hồi về $2c$ y hệt tế bào mẹ ban đầu.","ans":true,"exp":"Nguyên phân bảo toàn nguyên vẹn bộ NST $2n$ qua các thế hệ tế bào sinh dưỡng."}],"summaryExp":""},{"id":"TF-033","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giảm phân & Trao đổi chéo","stem":"Xét $1$ tế bào sinh dục chín có bộ NST $2n = 14$ (với $7$ cặp tương đồng) tiến hành giảm phân bình thường tạo giao tử. Hàm lượng ADN nhân ở pha $G_1$ trước giảm phân là $2c$. Xét các nhận định sau:","statements":[{"key":"a","text":"Ở kỳ đầu của giảm phân I, các cặp NST kép tương đồng tiếp hợp theo từng cặp tạo bộ bốn crômatit (tetrad) và có thể trao đổi chéo những đoạn tương ứng giữa các crômatit KHÔNG chị em.","ans":true,"exp":"Trao đổi chéo tại các điểm bắt chéo (chiasmata) tạo biến dị tổ hợp hoán vị gen và giữ cặp tương đồng dính nhau để định hướng chính xác."},{"key":"b","text":"Khi kết thúc lần phân bào giảm phân I (tạo $2$ tế bào con ở kỳ cuối I), mỗi tế bào con chứa $n = 7$ NST KÉP ($14$ crômatit) và mang hàm lượng ADN bằng $2c$.","ans":true,"exp":"Giảm phân I làm giảm một nửa số NST ($2n$ kép $\\to n$ kép), nên hàm lượng ADN từ $4c$ về $2c$."},{"key":"c","text":"Tại kỳ sau giảm phân I, xảy ra hiện tượng tách dọc tâm động của mỗi NST kép khiến các crômatit chị em chia làm hai nửa đi về hai cực tế bào.","ans":false,"exp":"Ở kỳ sau I, các tâm động KHÔNG tách; hai NST kép trong cặp tương đồng trượt tách nhau đi về 2 cực. Chỉ đến kỳ sau II tâm động mới tách đôi!"},{"key":"d","text":"Kết thúc toàn bộ quá trình giảm phân II, từ $1$ tế bào sinh tinh ban đầu thu được $4$ tế bào con đơn bội, mỗi tế bào có $n = 7$ NST đơn và hàm lượng ADN bằng $0.5c$.","ans":false,"exp":"Mỗi tế bào con giảm phân II nhận $n = 7$ NST đơn và hàm lượng ADN bằng $1c$ (một nửa so với mức $2c$ của tế bào $G_1$ ban đầu, không phải $0.5c$)."}],"summaryExp":""},{"id":"TF-034","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Số loại Giao tử & Quá trình Tạo Trứng - Tinh trùng","stem":"Xét một cá thể động vật đực và một cá thể cái cùng loài có kiểu gen $Aa Bb Dd \\frac{EG}{eg}$ ($3$ cặp đầu phân ly độc lập, cặp NST thứ $4$ mang $2$ gen liên kết $E/e$ và $G/g$; bộ NST chung $2n = 8$). Xét các nhận định định lượng sau:","statements":[{"key":"a","text":"Khi xét trên phạm vi TOÀN CƠ THỂ cá thể đực, nếu giảm phân bình thường và chỉ xảy ra trao đổi chéo giữa $E$ và $G$ ở một tỷ lệ tế bào sinh tinh, số loại tinh trùng TỐI ĐA có thể tạo thành là $2^3 \\times 2 = 16$ loại.","ans":false,"exp":"Mỗi cặp $Aa, Bb, Dd$ độc lập cho $2$ loại $\\Rightarrow 2^3 = 8$; cặp $EG/eg$ có hoán vị cho $4$ loại giao tử (`EG, eg, Eg, eG`), do đó tổng số loại $= 8 \\times 4 = 32$ loại giao tử tối đa!"},{"key":"b","text":"Nếu chỉ xét <strong>MỘT tế bào sinh tinh</strong> duy nhất có kiểu gen trên giảm phân có hoán vị gen tại cặp $EG/eg$, số loại tinh trùng thực tế thu được từ $1$ tế bào đó chỉ tối đa là $4$ loại (với tỉ lệ $1:1:1:1$).","ans":true,"exp":"$1$ tế bào sinh tinh chỉ tạo $4$ tinh trùng sau giảm phân II; nếu có hoán vị ở 1 cặp và các cặp kia phân ly độc lập theo một cách cố định, 4 sản phẩm tối đa mang $4$ tổ hợp giao tử."},{"key":"c","text":"Từ <strong>MỘT tế bào sinh trứng</strong> duy nhất của cá thể cái có kiểu gen trên giảm phân bình thường tạo giao tử, dù có hoán vị gen xảy ra ở bao nhiêu điểm đi nữa, kết quả vẫn chỉ thu được DUY NHẤT $1$ loại tế bào trứng (kèm $3$ thể cực thoái biến).","ans":true,"exp":"Phân bào chất không đều trong giảm phân tạo noãn dồn toàn bộ bào tương về $1$ tế bào trứng duy nhất $\\Rightarrow 1$ kiểu gen trứng duy nhất từ $1$ tế bào sinh trứng."},{"key":"d","text":"Giả sử $500$ tế bào sinh tinh của cá thể đực tiến hành giảm phân hoàn chỉnh thì thu được tất cả $2000$ tinh trùng có khả năng tham gia thụ tinh; còn $500$ tế bào sinh trứng giảm phân chỉ thu được $500$ tế bào trứng.","ans":true,"exp":"Tỷ lệ hiệu suất $1$ tế bào sinh dục chín $\\rightarrow 4$ tinh trùng vs $1$ trứng."}],"summaryExp":""},{"id":"TF-035","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Rối loạn Phân ly NST (GP I vs GP II)","stem":"Ở người, bệnh mù màu đỏ-lục do gen lặn $m$ trên vùng không tương đồng của NST X quy định (mắt nhìn màu bình thường do alen trội $M$). Một cặp vợ chồng có mắt nhìn màu BÌNH THƯỜNG (chồng $X^M Y$, vợ mang kiểu gen dị hợp $X^M X^m$) sinh ra một người con trai bị <strong>hội chứng Klinefelter ($XXY$) VÀ mắc bệnh mù màu</strong>. Biết không có đột biến gen phát sinh mới và không có hoán vị vùng chứa gen. Xét các suy luận về cơ chế gây rối loạn sau:","statements":[{"key":"a","text":"Người con trai mắc đồng thời Klinefelter và mù màu bắt buộc phải mang kiểu gen là $X^m X^m Y$.","ans":true,"exp":"Là con trai Klinefelter có $2$ NST X và $1$ Y; để biểu hiện tính trạng lặn mù màu thì cả $2$ NST X đều phải mang alen lặn $X^m$ (vì bố $X^M Y$ không có $X^m$)."},{"key":"b","text":"Cặp NST $X^m X^m$ trong hợp tử chắc chắn có nguồn gốc từ trứng bất thường ($n+1$) của người MẸ do rối loạn không phân ly ở lần phân bào <strong>giảm phân II</strong> (tại cặp crômatit $X^m X^m$).","ans":true,"exp":"Mẹ $X^M X^m$ chỉ tạo được trứng mang hai bản sao giống hệt $X^m X^m$ khi xảy ra không phân ly $2$ crômatit chị em ở GP II (còn nếu hỏng ở GP I, trứng $n+1$ sẽ là $X^M X^m$, kết hợp với $Y$ tạo $X^M X^m Y$ nhìn màu bình thường!)."},{"key":"c","text":"Nếu người mẹ bị rối loạn không phân ly ở <strong>giảm phân I</strong> (còn bố hoàn toàn bình thường), giao tử trứng chứa $2$ NST X đó kết hợp tinh trùng $Y$ có thể sinh ra con trai Klinefelter $X^m X^m Y$ mù màu.","ans":false,"exp":"Hỏng GP I ở mẹ $X^M X^m$ tạo trứng mang $X^M X^m$ nên con $X^M X^m Y$ sẽ KHÔNG bị mù màu nhờ có $X^M$ trội."},{"key":"d","text":"Sự không phân ly cặp NST giới tính trong giảm phân II ở người BỐ ($X^M Y$) có thể tạo ra tinh trùng chứa hai chiếc $Y$ ($YY$), khi thụ tinh với trứng bình thường tạo hợp tử $XYY$ (hội chứng Jacobs).","ans":true,"exp":"Chỉ có rối loạn GP II ở bố (không tách 2 crômatit Y) mới tạo được giao tử $YY$ (và $XX$ hoặc $O$)."}],"summaryExp":""},{"id":"TF-036","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến Cấu trúc: Mất đoạn & Lặp đoạn","stem":"Nghiên cứu hai dạng đột biến cấu trúc nhiễm sắc thể làm thay đổi số lượng gen trên mỗi NST là Mất đoạn và Lặp đoạn. Xét các nhận định sau:","statements":[{"key":"a","text":"Cơ chế phổ biến hàng đầu làm phát sinh ĐỒNG THỜI một NST bị lặp đoạn và một NST bị mất đoạn trong giảm phân là sự tiếp hợp lệch và trao đổi chéo KHÔNG CÂN giữa $2$ crômatit khác nguồn gốc trong cặp tương đồng.","ans":true,"exp":"Khi trượt lệch các trình tự lặp tương đồng trên 2 crômatit rồi trao đổi chéo, một chiếc nhận thêm đoạn thành lặp đoạn còn chiếc kia mất đoạn tương ứng."},{"key":"b","text":"Ở người, đột biến mất một đoạn nhỏ trên vai ngắn của NST số $5$ ($5p-$) gây hội chứng tiếng mèo kêu (Cri-du-chat) với chậm phát triển trí tuệ nghiêm trọng.","ans":true,"exp":"Đột biến mất đoạn làm mất các gen thiết yếu ở trạng thái đơn bội dẫn đến rối loạn phát triển nặng hoặc gây chết."},{"key":"c","text":"Đột biến lặp đoạn gen *Bar* trên NST X ở ruồi giấm làm tăng số lượng mặt đơn giúp mắt ruồi to gấp đôi mắt ruồi kiểu dại bình thường.","ans":false,"exp":"Lặp đoạn $16A$ (gen *Bar*) ở ruồi giấm làm mắt DẸT NHỎ đi (giảm số mặt đơn); lặp càng nhiều mắt càng dẹt nhỏ."},{"key":"d","text":"Trong tiến hóa hệ gen lâu dài, lặp đoạn gen có ý nghĩa đặc biệt vì bản sao gen dư thừa có thể tích lũy đột biến phân hóa tạo thành gen mới mang chức năng mới mà bản sao gốc vẫn đảm nhiệm chức năng thiết yếu cũ.","ans":true,"exp":"Lặp đoạn là động lực chủ yếu hình thành các họ đa gen (như họ gen globin $\\alpha, \\beta$ ở người)."}],"summaryExp":""},{"id":"TF-037","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến Cấu trúc: Đảo đoạn & Chuyển đoạn","stem":"Phân tích các dạng đột biến cấu trúc NST giữ nguyên hoặc thay đổi vị trí phân bố gen là Đảo đoạn và Chuyển đoạn NST:","statements":[{"key":"a","text":"Đột biến đảo đoạn làm xoay ngược $180^\\circ$ một đoạn NST thường không làm tăng hay giảm số lượng vật chất di truyền trên NST nhưng có thể làm thay đổi mức độ hoạt động của gen gần điểm đứt gãy (hiệu ứng vị trí).","ans":true,"exp":"Đặt gen gần vùng dị nhiễm sắc hoặc tách khỏi enhancer cũ làm thay đổi biểu hiện gen; đồng thời giúp tạo biến dị hình thái khi lai."},{"key":"b","text":"Cá thể mang đột biến đảo đoạn dị hợp tử thường tạo được tỉ lệ lớn giao tử mất đoạn/lặp đoạn không sống sót nếu xảy ra trao đổi chéo bên trong vòng đảo khi giảm phân, góp phần cách ly sinh sản hình thành loài mới.","ans":true,"exp":"Trao đổi chéo trong vòng đảo làm giảm khả năng sinh sản của con lai dị hợp đảo đoạn giữa các quần thể (cách ly sau hợp tử)."},{"key":"c","text":"Đột biến chuyển đoạn tương hỗ giữa NST số $9$ và NST số $22$ ở người hình thành nhiễm sắc thể Philadelphia gây bệnh bạch cầu tủy mạn (CML) là do thiếu vitamin C bẩm sinh trong khẩu phần ăn.","ans":false,"exp":"NST Philadelphia $t(9;22)$ là đột biến chuyển đoạn tương hỗ tạo gen dung hợp *BCR-ABL* sinh enzyme tyrosine kinase hoạt động quá mức thúc đẩy tế bào tủy tăng sinh ác tính, không phải do thiếu vitamin C."},{"key":"d","text":"Một người mang chuyển đoạn hòa hợp tâm (Robertsonian) cân bằng giữa NST $14$ và $21$ tuy chỉ có $45$ NST trong tế bào xôma nhưng vẫn khỏe mạnh bình thường vì hầu như không mất gen thiết yếu, song lại có nguy cơ cao sinh con mắc hội chứng Down.","ans":true,"exp":"Người mang $t(14;21)$ có thể truyền đồng thời NST hợp nhất $14/21$ cùng NST $21$ bình thường sang con tạo kiểu nhân $46$ NST với $3$ bản sao vùng gen $21q$ (Down do chuyển đoạn)."}],"summaryExp":""},{"id":"TF-038","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến Số lượng NST - Lệch bội ở Người","stem":"Nghiên cứu các hội chứng lệch bội thường gặp ở người (như Down, Turner, Klinefelter, Siêu nữ XXX). Xét các nhận định sau:","statements":[{"key":"a","text":"Hội chứng Down ($2n+1 = 47$ NST với $3$ NST số $21$) có tần suất xuất hiện tăng nhanh theo độ tuổi sinh con của người mẹ (đặc biệt trên $35$ tuổi) do noãn bào cấp I bị dừng kéo dài ở kỳ đầu I làm tăng nguy cơ rối loạn phân ly NST.","ans":true,"exp":"Tế bào trứng người dừng ở kỳ đầu I từ giai đoạn phôi thai tới tận lúc rụng trứng hàng chục năm sau dễ hỏng phức hệ gắn kết crômatit (cohesin)."},{"key":"b","text":"Bệnh nhân mắc hội chứng Turner có kiểu nhân $45, XO$ là nữ giới thường có vóc dáng thấp, cổ bạnh, vô sinh và khi nhuộm nhân tế bào niêm mạc miệng hoàn toàn KHÔNG phát hiện thể Barr.","ans":true,"exp":"Số thể Barr luôn bằng $\\text{số NST X} - 1$. Với $XO$, có $1 - 1 = 0$ thể Barr."},{"key":"c","text":"Trong tế bào xôma của người nam mắc hội chứng Klinefelter ($47, XXY$), khi xét nghiệm tiêu bản tế bào niêm mạc miệng cũng KHÔNG thấy xuất hiện thể Barr vì giới tính là nam có NST Y.","ans":false,"exp":"Bệnh nhân $XXY$ mang $2$ NST X nên vẫn bất hoạt $1$ NST X tạo thành $1$ thể Barr giống nữ $XX$ bình thường!"},{"key":"d","text":"Ở người, các đột biến thể một ($2n-1$) trên nhiễm sắc thể thường hầu như đều bị đào thải gây sẩy thai sớm từ giai đoạn phôi, trong khi thể một trên NST giới tính X ($XO$) lại có thể sống sót tới tuổi trưởng thành.","ans":true,"exp":"Cơ chế bất hoạt X (tế bào bình thường chỉ dùng liều $1$ NST X hoạt động) giải thích vì sao thiếu $1$ chiếc X ít gây chết phôi hơn thiếu $1$ NST thường."}],"summaryExp":""},{"id":"TF-039","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tính Xác suất Hợp tử Lệch bội","stem":"Ở một loài động vật ($2n$), người bố bình thường có $20\\%$ tế bào sinh tinh bị rối loạn không phân ly cặp NST giới tính $XY$ ở giảm phân I (giảm phân II bình thường), các tế bào còn lại giảm phân bình thường. Người mẹ hoàn toàn bình thường giảm phân cho $100\\%$ trứng bình thường ($n$). Các giao tử đều có khả năng thụ tinh như nhau. Xét các xác suất hợp tử $F_1$ thu được:","statements":[{"key":"a","text":"Tỉ lệ loại tinh trùng bất thường mang cả hai NST giới tính ($XY$) do người bố tạo ra bằng $20\\%$ tổng số tinh trùng.","ans":false,"exp":"$20\\%$ tế bào sinh tinh hỏng GP I tạo $50\\%$ tinh trùng $XY$ và $50\\%$ tinh trùng khuyết $O$ $\\Rightarrow$ tỷ lệ tinh trùng $XY = 20\\% \\times 0.5 = 10\\%$ (còn $O = 10\\%$, $X = 40\\%$, $Y = 40\\%$)."},{"key":"b","text":"Tỉ lệ tinh trùng bình thường mang $1$ NST $X$ trong tổng số tinh trùng của người bố chiếm đúng $40\\%$.","ans":true,"exp":"$80\\%$ tế bào sinh tinh giảm phân bình thường tạo $40\\%$ tinh trùng $X$ và $40\\%$ tinh trùng $Y$."},{"key":"c","text":"Xác suất cặp bố mẹ này sinh được một hợp tử mang kiểu gen $XXY$ là $10\\%$, xác suất sinh hợp tử $XO$ cũng bằng $10\\%$.","ans":true,"exp":"Vì $100\\%$ trứng mang $X$, kết hợp $10\\% XY \\to 10\\% XXY$ và kết hợp $10\\% O \\to 10\\% XO$."},{"key":"d","text":"Tỉ lệ hợp tử bình thường ($XX$ hoặc $XY$) ở đời con $F_1$ chỉ bằng $60\\%$ tổng số hợp tử.","ans":false,"exp":"Tổng tinh trùng bình thường ($X + Y$) $= 40\\% + 40\\% = 80\\% \\Rightarrow$ xác suất sinh hợp tử bình thường bằng $80\\%$ (gồm $40\\% XX$ và $40\\% XY$)."}],"summaryExp":""},{"id":"TF-040","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến Tự đa bội & Ứng dụng","stem":"Trong chọn tạo giống cây trồng, hóa chất Cônsixin (Colchicine) được sử dụng phổ biến để gây đột biến tạo các dòng cây tự đa bội mang nhiều đặc tính nông học quý giá. Xét các nhận định sau:","statements":[{"key":"a","text":"Cơ chế tác động chính của Cônsixin là trực tiếp cắt đứt các gen quy định chiều cao thấp để nối thêm gen tăng năng suất vào ADN.","ans":false,"exp":"Cônsixin gắn vào tiểu phần tubulin ức chế sự trùng hợp vi ống hình thành thoi phân bào, khiến bộ NST đã nhân đôi không thể phân ly về 2 cực $\\rightarrow$ tăng gấp bội số NST trong 1 nhân ($2n \\to 4n$)."},{"key":"b","text":"Khi lai cây dưa hấu tứ bội ($4n$) làm mẹ với cây dưa hấu lưỡng bội ($2n$) làm bố thu được cây dưa hấu tam bội ($3n$) phát triển thân lá lớn và tạo quả không hạt.","ans":true,"exp":"Tế bào tam bội ($3n$) có 3 chiếc mỗi cặp NST không thể chia đều đồng bộ trong giảm phân I, sinh giao tử lệch bội hỏng hầu hết $\\rightarrow$ không hạt."},{"key":"c","text":"Thể tự đa bội thường gặp và có giá trị thực tế rất cao ở thực vật (rau ăn lá, củ, cây ăn quả) vì có kích thước cơ quan sinh dưỡng to lớn, tế bào rộng, tổng hợp chất hữu cơ mạnh mẽ.","ans":true,"exp":"Tăng số bản sao hệ gen (nhân đa bội) tương ứng với tăng kích thước tế bào và năng suất sinh khối ở nhiều loài thực vật."},{"key":"d","text":"Để nhân giống nhanh và duy trì nguyên vẹn đặc điểm tốt của một cây chuối hay cây nho tam bội ($3n$) không hạt, người trồng trọt sử dụng các phương pháp sinh sản vô tính như nuôi cấy mô hoặc giâm/tách chồi.","ans":true,"exp":"Do $3n$ bất thụ hữu tính, sinh sản sinh dưỡng giúp nhân rộng vô hạn bản sao di truyền $3n$ ưu việt."}],"summaryExp":""},{"id":"TF-041","topic":"cellular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thể Dị đa bội & Thí nghiệm Karpechenko","stem":"Nhà di truyền học Liên Xô G.D. Karpechenko (1927) đã tiến hành lai xa giữa cây Củ cải (*Raphanus sativus*, $2n = 18R$) với cây Bắp cải (*Brassica oleracea*, $2n = 18B$). Cây lai $F_1$ thu được có $18$ NST ($9R + 9B$) sinh trưởng khỏe nhưng bị bất thụ hoàn toàn. Tuy nhiên, một số cây $F_1$ tự phát đa bội hóa bộ NST đã tạo thành loài thực vật mới hữu thụ đặt tên là *Raphanobrassica*. Xét các nhận định sau:","statements":[{"key":"a","text":"Nguyên nhân trực tiếp khiến cây lai $F_1$ ($9R + 9B$) bị bất thụ là do $9$ NST của củ cải không có $9$ NST tương đồng từ bắp cải để bắt cặp tiếp hợp bình thường ở kỳ đầu giảm phân I.","ans":true,"exp":"Hai bộ NST khác loài không tương đồng khiến quá trình phân ly trong giảm phân rối loạn hoàn toàn, không tạo được giao tử sống."},{"key":"b","text":"Cây song nhị bội *Raphanobrassica* hữu thụ mang tổng cộng $36$ NST lưỡng bội của cả hai loài ($18R + 18B$), khi giảm phân bình thường sẽ tạo ra mỗi giao tử chứa đúng $9R + 9B = 18$ NST.","ans":true,"exp":"Mỗi NST đều có bạn cặp tương đồng chính mình để tiếp hợp và phân ly chuẩn tạo giao tử lưỡng bội ghép $(n_R + n_B) = 18$."},{"key":"c","text":"Ở cây *Raphanobrassica* ($18R + 18B$), do số NST tổng cộng bằng $36$ nên bộ NST được xếp vào dạng tự tứ bội ($4n = 36$) thuộc cùng một loài củ cải ban đầu.","ans":false,"exp":"*Raphanobrassica* là thể SONG NHỊ BỘI (dị đa bội $2n_1 + 2n_2$), mang hai bộ lưỡng bội của hai loài khác nhau, đã cách ly sinh sản với cả củ cải ($2n=18$) và bắp cải ($2n=18$) thành một loài mới."},{"key":"d","text":"Phương pháp lai xa kết hợp đa bội hóa (tạo thể song nhị bội) có vai trò cực kỳ quan trọng trong tiến hóa lịch sử của thực vật hạt kín (như nguồn gốc lúa mì hiện đại $6n = 42$).","ans":true,"exp":"Đa số loài thực vật có hoa ngày nay (như lúa mì *Triticum aestivum*, bông vải, cải dầu) có lịch sử hình thành qua dị đa bội hóa."}],"summaryExp":""},{"id":"TF-042","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phép lai Thể Tứ bội ($4n$)","stem":"Ở một loài thực vật tứ bội ($4n$), alen $A$ quy định thân cao trội hoàn toàn so với alen $a$ quy định thân thấp. Giả sử các cây tứ bội giảm phân bình thường chỉ tạo giao tử lưỡng bội ($2n$) hữu thụ hoàn toàn. Thực hiện phép lai $P: AAaa \\times Aaaa$. Mỗi nhận định sau Đúng hay Sai?","statements":[{"key":"a","text":"Cây có kiểu gen $AAaa$ khi giảm phân cho tỉ lệ các loại giao tử lưỡng bội là $\\frac{1}{6} AA : \\frac{4}{6} Aa : \\frac{1}{6} aa$.","ans":true,"exp":"Áp dụng cách viết 6 cạnh của hình tứ diện/chữ nhật với 4 alen ($A, A, a, a$): $\\binom{4}{2} = 6$ cặp tạo $1 AA : 4 Aa : 1 aa$."},{"key":"b","text":"Cây có kiểu gen $Aaaa$ khi giảm phân chỉ tạo ra $2$ loại giao tử với tỉ lệ bằng nhau là $\\frac{1}{2} Aa : \\frac{1}{2} aa$.","ans":true,"exp":"Cây có $1 A$ và $3 a$ ghép $2$ tạo $3 Aa : 3 aa = \\frac{1}{2} Aa : \\frac{1}{2} aa$."},{"key":"c","text":"Ở đời con $F_1$ của phép lai $AAaa \\times Aaaa$, tỉ lệ cây thân thấp ($aaaa$) thu được bằng $\\frac{1}{24}$.","ans":false,"exp":"Tỉ lệ cây thân thấp $aaaa = \\frac{1}{6}(aa) \\times \\frac{1}{2}(aa) = \\frac{1}{12}$, suy ra tỉ lệ thân cao là $\\frac{11}{12}$."},{"key":"d","text":"Nếu cho các cây $F_1$ thân cao ở trên ($\\frac{1}{11} AAAa + \\frac{5}{11} AAaa + \\frac{5}{11} Aaaa$) lại tự tạo giao tử, tất cả các cây $F_1$ thân cao đều có thể tự thụ sinh ra toàn $100\\%$ thân cao ở $F_2$.","ans":false,"exp":"Chỉ cây $AAAa$ ($F_1$) tạo toàn giao tử mang $A$ ($\\frac{1}{2}AA:\\frac{1}{2}Aa$) mới sinh $100\\%$ thân cao; các cây $AAaa$ và $Aaaa$ đều tạo được giao tử $aa$ nên khi tự thụ đều tạo thêm cây thân thấp $aaaa$."}],"summaryExp":""},{"id":"TF-043","topic":"cellular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc Siêu hiển vi Nhiễm sắc thể","stem":"Ở tế bào nhân thực, phân tử ADN rất dài (tổng chiều dài $\\approx 2\\text{ m}$ trong nhân người đường kính chỉ vài micromet) được đóng gói gọn gàng qua các bậc cấu trúc siêu hiển vi của nhiễm sắc thể. Xét các nhận định sau:","statements":[{"key":"a","text":"Đơn vị cấu trúc cơ bản đầu tiên của nhiễm sắc thể là Nucleosome, gồm một lõi $8$ phân tử protein Histon ($2$ bản sao mỗi loại $H2A, H2B, H3, H4$) được $1$ đoạn ADN dài khoảng $146-147$ cặp nucleotit quấn quanh $1.75$ vòng.","ans":true,"exp":"Cấu trúc chuỗi hạt nucleosome làm đường kính sợi cơ bản đạt khoảng $10 - 11\\text{ nm}$."},{"key":"b","text":"Protein Histon giàu các axit amin mang điện tích ÂM như Glutamate và Aspartate nên đẩy mạnh phân tử ADN để tạo vùng giãn xoắn.","ans":false,"exp":"Protein Histon rất giàu axit amin kiềm mang điện tích DƯƠNG (Lysine, Arginine) giúp liên kết tĩnh điện chặt chẽ với khung đường-photphat mang điện tích ÂM của phân tử ADN."},{"key":"c","text":"Sợi cơ bản ($11\\text{ nm}$) tiếp tục cuộn xoắn với sự tham gia của histon $H1$ thành sợi nhiễm sắc đường kính $30\\text{ nm}$, rồi vùng xếp cuộn $300\\text{ nm}$ và sợi crômatit $700\\text{ nm}$.","ans":true,"exp":"Quá trình xoắn nhiều cấp giúp thu gọn chiều dài ADN tới hơn $10\\,000$ lần ở NST kỳ giữa."},{"key":"d","text":"Ở kỳ giữa của nguyên phân, NST co xoắn cực đại giúp quan sát rõ nhất hình thái, số lượng và kích thước đặc trưng cho loài (như lập bộ nhiễm sắc thể đồ - Karyotype).","ans":true,"exp":"Co xoắn cực đại ở kỳ giữa vừa giúp phân ly không đứt rối NST về 2 cực vừa thuận lợi cho xét nghiệm di truyền tế bào."}],"summaryExp":""},{"id":"TF-044","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh học Ung thư & Gen Kiểm soát Chu kỳ","stem":"Sự phát sinh ung thư là quá trình tích lũy nhiều đột biến liên tiếp tại hai nhóm gen chủ chốt kiểm soát chu kỳ tế bào: Tiền gen ung thư (Proto-oncogenes, như *Ras*, *Myc*) và Gen ức chế khối u (Tumor suppressor genes, như *Rb*, *p53*). Xét các nhận định sau:","statements":[{"key":"a","text":"Đột biến biến đổi một Tiền gen ung thư bình thường thành Gen ung thư hoạt động quá mức (Oncogene) thường có tính chất như một đột biến TRỘI ở cấp độ tế bào (chỉ cần $1$ trong $2$ alen bị đột biến tăng chức năng đã thúc đẩy tăng sinh).","ans":true,"exp":"Ví dụ một bản sao *Ras* đột biến khóa ở trạng thái gắn GTP liên tục phát tín hiệu phân bào bất chấp không có yếu tố tăng trưởng."},{"key":"b","text":"Với gen ức chế khối u (như gen $Rb$ trong bệnh u nguyên bào võng mạc), ở người bình thường chỉ cần $1$ alen lành còn lại vẫn đủ tạo protein kìm hãm tăng sinh; theo giả thuyết 'hai cú đánh' của Knudson, tế bào thường chỉ mất kiểm soát khi CẢ HAI alen của gen ức chế khối u bị bất hoạt.","ans":true,"exp":"Đây là lý do người thừa hưởng sẵn $1$ alen đột biến $Rb$ từ bố mẹ có nguy cơ ung thư võng mạc sớm rất cao (chỉ cần thêm $1$ đột biến xôma trên alen thứ hai)."},{"key":"c","text":"Tế bào ung thư chỉ cần tích lũy duy nhất $1$ đột biến tăng hoạt tính trên gen $p53$ là lập tức mọc thành khối u di căn xa toàn thân.","ans":false,"exp":"Hình thành ung thư ác tính thường đòi hỏi nhiều bước tích lũy đột biến qua thời gian (kết hợp bật oncogene, mất gen ức chế khối u, bật telomerase và tăng sinh mạch máu di căn); bản thân *tăng* $p53$ lại chống ung thư, phải là *mất* chức năng $p53$."},{"key":"d","text":"Thuốc Imatinib (Gleevec) nhắm trúng đích ức chế đặc hiệu hoạt tính kinase của protein đột biến *BCR-ABL* mà không phá hủy hàng loạt tế bào lành như hóa trị kinh điển.","ans":true,"exp":"Liệu pháp nhắm trúng đích (Targeted therapy) gắn vào khe bám ATP của tyrosine kinase đột biến mang lại hiệu quả điều trị vượt trội trong CML."}],"summaryExp":""},{"id":"TF-045","topic":"cellular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân tích Thực nghiệm Chu kỳ Tế bào","stem":"Nuôi cấy đồng loạt một quần thể tế bào động vật có tổng thời gian một chu kỳ tế bào đúng bằng $24\\text{ giờ}$. Khi đếm ngẫu nhiên $1000$ tế bào trên tiêu bản cố định (tất cả đang phân chia tích cực, không đồng pha) thu được: $450$ tế bào đang ở pha $G_1$; $350$ tế bào ở pha $S$; $150$ tế bào ở pha $G_2$; và $50$ tế bào đang ở các kỳ của nguyên phân $M$ (trong đó có $15$ tế bào ở kỳ giữa). Xét các phân tích sau:","statements":[{"key":"a","text":"Tổng thời gian của kỳ trung gian ($G_1 + S + G_2$) trong mỗi chu kỳ tế bào chiếm thời lượng gấp đôi so với pha nguyên phân ($M$).","ans":false,"exp":"Kỳ trung gian có $450 + 350 + 150 = 950$ tế bào ($95\\% = 22.8\\text{ giờ}$), còn pha $M$ có $50$ tế bào ($5\\% = 1.2\\text{ giờ}$), tức kỳ trung gian dài gấp $19$ lần pha $M$ chứ không phải gấp đôi."},{"key":"b","text":"Khoảng thời gian trung bình dành cho giai đoạn nhân đôi ADN (pha $S$) của tế bào này ước tính bằng $8.4\\text{ giờ}$.","ans":true,"exp":"Thời gian pha tỷ lệ với phần trăm số tế bào đang ở pha đó: $t_S = \\frac{350}{1000} \\times 24 = 8.4\\text{ giờ}$."},{"key":"c","text":"Nếu bổ sung chất đánh dấu phóng xạ $^3H$-Thymidine trong một xung ngắn $15$ phút vào môi trường nuôi cấy, ngay lúc vừa kết thúc xung $15$ phút chỉ các tế bào đang nằm trong pha $S$ mới mang dấu phóng xạ trong nhân.","ans":true,"exp":"Thymidine là đơn phân đặc thù của ADN (khác Uracil của ARN) nên chỉ gắn vào ADN khi tế bào đang sao chép ở pha $S$."},{"key":"d","text":"Từ dữ kiện tiêu bản, chỉ số phân bào (Mitotic index) của quần thể tế bào đang xét là $5.0\\%$ và thời gian kỳ giữa ước tính vào khoảng $21.6\\text{ phút}$.","ans":true,"exp":"Chỉ số phân bào $= \\frac{50}{1000} = 5.0\\%$. Thời gian kỳ giữa $= \\frac{15}{1000} \\times 24\\text{ giờ} = 0.36\\text{ giờ} = 21.6\\text{ phút}$."}],"summaryExp":""},{"id":"TF-046","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quy luật Phân ly độc lập","stem":"Ở một loài thực vật giao phấn, alen $A$ quy định thân cao trội hoàn toàn so với $a$ thân thấp; $B$ quy định hoa đỏ trội hoàn toàn so với $b$ hoa trắng; $D$ quy định hạt vàng trội hoàn toàn so với $d$ hạt xanh. Các cặp gen nằm trên các cặp NST tương đồng khác nhau. Cho phép lai $P: AaBbDd \\times AaBbdd$. Xét đời con $F_1$ thu được:","statements":[{"key":"a","text":"Số loại kiểu gen tối đa thu được ở đời con $F_1$ bằng $18$ và số loại kiểu hình tối đa bằng $8$.","ans":true,"exp":"$Aa \\times Aa \\to 3\\text{ KG}, 2\\text{ KH}$; $Bb \\times Bb \\to 3\\text{ KG}, 2\\text{ KH}$; $Dd \\times dd \\to 2\\text{ KG}, 2\\text{ KH}$. Tổng $= 3\\times 3\\times 2 = 18$ KG và $2\\times 2\\times 2 = 8$ KH."},{"key":"b","text":"Tỉ lệ cây thân cao, hoa đỏ, hạt vàng thuần chủng ($AABBDD$) ở $F_1$ bằng $0$.","ans":true,"exp":"Bố mẹ có $dd$ nên mọi giao tử của bố mẹ đó đều mang $d$, không thể tạo được kiểu gen $DD$ ở $F_1$."},{"key":"c","text":"Tỉ lệ cây có kiểu hình mang ĐÚNG $2$ tính trạng trội và $1$ tính trạng lặn ở $F_1$ chiếm $\\frac{9}{32}$ ($28.125\\%$).","ans":false,"exp":"Các kiểu $2$ trội $+ 1$ lặn: $A-B-dd = \\frac{3}{4}\\cdot\\frac{3}{4}\\cdot\\frac{1}{2} = \\frac{9}{32}$; $A-bbD- = \\frac{3}{4}\\cdot\\frac{1}{4}\\cdot\\frac{1}{2} = \\frac{3}{32}$; $aaB-D- = \\frac{1}{4}\\cdot\\frac{3}{4}\\cdot\\frac{1}{2} = \\frac{3}{32}$. Tổng cộng $= \\frac{15}{32} = 46.875\\%$!"},{"key":"d","text":"Tỉ lệ cá thể dị hợp về ÍT NHẤT $1$ cặp gen ở đời con $F_1$ là $\\frac{7}{8}$ ($87.5\\%$).","ans":true,"exp":"Tỉ lệ cá thể ĐỒNG HỢP tất cả các cặp ($AA/aa$ và $BB/bb$ và $dd$) $= \\frac{1}{2} \\times \\frac{1}{2} \\times \\frac{1}{2} = \\frac{1}{8}$. Lấy $1 - \\frac{1}{8} = \\frac{7}{8}$ có ít nhất $1$ cặp dị hợp."}],"summaryExp":""},{"id":"TF-047","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Gen Bổ sung ($9:7$ và $9:6:1$)","stem":"Ở một loài cây trồng, màu sắc hoa do $2$ cặp gen không alen phân ly độc lập $A/a$ và $B/b$ cùng chi phối theo kiểu tương tác bổ sung: kiểu gen chứa đồng thời cả alen $A$ và alen $B$ ($A-B-$) cho hoa ĐỎ; các kiểu gen còn lại ($A-bb, aaB-, aabb$) đều cho hoa TRẮNG. Cho giao phấn $P: AaBb \\text{ (hoa đỏ)} \\times Aabb \\text{ (hoa trắng)}$ thu được $F_1$. Xét các nhận định sau:","statements":[{"key":"a","text":"Ở thế hệ $F_1$ thu được tỉ lệ phân ly kiểu hình là $3$ cây hoa đỏ : $5$ cây hoa trắng.","ans":true,"exp":"Từ $Aa \\times Aa \\to \\frac{3}{4}A-$, từ $Bb \\times bb \\to \\frac{1}{2}B-$. Vậy hoa đỏ $A-B- = \\frac{3}{4} \\times \\frac{1}{2} = \\frac{3}{8}$, còn lại $\\frac{5}{8}$ hoa trắng ($3:5$)."},{"key":"b","text":"Nếu cho các cây hoa TRẮNG ở $F_1$ tự thụ phấn riêng rẽ, chắc chắn sẽ xuất hiện một số cây con $F_2$ cho hoa màu ĐỎ.","ans":false,"exp":"Các cây hoa trắng ở $F_1$ gồm $A-bb$, $aaBb$ và $aabb$ đều thiếu hoàn toàn ít nhất $1$ trong $2$ alen trội $A$ hoặc $B$ nên khi tự thụ phấn không bao giờ tổ hợp lại được $A-B-$ (ra $100\\%$ trắng)."},{"key":"c","text":"Trong số các cây hoa ĐỎ thu được ở $F_1$, tỉ lệ cây có kiểu gen đồng hợp về cặp gen $A$ ($AABb$) chiếm $\\frac{1}{3}$.","ans":true,"exp":"Các cây hoa đỏ $F_1$ chỉ có $2$ kiểu gen là $\\frac{1}{3} AABb$ và $\\frac{2}{3} AaBb$ (vì từ $Aa\\times Aa$ trong nhóm $A-$ thì $AA=1/3, Aa=2/3$; còn $Bb$ luôn $100\\%$)."},{"key":"d","text":"Nếu cũng vẫn $2$ kiểu gen $AaBb \\times Aabb$ đó nhưng xét tính trạng hình dạng quả di truyền theo tương tác bổ sung $9:6:1$ ($A-B-$ dẹt; $A-bb + aaB-$ tròn; $aabb$ dài) thì đời con thu được $3$ dẹt : $4$ tròn : $1$ dài.","ans":true,"exp":"Dẹt $= \\frac{3}{8}$; dài $aabb = \\frac{1}{4} \\times \\frac{1}{2} = \\frac{1}{8}$; còn lại tròn $= \\frac{4}{8} \\Rightarrow 3:4:1$."}],"summaryExp":""},{"id":"TF-048","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương tác Cộng gộp (Di truyền Đa gen)","stem":"Ở một loài thực vật, chiều cao cây do $3$ cặp gen phân ly độc lập ($A/a, B/b, D/d$) tương tác cộng gộp quy định: cây mang toàn alen lặn ($aabbdd$) cao $100\\text{ cm}$, mỗi alen trội có mặt trong kiểu gen làm cây cao thêm $5\\text{ cm}$. Tiến hành phép lai $P: AaBbDd \\times AaBbdd$ thu được $F_1$. Xét các nhận định sau:","statements":[{"key":"a","text":"Chiều cao các cây ở đời con $F_1$ phân bố thành $6$ nhóm kiểu hình khác nhau trải từ mức thấp nhất $100\\text{ cm}$ đến cao nhất $125\\text{ cm}$.","ans":true,"exp":"Số alen trội ở con tối thiểu là $0$ ($aabbdd \\to 100\\text{ cm}$) và tối đa là $5$ ($AABBDd \\to 125\\text{ cm}$) $\\Rightarrow 6$ mức chiều cao ($100, 105, 110, 115, 120, 125\\text{ cm}$)."},{"key":"b","text":"Trong số các cây thu được ở $F_1$, tỉ lệ cây có chiều cao đúng $115\\text{ cm}$ (mang $3$ alen trội) bằng $\\frac{5}{16}$ ($31.25\\%$).","ans":true,"exp":"Xét phân bố số alen trội của $AaBbDd \\times AaBbdd$ là khai triển $(\\frac{1}{2}A + \\frac{1}{2}a)^4 (\\frac{1}{2}D + \\frac{1}{2}d)^1 = (\\frac{1}{2} + \\frac{1}{2})^5$: xác suất đúng $3$ alen trội $= \\binom{5}{3} (\\frac{1}{2})^5 = \\frac{10}{32} = \\frac{5}{16}$."},{"key":"c","text":"Cây mang chiều cao trung bình $115\\text{ cm}$ ở $F_1$ chỉ có duy nhất $1$ kiểu gen là $AaBbDd$.","ans":false,"exp":"Tất cả mọi kiểu gen có tổng cộng $3$ alen trội (như $AABbdd, AaBBdd, AABbDd$...) đều cao $115\\text{ cm}$: cụ thể $AaBbDd$ chiếm $\\frac{1}{8}$ nhưng tổng nhóm $115\\text{ cm}$ tới $\\frac{5}{16}$, có tới nhiều kiểu gen khác nhau."},{"key":"d","text":"Khi lấy ngẫu nhiên các cây $125\\text{ cm}$ ($AABBDd$) ở $F_1$ cho giao phấn ngẫu nhiên với nhau thì $100\\%$ đời $F_2$ thu được sẽ có chiều cao đồng nhất $125\\text{ cm}$.","ans":false,"exp":"$AABBDd \\times AABBDd$ phân ly cặp $Dd$ tạo $AABBDD$ ($130\\text{ cm}$), $AABBDd$ ($125\\text{ cm}$) và $AABBdd$ ($120\\text{ cm}$) theo tỉ lệ $1:2:1$."}],"summaryExp":""},{"id":"TF-049","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hoán vị gen ở Hai giới (Thực vật)","stem":"Ở một loài cây trồng tự thụ phấn, alen $A$ (thân cao) trội hoàn toàn so với $a$ (thân thấp), alen $B$ (quả tròn) trội hoàn toàn so với $b$ (quả dài). Hai gen cùng nằm trên một cặp NST thường cách nhau $20\\text{ cM}$ (hoán vị gen xảy ra ở cả hai giới với tần số $f = 20\\%$). Cho một cây thân cao, quả tròn dị hợp đối $\\frac{Ab}{aB}$ tự thụ phấn thu được $F_1$. Xét các nhận định sau:","statements":[{"key":"a","text":"Cây $\\frac{Ab}{aB}$ tạo ra $4$ loại giao tử với tỉ lệ bằng $\\underline{Ab} = \\underline{aB} = 40\\%$ và $\\underline{AB} = \\underline{ab} = 10\\%$.","ans":true,"exp":"Với $f = 20\\%$, mỗi loại giao tử hoán vị chiếm $f/2 = 10\\%$ ($\\underline{AB}, \\underline{ab}$) và giao tử liên kết chiếm $50\\% - 10\\% = 40\\%$ ($\\underline{Ab}, \\underline{aB}$)."},{"key":"b","text":"Tỉ lệ cây thân thấp, quả dài ($\\frac{ab}{ab}$) thu được ở thế hệ $F_1$ là $1\\%$ ($0.01$).","ans":true,"exp":"$f(\\frac{ab}{ab}) = 0.10 \\times 0.10 = 0.01 = 1\\%$."},{"key":"c","text":"Tỉ lệ cây thân cao, quả dài thuần chủng ($\\frac{Ab}{Ab}$) ở $F_1$ chiếm $24\\%$.","ans":false,"exp":"$A-bb = 0.25 - 0.01 = 24\\%$, nhưng trong đó gồm $2$ kiểu gen $\\frac{Ab}{Ab}$ ($0.4^2 = 16\\%$) và $\\frac{Ab}{ab}$ ($2\\times 0.4\\times 0.1 = 8\\%$); vậy kiểu gen thuần chủng $\\frac{Ab}{Ab}$ chỉ chiếm $16\\%$!"},{"key":"d","text":"Trong tổng số các cây thân cao, quả tròn ($A-B-$) ở $F_1$, số cây mang kiểu gen đồng hợp $2$ cặp gen ($\\frac{AB}{AB}$) chỉ chiếm tỉ lệ $\\frac{1}{51}$.","ans":true,"exp":"$A-B- = 0.50 + 0.01 = 51\\%$, trong đó $\\frac{AB}{AB} = 0.10^2 = 1\\% \\Rightarrow$ tỷ lệ $= \\frac{1}{51}$!"}],"summaryExp":""},{"id":"TF-050","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Ruồi giấm - Hoán vị gen Một giới","stem":"Ở ruồi giấm (*Drosophila melanogaster*), tính trạng thân xám ($A$) trội hoàn toàn so với thân đen ($a$); cánh dài ($B$) trội hoàn toàn so với cánh cụt ($b$), hai gen cùng nằm trên NST thường số II cách nhau $20\\text{ cM}$. Đặc trưng sinh học của ruồi giấm là hoán vị gen CHỈ xảy ra ở con CÁI (con đực liên kết hoàn toàn $f=0$). Cho ruồi cái $\\frac{Ab}{aB}$ giao phối với ruồi đực $\\frac{Ab}{aB}$ thu được $F_1$. Xét các nhận định sau:","statements":[{"key":"a","text":"Vì cả bố và mẹ đều có kiểu gen dị hợp chéo $\\frac{Ab}{aB}$ nên chắc chắn xuất hiện kiểu hình ruồi thân đen, cánh cụt ($\\frac{ab}{ab}$) ở $F_1$ với tỉ lệ $1\\%$.","ans":false,"exp":"Ruồi đực $\\frac{Ab}{aB}$ không hoán vị nên chỉ tạo $\\frac{1}{2}\\underline{Ab} : \\frac{1}{2}\\underline{aB}$ (hoàn toàn KHÔNG tạo giao tử $\\underline{ab}$!), do đó tỉ lệ $\\frac{ab}{ab}$ ở $F_1$ bằng $0\\%$!"},{"key":"b","text":"Số loại kiểu gen tối đa thu được ở thế hệ $F_1$ của phép lai này là $7$ kiểu gen và tỉ lệ kiểu hình $F_1$ là $2$ xám-dài : $1$ xám-cụt : $1$ đen-dài.","ans":true,"exp":"Từ cái ($0.4\\underline{Ab}, 0.4\\underline{aB}, 0.1\\underline{AB}, 0.1\\underline{ab}$) $\\times$ đực ($0.5\\underline{Ab}, 0.5\\underline{aB}$): tạo $7$ KG ($\\frac{AB}{Ab}, \\frac{AB}{aB}, \\frac{Ab}{Ab}, \\frac{Ab}{aB}, \\frac{aB}{aB}, \\frac{Ab}{ab}, \\frac{aB}{ab}$), kiểu hình luôn là $50\\%$ $A-B-$ : $25\\%$ $A-bb$ : $25\\%$ $aaB-$ ($2:1:1$)."},{"key":"c","text":"Tỉ lệ ruồi thân xám, cánh dài ($A-B-$) có kiểu gen dị hợp $2$ cặp gen $\\frac{Ab}{aB}$ ở $F_1$ bằng $40\\%$ tính trên tổng toàn bộ đàn con.","ans":true,"exp":"$f(\\frac{Ab}{aB}) = 0.4(\\underline{Ab}) \\times 0.5(\\underline{aB}) + 0.4(\\underline{aB}) \\times 0.5(\\underline{Ab}) = 0.20 + 0.20 = 40\\%$."},{"key":"d","text":"Thú vị hơn, cho ruồi cái dị hợp ĐỀU $\\frac{AB}{ab}$ (hoán vị $f=20\\%$) lai với ruồi đực dị hợp ĐỀU $\\frac{AB}{ab}$ ($f=0\\%$) cũng vẫn thu được $7$ kiểu gen nhưng tỉ lệ đồng hợp lặn $\\frac{ab}{ab}$ khi đó sẽ bằng $20\\%$.","ans":true,"exp":"Từ cái ($0.4\\underline{ab}$) $\\times$ đực ($0.5\\underline{ab}$) thu được $\\frac{ab}{ab} = 0.4 \\times 0.5 = 0.20 = 20\\%$, khi đó tỉ lệ KH là $70\\%$ $A-B-$ : $5\\%$ $A-bb$ : $5\\%$ $aaB-$ : $20\\%$ $aabb$."}],"summaryExp":""},{"id":"TF-051","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Di truyền Liên kết Giới tính trên NST X","stem":"Trong thí nghiệm nổi tiếng năm 1910 của T.H. Morgan trên ruồi giấm về gen quy định màu mắt nằm trên vùng không tương đồng của NST X ($W$: mắt đỏ trội hoàn toàn so với $w$: mắt trắng). Xét hai phép lai thuận và nghịch thuần chủng: Phép lai thuận: $\\text{Cái mắt đỏ } X^W X^W \\times \\text{Đực mắt trắng } X^w Y$; Phép lai nghịch: $\\text{Cái mắt trắng } X^w X^w \\times \\text{Đực mắt đỏ } X^W Y$. Xét các nhận định sau:","statements":[{"key":"a","text":"Ở $F_1$ của phép lai thuận, toàn bộ $100\\%$ ruồi đực và cái đều đồng loạt biểu hiện mắt đỏ, nhưng nếu cho $F_1$ giao phối tạo $F_2$ thì tất cả ruồi mắt trắng đều tập trung ở giới ĐỰC.","ans":true,"exp":"$F_1$: $X^W X^w \\times X^W Y \\rightarrow F_2$: $1 X^W X^W : 1 X^W X^w : 1 X^W Y : 1 X^w Y$ (toàn bộ ruồi cái mắt đỏ, một nửa ruồi đực mắt trắng)."},{"key":"b","text":"Ở ngay thế hệ $F_1$ của phép lai nghịch, kết quả phân ly kiểu hình khác nhau giữa 2 giới: $100\\%$ ruồi cái mắt ĐỎ ($X^W X^w$) và $100\\%$ ruồi đực mắt TRẮNG ($X^w Y$) — biểu hiện quy luật di truyền chéo.","ans":true,"exp":"Con đực nhận X trực tiếp từ mẹ trắng ($X^w$) còn con cái nhận X từ bố đỏ ($X^W$)."},{"key":"c","text":"Nếu cho ruồi mắt trắng $X^w Y$ giao phối với ruồi cái $F_1$ của phép lai thuận ($X^W X^w$) thì tỉ lệ ruồi ĐỰC mắt trắng trong tổng số cá thể đời con chỉ chiếm $50\\%$.","ans":false,"exp":"$X^W X^w \\times X^w Y \\rightarrow \\frac{1}{4} X^W X^w : \\frac{1}{4} X^w X^w : \\frac{1}{4} X^W Y : \\frac{1}{4} X^w Y$. Do đó ruồi đực mắt trắng chiếm $25\\%$ tổng số đời con (chiếm $50\\%$ trong riêng nhóm con đực)."},{"key":"d","text":"Trong tự nhiên ở chim, bướm và cá, hệ NST giới tính có cặp đồng giao ở con đực ($ZZ$) và dị giao ở con cái ($ZW$), nên gen lặn trên Z sẽ biểu hiện di truyền chéo theo chiều mẹ $Z^a W$ truyền cho con trống và bố truyền cho con mái.","ans":true,"exp":"Quy luật di truyền chéo trên Z luôn đi từ $Z$ của bố $\\rightarrow$ con mái $ZW$, còn $Z$ của mẹ chỉ đi về con trống $ZZ$."}],"summaryExp":""},{"id":"TF-052","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phối hợp Tương tác Gen & Liên kết NST Z","stem":"Ở gà ($ZZ$ là trống, $ZW$ là mái), tính trạng màu lông do $2$ gen tương tác bổ sung quy định: kiểu gen có đồng thời cả alen $A$ và $B$ ($A-B-$) quy định lông màu XÁM, các kiểu gen còn lại cho lông TRẮNG. Trong đó gen $A/a$ nằm trên NST thường; gen $B/b$ nằm trên vùng không tương đồng của NST giới tính Z. Thực hiện phép lai $P: Aa Z^B Z^b \\text{ (trống xám)} \\times Aa Z^b W \\text{ (mái trắng)}$ thu được $F_1$. Xét các phân tích sau:","statements":[{"key":"a","text":"Số loại kiểu gen tối đa có thể xuất hiện ở đàn gà con $F_1$ bằng $12$ kiểu gen ($3 \\times 4$).","ans":true,"exp":"$Aa \\times Aa \\to 3\\text{ KG}$; $Z^B Z^b \\times Z^b W \\to 4\\text{ KG}$ ($Z^B Z^b, Z^b Z^b, Z^B W, Z^b W$). Tổng $3 \\times 4 = 12\\text{ KG}$."},{"key":"b","text":"Tổng tỉ lệ gà con có bộ lông màu XÁM thu được ở thế hệ $F_1$ chiếm $37.5\\%$ ($\\frac{3}{8}$), trong đó chia đều bằng nhau giữa gà trống xám và gà mái xám.","ans":true,"exp":"$A- = \\frac{3}{4}$; ở cặp Z thu $\\frac{1}{4} Z^B Z^b$ (trống $B-$) và $\\frac{1}{4} Z^B W$ (mái $B-$). Vậy trống xám $= \\frac{3}{16}$, mái xám $= \\frac{3}{16}$, tổng xám $= \\frac{6}{16} = \\frac{3}{8} = 37.5\\%$."},{"key":"c","text":"Tỉ lệ gà con lông TRẮNG thu được ở $F_1$ chiếm $\\frac{5}{8}$ và tất cả các gà lông trắng này chỉ có thể là gà mái.","ans":false,"exp":"Cả trống và mái đều có thể có lông trắng (như $aa Z^B Z^b$ hay $AA Z^b Z^b$), trong đó trống trắng chiếm $\\frac{5}{16}$ và mái trắng cũng chiếm $\\frac{5}{16}$."},{"key":"d","text":"Nếu cho tất cả gà trống lông xám và gà mái lông xám ở $F_1$ giao phối ngẫu nhiên tạo $F_2$, tỉ lệ gà con lông TRẮNG ở $F_2$ thu được bằng $\\frac{1}{3}$ ($\\approx 33.33\\%$).","ans":true,"exp":"Nhóm xám $F_1$ gồm $(\\frac{1}{3}AA : \\frac{2}{3}Aa) Z^B Z^b \\times (\\frac{1}{3}AA : \\frac{2}{3}Aa) Z^B W$. Tỉ lệ $A- = 1 - (\\frac{1}{3})^2 = \\frac{8}{9}$; tỉ lệ $B- = \\frac{3}{4}$. Vậy xám $F_2 = \\frac{8}{9} \\times \\frac{3}{4} = \\frac{2}{3} \\Rightarrow$ lông trắng $F_2 = 1 - \\frac{2}{3} = \\frac{1}{3}$!"}],"summaryExp":""},{"id":"TF-053","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Di truyền Ngoài nhân (Tế bào chất)","stem":"Phân tích đặc điểm di truyền của các gen nằm trong ty thể và lục lạp thông qua thí nghiệm lai thuận nghịch trên cây hoa phấn (*Mirabilis jalapa*) của C. Correns và bệnh động kinh rung giật cơ (MERRF) do đột biến ADN ty thể ở người:","statements":[{"key":"a","text":"Ở cây hoa phấn, khi lấy hạt phấn từ cành lá ĐỐM thụ phấn cho hoa trên cành lá XANH hoàn toàn, đời con thu được có $50\\%$ lá xanh và $50\\%$ lá đốm.","ans":false,"exp":"Di truyền ngoài nhân tuân theo dòng MẸ: tế bào hạt phấn gần như không đóng góp bào tương (lục lạp) cho hợp tử; khi mẹ lá xanh nhận phấn bất kể cành nào thì $100\\%$ cây con đều lá XANH."},{"key":"b","text":"Nếu cho hạt phấn từ hoa lá xanh thụ phấn cho nhụy trên cành lá KHẢM (chứa hỗn hợp lục lạp xanh bình thường và lục lạp trắng đột biến trong bào tương noãn), đời con có thể xuất hiện đồng thời cả cây lá xanh, cây lá trắng và cây lá khảm với tỉ lệ không cố định.","ans":true,"exp":"Sự phân chia tế bào chất không đồng đều trong nguyên phân/giảm phân hình thành noãn trên cành khảm tạo ra $3$ loại tế bào trứng chứa toàn lạp xanh, toàn lạp trắng hoặc hỗn hợp lạp xanh-trắng."},{"key":"c","text":"Ở người, một người đàn ông mắc bệnh di truyền do đột biến gen ty thể ($mtADN$) kết hôn với người phụ nữ có ty thể hoàn toàn bình thường sẽ truyền alen bệnh cho $100\\%$ các con gái của anh ta.","ans":false,"exp":"Người đàn ông mang ty thể bệnh KHÔNG truyền ty thể cho các con (duy nhất trứng của người mẹ cung cấp ty thể cho phôi hợp tử; đuôi tinh trùng mang ty thể hầu hết bị phá hủy khi thụ tinh)."},{"key":"d","text":"Mọi người con của một người mẹ mang hoàn toàn ty thể đồng hợp đột biến gây bệnh teo dây thần kinh thị giác Leber (LHON) đều thừa hưởng các phân tử ty thể đột biến từ mẹ bất kể giới tính nam hay nữ.","ans":true,"exp":"Ty thể di truyền thẳng theo dòng mẹ (maternal inheritance) cho cả con trai lẫn con gái."}],"summaryExp":""},{"id":"TF-054","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Mức phản ứng & Ảnh hưởng Môi trường","stem":"Mối quan hệ tương tác giữa kiểu gen, môi trường và kiểu hình được thể hiện rõ ở hai hiện tượng sinh học quen thuộc: (1) Cây hoa cẩm tú cầu (*Hydrangea macrophylla*) có cùng kiểu gen nhưng trồng ở đất chua giàu $Al^{3+}$ ra hoa xanh lam còn trồng ở đất kiềm ra hoa hồng; (2) Thỏ Himalaya thuần chủng có lông trắng toàn thân nhưng chóp tai, chóp mũi, bàn chân và đuôi lại đen tuyền. Xét các nhận định sau:","statements":[{"key":"a","text":"Tập hợp tất cả các màu hoa khác nhau mà cùng một kiểu gen hoa cẩm tú cầu có thể biểu hiện ra tương ứng với các độ pH đất khác nhau gọi là mức phản ứng của kiểu gen đó.","ans":true,"exp":"Mức phản ứng là tập hợp các kiểu hình của CÙNG MỘT KIỂU GEN tương ứng với các điều kiện môi trường khác nhau."},{"key":"b","text":"Ở thỏ Himalaya, sở dĩ các vùng đầu mút như tai, mũi, bàn chân có màu lông đen là do nhiệt độ ngoại vi ở các vùng này mát lạnh hơn thân mình ($< 33^\\circ\\text{C}$), cho phép enzyme tổng hợp sắc tố melanin hoạt động.","ans":true,"exp":"Enzyme tyrosinase ở giống thỏ này mang đột biến nhạy nhiệt: mất hoạt tính ở thân ấm ($\\sim 37^\\circ\\text{C}$) nhưng hoạt động bình thường ở vùng mút lạnh ($\\sim 25-32^\\circ\\text{C}$)."},{"key":"c","text":"Nếu cạo sạch lông trắng trên lưng một con thỏ Himalaya rồi chườm túi nước đá lạnh liên tục lên vùng da vừa cạo cho tới khi lông mọc lại, lông mọc lên vẫn hoàn toàn giữ màu trắng vì kiểu gen quy định vùng lưng không bao giờ đen được.","ans":false,"exp":"Chính kiểu gen nhạy nhiệt phản ứng với nhiệt độ thấp tại vùng lưng được chườm lạnh sẽ kích hoạt enzyme tổng hợp melanin làm vùng lông mọc mới ở lưng có màu ĐEN!"},{"key":"d","text":"Bố mẹ không truyền trực tiếp các kiểu hình đã hình thành sẵn (như vết sẹo hay màu hoa xanh do pH) cho con, mà truyền cho con một kiểu gen quy định giới hạn mức phản ứng trước môi trường.","ans":true,"exp":"Tính trạng chất lượng thường có mức phản ứng hẹp, tính trạng số lượng (năng suất, cân nặng) thường có mức phản ứng rộng."}],"summaryExp":""},{"id":"TF-055","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Lập Bản đồ 3 Điểm Gen (Three-point Cross)","stem":"Một cá thể dị hợp $3$ cặp gen ($A/a, B/b, C/c$) nằm trên cùng $1$ cặp NST thường được lai phân tích thu được $1000$ cá thể đời con $F_a$ gồm $8$ tổ hợp giao tử: $ABC = 420$; $abc = 424$; $aBC = 48$; $Abc = 48$; $ABc = 28$; $abC = 28$; $AbC = 2$; $aBc = 2$. Xét các kết luận sau:","statements":[{"key":"a","text":"Hai lớp giao tử bố mẹ ban đầu (không có trao đổi chéo) là $\\underline{ABC}$ và $\\underline{abc}$, tương ứng kiểu gen dị hợp đều $\\frac{ABC}{abc}$.","ans":true,"exp":"$420 + 424 = 844$ ($84.4\\%$) chiếm đa số tuyệt đối nên là giao tử liên kết ban đầu."},{"key":"b","text":"Từ hai lớp trao đổi chéo kép ít nhất ($AbC = 2, aBc = 2$) suy ra trật tự sắp xếp của $3$ gen trên nhiễm sắc thể là $B - A - C$ (tức $A$ nằm giữa).","ans":false,"exp":"So với lớp bố mẹ $\\underline{ABC}$, tổ hợp chéo kép $\\underline{AbC}$ chỉ đảo một mình alen $b$ (còn $A$ và $C$ giữ nguyên vị trí tương đối), chứng tỏ <strong>$B$</strong> nằm chính giữa: trật tự đúng là $A - B - C$."},{"key":"c","text":"Khoảng cách di truyền giữa $A$ và $B$ bằng $10.0\\text{ cM}$ và khoảng cách giữa $B$ và $C$ bằng $6.0\\text{ cM}$.","ans":true,"exp":"$d(A-B) = \\frac{48+48+2+2}{1000}\\times 100 = 10.0\\text{ cM}$; $d(B-C) = \\frac{28+28+2+2}{1000}\\times 100 = 6.0\\text{ cM}$."},{"key":"d","text":"Số lượng cá thể trao đổi chéo kép KỲ VỌNG (nếu hai đoạn trao đổi chéo hoàn toàn độc lập) là $6$ cá thể, nhưng thực tế chỉ quan sát được $4$ cá thể, chứng tỏ có hiện tượng nhiễu dương với $CoC = \\frac{2}{3}$ và hệ số nhiễu $I = \\frac{1}{3}$.","ans":true,"exp":"Kỳ vọng $= 0.10 \\times 0.06 \\times 1000 = 6$; $CoC = \\frac{4}{6} = \\frac{2}{3}$ và nhiễu $I = 1 - CoC = \\frac{1}{3} \\approx 33.3\\%$."}],"summaryExp":""},{"id":"TF-056","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Gen Đa hiệu & Tương tác Át chế","stem":"Xét hai hiện tượng di truyền quan trọng: (1) Một gen đột biến $Hb^S$ ở người gây đồng thời hồng cầu hình liềm, tắc nghẽn vi mạch, tổn thương lách và suy thận; (2) Màu lông ở chó Labrador Retriever do $2$ gen độc lập: gen $B/b$ quy định sắc tố đen ($B-$) hay nâu ($bb$), nhưng gen $E/e$ kiểm soát khả năng lắng đọng sắc tố lên lông ($ee$ ngăn tất cả sắc tố gắn vào lông tạo lông vàng bất kể $B$ hay $b$). Xét các nhận định sau:","statements":[{"key":"a","text":"Hiện tượng đột biến ở một gen $Hb^S$ ảnh hưởng hàng loạt tới nhiều tính trạng và cơ quan khác nhau trong cơ thể được gọi là tác động đa hiệu của gen (Pleiotropy).","ans":true,"exp":"Sản phẩm của một gen tham gia con đường chuyển hóa hoặc cấu trúc thiết yếu sẽ dẫn tới chuỗi tác động hệ quả đa cơ quan."},{"key":"b","text":"Khi cho lai hai con chó Labrador đều dị hợp $2$ cặp gen lông đen ($BbEe \\times BbEe$), đời con phân ly kiểu hình theo tỉ lệ $9$ đen : $3$ nâu : $4$ vàng.","ans":true,"exp":"$9 B-E-$ (đen) : $3 bbE-$ (nâu) : $(3 B-ee + 1 bbee)$ (vàng) $= 9:3:4$ — kiểu tương tác át chế lặn ($ee$ át chế locus $B/b$)."},{"key":"c","text":"Khi lai chó Labrador lông VÀNG ($BBee$) với chó lông VÀNG ($bbee$), đời con chắc chắn thu được $100\\%$ chó con lông NÂU hoặc ĐEN nhờ hiện tượng bổ sung phục hồi màu tối.","ans":false,"exp":"$BBee \\times bbee \\rightarrow 100\\% Bbee$ mang $ee$ nên vẫn $100\\%$ lông VÀNG; chỉ khi lai $BBee$ với $bbEE$ (hoặc $bbEe$) mới ra được $BbEe$ lông ĐEN."},{"key":"d","text":"Kiểu gen gây hội chứng Marfan ở người (đột biến gen *FBN1* mã hóa fibrillin-1 gây chân tay dài bất thường, trật thủy tinh thể mắt và phình vỡ động mạch chủ) cũng tuân theo quy luật tương tác $2$ cặp gen bổ sung hoàn toàn không liên quan đa hiệu.","ans":false,"exp":"Hội chứng Marfan cũng là ví dụ điển hình cho TÍNH ĐA HIỆU của một gen đột biến trội đơn lẻ (*FBN1*) gây khiếm khuyết mô liên kết toàn cơ thể."}],"summaryExp":""},{"id":"TF-057","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phối hợp Độc lập & Hoán vị Gen","stem":"Ở một loài thực vật giao phấn, $3$ cặp gen quy định $3$ tính trạng trội hoàn toàn ($A>a$, $B>b$, $D>d$). Phép lai $P: Aa \\frac{BD}{bd} \\times Aa \\frac{Bd}{bD}$ thu được $F_1$. Biết hoán vị gen xảy ra ở cả hai giới với tần số $f = 40\\%$. Xét các tính toán ở đời con $F_1$:","statements":[{"key":"a","text":"Số loại kiểu gen tối đa có thể xuất hiện ở đời con $F_1$ là $3 \\times 9 = 27$ kiểu gen.","ans":false,"exp":"Cặp $Aa \\times Aa$ cho $3$ kiểu gen; cặp liên kết hoán vị ở cả $2$ giới $\\frac{BD}{bd} \\times \\frac{Bd}{bD}$ tạo tối đa $10$ kiểu gen trên cặp NST đó. Tổng số KG $= 3 \\times 10 = 30$ kiểu gen!"},{"key":"b","text":"Tỉ lệ kiểu gen mang đồng thời cả $3$ cặp gen đồng hợp lặn ($aa \\frac{bd}{bd}$) ở $F_1$ chiếm $1.5\\%$ ($0.015$).","ans":true,"exp":"Cặp $Aa \\times Aa \\to 0.25 aa$. Ở cặp liên kết: $\\frac{BD}{bd}$ tạo $0.30 \\underline{bd}$; $\\frac{Bd}{bD}$ tạo $0.20 \\underline{bd} \\Rightarrow \\frac{bd}{bd} = 0.30 \\times 0.20 = 0.06$. Vậy $aa \\frac{bd}{bd} = 0.25 \\times 0.06 = 0.015 = 1.5\\%$."},{"key":"c","text":"Tỉ lệ cá thể ở $F_1$ mang kiểu hình lặn về cặp $A$ nhưng trội về cả hai tính trạng $B$ và $D$ ($aa B-D-$) bằng $14.0\\%$.","ans":true,"exp":"Từ $\\frac{bd}{bd} = 0.06$, áp dụng hệ thức $B-D- = 0.50 + \\frac{bd}{bd} = 0.56$. Nhân $0.25 aa \\times 0.56 = 0.14 = 14.0\\%$!"},{"key":"d","text":"Tỉ lệ kiểu hình mang ĐÚNG $1$ tính trạng trội và $2$ tính trạng lặn ở $F_1$ là $24.5\\%$.","ans":false,"exp":"Tính chính xác: từ $\\frac{bd}{bd}=0.06 \\Rightarrow B-dd = bbD- = 0.25 - 0.06 = 0.19$. Các trường hợp $1$ trội $2$ lặn: $A-bbdd = 0.75\\times 0.06 = 0.045$; $aa B-dd = 0.25\\times 0.19 = 0.0475$; $aa bbD- = 0.25\\times 0.19 = 0.0475$. Tổng $= 0.045 + 0.095 = 0.14 = 14.0\\%$, không phải $24.5\\%$!"}],"summaryExp":""},{"id":"TF-058","topic":"mendel","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Alen Gây chết (Lethal Alleles)","stem":"Ở chuột, gen quy định màu lông gồm alen trội $A^Y$ (lông vàng) và alen lặn $A$ (lông xám/nâu kiểu dại). Tuy nhiên, alen $A^Y$ đồng thời gây chết giai đoạn phôi ở trạng thái đồng hợp $A^Y A^Y$ (biến tính gen thiết yếu lân cận). Khi cho lai các con chuột lông vàng với nhau ($P: A^Y A \\times A^Y A$), xét đàn chuột con sinh ra còn sống ở $F_1$:","statements":[{"key":"a","text":"Tỉ lệ phân ly kiểu hình của các con chuột con SỐNG SÓT sinh ra ở $F_1$ là $2$ lông vàng : $1$ lông xám (thay vì $3:1$).","ans":true,"exp":"Tổ hợp hợp tử $1 A^Y A^Y \\text{ (chết)} : 2 A^Y A \\text{ (vàng)} : 1 AA \\text{ (xám)}$, do đó trong số con sống sót luôn phân ly $2$ vàng : $1$ xám."},{"key":"b","text":"Mọi con chuột lông vàng trưởng thành đang sống trong đàn thực chất đều mang kiểu gen DỊ HỢP tử ($A^Y A$), không bao giờ tồn tại dòng chuột lông vàng thuần chủng.","ans":true,"exp":"Do $A^Y A^Y$ chết ngay từ giai đoạn phôi sớm nên bất kỳ cá thể vàng nào sống được đều là $A^Y A$."},{"key":"c","text":"Nếu cho một con chuột lông vàng ($A^Y A$) giao phối với một con chuột lông xám ($AA$), tỉ lệ chuột chết phôi vẫn là $25\\%$ và đời con sống phân ly $2:1$.","ans":false,"exp":"$A^Y A \\times AA \\to \\frac{1}{2} A^Y A \\text{ (vàng)} : \\frac{1}{2} AA \\text{ (xám)}$; không hề xuất hiện đồng hợp $A^Y A^Y$ nên tỷ lệ phôi chết do alen này bằng $0\\%$ và tỉ lệ phân ly là $1:1$."},{"key":"d","text":"Hiện tượng mất đi một tổ hợp kiểu gen đồng hợp ở đời con là một ví dụ cho thấy yếu tố sức sống / chọn lọc phôi có thể làm biến đổi tỉ lệ kiểu hình lý thuyết kinh điển của Mendel.","ans":true,"exp":"Các gen gây chết lặn hoặc trội có hiệu ứng gây chết lặn ở đồng hợp tử đều biến đổi tỷ lệ $3:1$ kinh điển thành $2:1$."}],"summaryExp":""},{"id":"TF-059","topic":"mendel","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Suy luận Kiểu gen & Tần số Hoán vị ngược từ $F_2$","stem":"Ở một loài thực vật, xét $2$ cặp gen cùng nằm trên $1$ cặp NST thường: $A$ (quả đỏ) trội hoàn toàn $a$ (quả vàng); $B$ (quả ngọt) trội hoàn toàn $b$ (quả chua). Hai phép lai tự thụ phấn độc lập (tần số hoán vị bằng nhau ở 2 giới): Ở thí nghiệm $1$, cây dị hợp $2$ cặp gen $X$ tự thụ cho $F_2$ có $16\\%$ $aabb$; Ở thí nghiệm $2$, cây dị hợp $2$ cặp gen $Y$ tự thụ cho $F_2$ có $4\\%$ $aabb$. Xét các suy luận sau:","statements":[{"key":"a","text":"Kiểu gen của cây $X$ là dị hợp đều $\\frac{AB}{ab}$ với tần số hoán vị gen $f = 20\\%$.","ans":true,"exp":"$aabb = 0.16 \\Rightarrow \\underline{ab} = 0.40 > 0.25$ nên là giao tử liên kết $\\frac{AB}{ab}$, $f = 2(0.5 - 0.4) = 20\\%$."},{"key":"b","text":"Kiểu gen của cây $Y$ cũng là dị hợp đều $\\frac{AB}{ab}$ nhưng với tần số hoán vị gen $f = 10\\%$.","ans":false,"exp":"Do $\\underline{ab} = \\sqrt{0.04} = 0.20 < 0.25$, cây $Y$ có kiểu gen dị hợp chéo $\\frac{Ab}{aB}$ với $f = 2 \\times 0.20 = 40\\%$."},{"key":"c","text":"Ở $F_2$ của thí nghiệm $1$, tỉ lệ cây quả đỏ, quả ngọt ($A-B-$) chiếm $66\\%$ tổng số cây thu được.","ans":true,"exp":"$A-B- = 0.50 + 0.16 = 0.66 = 66\\%$."},{"key":"d","text":"Ở $F_2$ của thí nghiệm $2$, tổng tỉ lệ các cây dị hợp $2$ cặp gen (cả $\\frac{AB}{ab}$ và $\\frac{Ab}{aB}$) bằng đúng $26\\%$.","ans":true,"exp":"Cây $Y$ tạo $0.3\\underline{Ab} : 0.3\\underline{aB} : 0.2\\underline{AB} : 0.2\\underline{ab}$. Tự thụ tạo $\\frac{Ab}{aB} = 2(0.3)(0.3) = 18\\%$ và $\\frac{AB}{ab} = 2(0.2)(0.2) = 8\\%$. Tổng cộng $18\\% + 8\\% = 26\\%$!"}],"summaryExp":""},{"id":"TF-060","topic":"mendel","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Liên kết Gen Hoàn toàn vs Hoán vị Gen","stem":"So sánh phép lai giữa hai cây dị hợp $2$ cặp gen $P: \\frac{AB}{ab} \\times \\frac{AB}{ab}$ trong $3$ kịch bản độc lập khác nhau về diễn biến giảm phân của $2$ gen $A/a$ và $B/b$ cùng nằm trên một cặp NST:","statements":[{"key":"a","text":"Nếu cả bố và mẹ đều có $f = 0\\%$ (liên kết hoàn toàn), đời con $F_1$ thu được tối đa $10$ loại kiểu gen và $4$ loại kiểu hình.","ans":false,"exp":"Nếu liên kết hoàn toàn cả 2 bên: $0.5\\underline{AB}, 0.5\\underline{ab} \\times 0.5\\underline{AB}, 0.5\\underline{ab}$ chỉ tạo $3$ kiểu gen ($1 \\frac{AB}{AB} : 2 \\frac{AB}{ab} : 1 \\frac{ab}{ab}$) và $2$ kiểu hình ($3:1$)."},{"key":"b","text":"Nếu chỉ một bên xảy ra hoán vị gen (tạo $4$ loại giao tử) và bên kia liên kết hoàn toàn (tạo $2$ loại giao tử), đời con $F_1$ thu được tối đa $7$ loại kiểu gen.","ans":true,"exp":"Phép nhân $(4 \\text{ loại}) \\times (2 \\text{ loại})$ giao tử liên kết-hoán vị sinh đúng $7$ kiểu gen phân biệt (chỉ trùng $\\frac{AB}{ab}$)."},{"key":"c","text":"Nếu hoán vị gen xảy ra ở cả hai bên bố và mẹ đều tạo $4$ loại giao tử, số loại kiểu gen tối đa ở $F_1$ tăng lên thành $10$ loại (với $2$ kiểu dị hợp hai cặp là $\\frac{AB}{ab}$ và $\\frac{Ab}{aB}$).","ans":true,"exp":"Bảng $4\\times 4$ tổ hợp với $2$ kiểu dị hợp kép phân biệt cho $\\frac{4(4+1)}{2} = 10$ kiểu gen."},{"key":"d","text":"Hiện tượng liên kết hoàn toàn làm hạn chế sự xuất hiện các biến dị tổ hợp, góp phần bảo tồn ổn định các nhóm gen quý thường xuyên di truyền cùng nhau.","ans":true,"exp":"Đây là ý nghĩa di truyền và chọn giống quan trọng của hiện tượng liên kết gen do Morgan phát hiện."}],"summaryExp":""},{"id":"TF-061","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc Quần thể Tự thụ phấn","stem":"Một quần thể thực vật lưỡng bội tự thụ phấn bắt buộc có cấu trúc di truyền ở thế hệ xuất phát $P$ là: $0.20 AA + 0.60 Aa + 0.20 aa = 1$ (không có đột biến, không chọn lọc, sức sống mọi kiểu gen bằng nhau). Xét các nhận định sau về các thế hệ con cháu:","statements":[{"key":"a","text":"Tần số tương đối của alen $A$ và alen $a$ tại thế hệ xuất phát $P$ đều bằng nhau ($p(A) = q(a) = 0.50$) và vẫn bảo toàn ở mức $0.50$ tại thế hệ $F_5$.","ans":true,"exp":"Tự thụ phấn không làm thay đổi tần số alen: $p(A) = 0.20 + 0.60/2 = 0.50$."},{"key":"b","text":"Ở thế hệ $F_1$, thành phần kiểu gen của quần thể là $0.35 AA + 0.30 Aa + 0.35 aa = 1$.","ans":true,"exp":"$Aa$ giảm một nửa còn $0.30$; lượng giảm $0.30$ chia đều cho $AA$ và $aa$ mỗi bên $+0.15$ thành $0.35 AA$ và $0.35 aa$."},{"key":"c","text":"Ở thế hệ $F_2$, tỉ lệ cây mang kiểu hình trội ($A-$) trong quần thể giảm xuống còn $57.5\\%$ ($0.575$).","ans":true,"exp":"Ở $F_2$: $Aa = 0.6 \\times (0.5)^2 = 0.15$; $AA = 0.2 + \\frac{0.6 - 0.15}{2} = 0.425$; $aa = 0.425$. Tổng kiểu hình trội $A- = 0.425 + 0.15 = 0.575 = 57.5\\%$ (hoặc $1 - 0.425 = 0.575$)."},{"key":"d","text":"Sau $3$ thế hệ tự thụ phấn ($F_3$), quần thể đạt ngay trạng thái cân bằng Hardy-Weinberg với $2pq = 0.50 Aa$.","ans":false,"exp":"Tự thụ phấn càng kéo dài thì tỉ lệ dị hợp $Aa$ càng tiến về $0$ ($F_3$ còn $0.075 Aa$), không bao giờ chuyển thành $0.50 Aa$ của ngẫu phối."}],"summaryExp":""},{"id":"TF-062","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Kiểm định Cân bằng Hardy-Weinberg","stem":"Khảo sát một quần thể động vật sinh sản hữu tính (gen trên NST thường gồm $2$ alen $A, a$) tại thế hệ xuất phát $P$: Giới cái ($50\\%$) có cấu trúc $0.5 AA + 0.4 Aa + 0.1 aa = 1$; Giới đực ($50\\%$) có cấu trúc $0.1 AA + 0.4 Aa + 0.5 aa = 1$. Cho quần thể này giao phối ngẫu nhiên tự do qua các thế hệ (không chọn lọc, không đột biến, không di-nhập gen). Xét các phân tích sau:","statements":[{"key":"a","text":"Tần số alen $A$ ở giới cái là $p_f = 0.70$, còn ở giới đực là $p_m = 0.30$.","ans":true,"exp":"Giới cái: $p_f = 0.5 + 0.2 = 0.7$; giới đực: $p_m = 0.1 + 0.2 = 0.3$."},{"key":"b","text":"Ngay sau $1$ thế hệ ngẫu phối ($F_1$), quần thể đã đạt trạng thái cân bằng di truyền Hardy-Weinberg với $0.25 AA + 0.50 Aa + 0.25 aa$.","ans":false,"exp":"Do $p_f \\neq p_m$ ở $P$, $F_1$ thu được có: $AA = 0.7\\times 0.3 = 0.21$; $aa = 0.3\\times 0.7 = 0.21$; $Aa = 0.7(0.7)+0.3(0.3) = 0.58$ ($0.21 AA + 0.58 Aa + 0.21 aa$, CHƯA cân bằng!). Phải sang <strong>$F_2$</strong> mới đạt cân bằng $0.25:0.50:0.25$!"},{"key":"c","text":"Ở thế hệ $F_1$, tần số alen $A$ đã đồng nhất ở cả con đực và con cái bằng $0.50$, và tỉ lệ kiểu gen dị hợp $Aa$ tại $F_1$ chiếm tới $58\\%$.","ans":true,"exp":"Mỗi con $F_1$ nhận ngẫu nhiên $1$ NST thường từ mẹ ($0.7 A$) và $1$ từ bố ($0.3 A$), nên $p(F_1) = 0.50$ đều cả 2 giới, còn $Aa = 0.58 > 0.50$."},{"key":"d","text":"Từ thế hệ $F_2$ trở đi, nếu các nhân tố tiến hóa vẫn không tác động, cấu trúc di truyền quần thể ổn định vĩnh viễn ở $0.25 AA + 0.50 Aa + 0.25 aa = 1$.","ans":true,"exp":"Từ $F_1$ đồng nhất 2 giới ($p=0.5$), sang $F_2$ đạt ngay định luật Hardy-Weinberg $0.25:0.50:0.25$."}],"summaryExp":""},{"id":"TF-063","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Gen Liên kết Giới tính X","stem":"Trong một quần thể người lớn đạt trạng thái cân bằng di truyền Hardy-Weinberg (tỉ lệ nam:nữ là $1:1$), bệnh máu khó đông (Hemophilia) do một alen lặn $h$ nằm trên vùng không tương đồng của NST X quy định ($H$ bình thường trội hoàn toàn). Khảo sát ghi nhận tần số nam giới mắc bệnh trong nhóm nam là $5\\%$ ($q(X^h) = 0.05$). Xét các nhận định sau:","statements":[{"key":"a","text":"Tỉ lệ phụ nữ mắc bệnh máu khó đông ($X^h X^h$) trong tổng số nữ giới là $0.25\\%$ ($0.0025$), thấp hơn $20$ lần so với tỉ lệ mắc bệnh ở nam giới.","ans":true,"exp":"Nữ mắc bệnh có tần số $q^2 = 0.05^2 = 0.0025 = 0.25\\%$. Tỷ lệ so với nam $= 0.05 / 0.0025 = 20$ lần."},{"key":"b","text":"Tỉ lệ phụ nữ có kiểu hình bình thường nhưng mang alen gây bệnh ($X^H X^h$) trong nhóm nữ giới chiếm $9.5\\%$ ($0.095$).","ans":true,"exp":"Trong giới nữ: $2pq = 2 \\times 0.95 \\times 0.05 = 0.095 = 9.5\\%$."},{"key":"c","text":"Nếu chọn ngẫu nhiên một cặp vợ chồng đều KHÔNG mắc bệnh trong quần thể này, xác suất để đứa con trai đầu lòng của họ mắc bệnh máu khó đông bằng $5\\%$.","ans":false,"exp":"Bố bình thường luôn là $X^H Y$ nên không ảnh hưởng bệnh con trai (chỉ truyền Y cho con trai). Mẹ bình thường có xác suất mang $X^H X^h = \\frac{2pq}{p^2+2pq} = \\frac{2q}{1+q} = \\frac{0.10}{1.05} = \\frac{2}{21}$. Khi xét NẾU đã sinh con trai, xác suất con trai nhận $X^h$ từ mẹ $= \\frac{1}{2} \\times \\frac{2}{21} = \\frac{1}{21} \\approx 4.76\\%$ (nếu xét xác suất vừa là con trai vừa bị bệnh thì còn chia thêm $1/2$ thành $\\frac{1}{42} \\approx 2.38\\%$, trong mọi cách hiểu đều không bằng $5\\%$!)."},{"key":"d","text":"Tần số alen $h$ ở giới nữ ($XX$) và ở giới nam ($XY$) trong quần thể đang cân bằng là hoàn toàn khác nhau ($q_{\\text{nữ}} = 2 q_{\\text{nam}}$).","ans":false,"exp":"Khi quần thể đạt cân bằng di truyền trên NST X, tần số alen lặn ở cả $2$ giới đã hội tụ bằng nhau: $q_{\\text{nữ}} = q_{\\text{nam}} = q = 0.05$."}],"summaryExp":""},{"id":"TF-064","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chọn lọc Loại bỏ Đồng hợp Lặn trong Ngẫu phối","stem":"Một quần thể thực vật giao phấn ngẫu nhiên có thành phần kiểu gen ở giai đoạn hạt nảy mầm thế hệ $P$ là $0.16 AA + 0.48 Aa + 0.36 aa = 1$. Do sâu ăn lá đặc hiệu chỉ phá hủy làm chết $100\\%$ các cây non mang kiểu gen $aa$ trước độ tuổi ra hoa ở MỌI thế hệ; các cây sống sót giao phấn ngẫu nhiên bình thường. Xét các nhận định sau:","statements":[{"key":"a","text":"Tỉ lệ cá thể sống sót ra hoa ở thế hệ $P$ là $0.64$, trong đó tỉ lệ kiểu gen của các cây trưởng thành $P$ tham gia sinh sản là $0.25 AA + 0.75 Aa$.","ans":true,"exp":"Loại $0.36 aa$, phần còn lại $0.64$: $AA = \\frac{0.16}{0.64} = \\frac{1}{4} = 0.25$ và $Aa = \\frac{0.48}{0.64} = \\frac{3}{4} = 0.75$."},{"key":"b","text":"Từ các cây sống sót thế hệ $P$, tần số alen $a$ truyền qua giao tử bằng $0.375$ ($\\frac{3}{8}$), và khi giao phấn ngẫu nhiên tạo thế hệ hạt $F_1$ sẽ cho tỉ lệ hạt $aa$ chiếm $\\frac{9}{64}$ ($\\approx 14.06\\%$).","ans":true,"exp":"$q_0' = \\frac{0.75}{2} = \\frac{3}{8} = 0.375 \\Rightarrow$ hạt $F_1$ có $aa = (\\frac{3}{8})^2 = \\frac{9}{64}$."},{"key":"c","text":"Sau khi cây $aa$ ở $F_1$ lại tiếp tục bị chết hết, tần số alen $a$ ở các cây trưởng thành $F_1$ còn lại bằng $\\frac{3}{11}$, suy ra tỉ lệ hạt $aa$ bị chết ở thế hệ $F_2$ là $\\frac{9}{100}$ ($9\\%$).","ans":false,"exp":"$q_1' = \\frac{3/8}{1 + 3/8} = \\frac{3}{11}$, nên ở $F_2$ tỉ lệ hạt $aa = (\\frac{3}{11})^2 = \\frac{9}{121}$ ($\\approx 7.44\\%$), không phải $\\frac{9}{100}$!"},{"key":"d","text":"Theo công thức lặp chuẩn $q_n = \\frac{q_0'}{1 + n \\cdot q_0'}$, tốc độ làm giảm tần số alen $a$ diễn ra rất nhanh ở các thế hệ đầu nhưng chậm dần về sau và rất khó tiệt trừ alen $a$ về $0$ tuyệt đối sau hữu hạn thế hệ.","ans":true,"exp":"Vì khi $q$ nhỏ, phần lớn alen $a$ nằm ẩn trong kiểu gen dị hợp $Aa$ sống sót nên tốc độ chọn lọc $\\Delta q \\approx -s q^2 (1-q)$ giảm theo bình phương của $q$."}],"summaryExp":""},{"id":"TF-065","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phả hệ Kết hợp Di truyền Quần thể","stem":"Ở người, bệnh xơ nang (Cystic Fibrosis) do một alen lặn $a$ nằm trên NST thường quy định (alen trội $A$ bình thường). Trong một quần thể người cân bằng Hardy-Weinberg có tỉ lệ người mắc bệnh xơ nang là $1\\%$ ($0.01$). Anh Minh có kiểu hình bình thường nhưng có em ruột bị mắc bệnh xơ nang; bố mẹ anh Minh đều bình thường. Anh Minh kết hôn với chị Lan — một người phụ nữ bình thường được chọn ngẫu nhiên từ quần thể trên (gia đình bên ngoại không rõ tiền sử bệnh). Xét các nhận định sau:","statements":[{"key":"a","text":"Tần số alen lặn $a$ trong quần thể là $q = 0.10$ và tần số alen trội $A$ là $p = 0.90$.","ans":true,"exp":"$q^2 = 0.01 \\Rightarrow q = 0.10$, $p = 0.90$."},{"key":"b","text":"Xác suất anh Minh mang kiểu gen dị hợp ($Aa$) bằng $\\frac{2}{3}$, còn xác suất chị Lan mang kiểu gen dị hợp ($Aa$) bằng $\\frac{2}{11}$ ($\\approx 18.18\\%$).","ans":true,"exp":"Bố mẹ Minh đều $Aa \\Rightarrow$ Minh bình thường có $\\frac{2}{3} Aa$. Chị Lan trong nhóm bình thường quần thể ($0.81 AA : 0.18 Aa$) có $\\frac{0.18}{0.99} = \\frac{2}{11} Aa$."},{"key":"c","text":"Xác suất để đứa con đầu lòng của cặp vợ chồng anh Minh - chị Lan là CON GÁI VÀ BỊ BỆNH xơ nang bằng $\\frac{1}{33}$.","ans":false,"exp":"Xác suất đứa con đầu lòng mắc bệnh ($aa$) $= \\frac{2}{3} \\times \\frac{2}{11} \\times \\frac{1}{4} = \\frac{1}{33}$. Do có thêm điều kiện là CON GÁI (xác suất $\\frac{1}{2}$ độc lập), nên xác suất cần tìm $= \\frac{1}{33} \\times \\frac{1}{2} = \\frac{1}{66}$!"},{"key":"d","text":"Nếu đứa con đầu lòng của anh Minh và chị Lan thực tế sinh ra bị mắc bệnh xơ nang ($aa$), thì xác suất để đứa con thứ hai của họ KHÔNG bị mắc bệnh (bình thường) tăng lên? Không: bằng đúng $\\frac{3}{4}$ ($75\\%$).","ans":true,"exp":"Khi đã sinh con đầu $aa$, ta biết CHẮC CHẮN $100\\%$ cả anh Minh và chị Lan đều mang kiểu gen $Aa \\times Aa$; do đó xác suất đứa thứ hai bình thường ($A-$) bằng đúng $3/4 = 75\\%$."}],"summaryExp":""},{"id":"TF-066","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Đa alen - Hệ Nhóm máu ABO","stem":"Khảo sát một quần thể người lớn đang cân bằng di truyền về hệ nhóm máu ABO ($I^A, I^B$ đồng trội và trội hoàn toàn so với $I^O$). Kết quả thống kê ghi nhận tần số các alen là $p(I^A) = 0.4$, $q(I^B) = 0.2$ và $r(I^O) = 0.4$. Xét các nhận định sau:","statements":[{"key":"a","text":"Tỉ lệ phân bố $4$ nhóm máu trong quần thể này lần lượt là: Nhóm A chiếm $48\\%$; Nhóm B chiếm $20\\%$; Nhóm AB chiếm $16\\%$ và Nhóm O chiếm $16\\%$.","ans":true,"exp":"O $= 0.4^2 = 16\\%$; AB $= 2(0.4)(0.2) = 16\\%$; A $= 0.4^2 + 2(0.4)(0.4) = 0.16 + 0.32 = 48\\%$; B $= 0.2^2 + 2(0.2)(0.4) = 0.04 + 0.16 = 20\\%$. (Tổng $100\\%$)."},{"key":"b","text":"Trong số những người mang nhóm máu A của quần thể, tỉ lệ người có kiểu gen thuần chủng ($I^A I^A$) chiếm tới $50\\%$.","ans":false,"exp":"Trong $48\\%$ nhóm máu A gồm $16\\% I^A I^A$ và $32\\% I^A I^O$; vậy người thuần chủng $I^A I^A$ chiếm $\\frac{16}{48} = \\frac{1}{3}$ ($\\approx 33.33\\%$), còn dị hợp $I^A I^O$ chiếm $\\frac{2}{3}$."},{"key":"c","text":"Nếu một cặp vợ chồng ngẫu nhiên trong quần thể đều có nhóm máu B kết hôn với nhau, xác suất họ sinh được đứa con đầu lòng mang nhóm máu O ($I^O I^O$) bằng $\\frac{16}{100} = 16\\%$.","ans":true,"exp":"Trong nhóm B ($4\\% I^B I^B + 16\\% I^B I^O = 20\\%$), tỉ lệ mang dị hợp $I^B I^O$ là $\\frac{16}{20} = \\frac{4}{5}$. Xác suất hai vợ chồng B sinh con O $= \\frac{4}{5} \\times \\frac{4}{5} \\times \\frac{1}{4} = \\frac{16}{100} = 16\\%$!"},{"key":"d","text":"Xác suất chọn ngẫu nhiên được một người có kiểu gen ĐỒNG HỢP (tính chung cho cả $I^A I^A, I^B I^B$ và $I^O I^O$) trong quần thể này bằng $36\\%$.","ans":true,"exp":"Tổng tỉ lệ đồng hợp $= p^2 + q^2 + r^2 = 0.16 + 0.04 + 0.16 = 0.36 = 36\\%$."}],"summaryExp":""},{"id":"TF-067","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vai trò các Nhân tố Tiến hóa","stem":"Theo thuyết tiến hóa tổng hợp hiện đại, $5$ nhân tố tiến hóa cơ bản tác động làm biến đổi cấu trúc di truyền của quần thể là: Đột biến, Di-nhập gen, Chọn lọc tự nhiên, Các yếu tố ngẫu nhiên và Giao phối không ngẫu nhiên. Xét bảng đối chiếu tính chất của các nhân tố này:","statements":[{"key":"a","text":"Chỉ có duy nhất $2$ nhân tố là Đột biến và Di-nhập gen có khả năng làm giàu thêm vốn gen của quần thể bằng cách trực tiếp bổ sung các alen hoàn toàn mới.","ans":true,"exp":"Đột biến phát sinh alen mới từ trong quần thể; di-nhập gen đưa alen mới từ quần thể khác tới."},{"key":"b","text":"Cả Chọn lọc tự nhiên và Các yếu tố ngẫu nhiên (phiêu bạt di truyền) đều có khả năng làm nghèo vốn gen và giảm sự đa dạng di truyền của quần thể.","ans":true,"exp":"CLTN loại bỏ alen kém thích nghi; phiêu bạt ngẫu nhiên làm mất ngẫu nhiên các alen (đặc biệt alen hiếm) khỏi quần thể nhỏ."},{"key":"c","text":"Giao phối không ngẫu nhiên vừa trực tiếp làm tăng tỉ lệ đồng hợp tử vừa làm biến đổi mạnh tần số tương đối của các alen theo hướng tăng dần alen trội.","ans":false,"exp":"Giao phối không ngẫu nhiên KHÔNG làm thay đổi tần số alen của quần thể (chỉ làm giảm dị hợp tử và tăng đồng hợp tử)."},{"key":"d","text":"Các yếu tố ngẫu nhiên (thiên tai, lũ lụt, dịch bệnh bất ngờ) tác động càng mạnh mẽ nhất lên những quần thể có kích thước càng lớn (hàng triệu cá thể).","ans":false,"exp":"Ngược lại: sai số ngẫu nhiên tác động CỰC MẠNH ở những quần thể có kích thước NHỎ; quần thể càng lớn thì biến động ngẫu nhiên càng yếu."}],"summaryExp":""},{"id":"TF-068","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Các Hình thức Chọn lọc Tự nhiên","stem":"Trong sinh học tiến hóa, chọn lọc tự nhiên tác động lên các tính trạng phân bố liên tục (như kích thước, khối lượng, màu sắc) theo $3$ hình thức chính: Chọn lọc ổn định, Chọn lọc vận động (định hướng) và Chọn lọc phân hóa. Xét các nhận định phân biệt $3$ hình thức này:","statements":[{"key":"a","text":"Chọn lọc ổn định xảy ra khi điều kiện môi trường ít thay đổi trong thời gian dài, không làm thay đổi giá trị trung bình của quần thể mà lại mở rộng biên độ phương sai ra gấp đôi.","ans":false,"exp":"Chọn lọc ổn định thu hẹp biên độ biến dị (GIẢM phương sai) do đào thải hai cực, giữ chặt kiểu hình trung bình tối ưu."},{"key":"b","text":"Chọn lọc vận động (định hướng) làm dịch chuyển giá trị trung bình của tính trạng về một phía thích nghi hơn, ví dụ sự phát triển chiều cao hươu cao cổ hay tính kháng thuốc trừ sâu ở muỗi theo thời gian.","ans":true,"exp":"Khi môi trường biến đổi theo một xu hướng mới, một cực của dãy phân bố có giá trị thích nghi cao hơn sẽ dần thay thế trạng thái trung bình cũ."},{"key":"c","text":"Chọn lọc phân hóa ưu tiên giữ lại các cá thể mang giá trị tính trạng ở CẢ HAI CỰC ĐOAN (ví dụ chim sẻ mỏ rất to ăn hạt cứng và mỏ rất nhỏ ăn hạt mềm) và đào thải nhóm trung gian, có thể làm phân chia quần thể thành hai nhóm riêng biệt.","ans":true,"exp":"Chọn lọc phân hóa làm tăng phương sai, tạo phân bố hai đỉnh và có thể khởi phát hình thành loài cùng khu nếu kết hợp chọn bạn tình đồng hình."},{"key":"d","text":"Ở động vật đẻ trứng (như chim sáo đá đẻ số trứng mỗi lứa dao động từ $1$ đến $9$), những ổ có số trứng trung bình ($4-5$ trứng) cho tỉ lệ con non sống sót tới trưởng thành cao nhất là ví dụ của chọn lọc ổn định.","ans":true,"exp":"Đẻ quá ít không hiệu quả sinh sản, đẻ quá nhiều bố mẹ không đủ mồi nuôi khiến con còi cọc chết nhiều $\\rightarrow$ chọn lọc ổn định quanh $4-5$ trứng."}],"summaryExp":""},{"id":"TF-069","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Con đường Hình thành Loài mới","stem":"Quá trình hình thành loài mới (tiến hóa nhỏ kết thúc khi xuất hiện cách ly sinh sản) diễn ra qua các con đường khác nhau: Cách ly địa lý, Cách ly sinh thái (cùng khu) và Lai xa kết hợp đa bội hóa. Xét các nhận định sau:","statements":[{"key":"a","text":"Hình thành loài bằng con đường cách ly địa lý thường diễn ra rất chậm chạp qua nhiều giai đoạn trung gian và rất dễ xảy ra ở những loài động vật có khả năng phát tán, di cư mở rộng khu phân bố.","ans":true,"exp":"Cách ly địa lý chia cắt quần thể thành nhiều quần thể nhỏ tách biệt dòng gen trong thời gian dài để thích nghi với điều kiện địa phương khác nhau."},{"key":"b","text":"Trong con đường cách ly địa lý, điều kiện địa lý khác nhau đóng vai trò trực tiếp gây ra các đột biến định hướng giống nhau giúp cách ly sinh sản ngay lập tức.","ans":false,"exp":"Điều kiện địa lý và ngoại cảnh KHÔNG tạo ra đột biến có hướng sẵn, mà đóng vai trò tác nhân chọn lọc tự nhiên giữ lại các biến dị thích nghi khác nhau ở mỗi khu vực."},{"key":"c","text":"Loài ruồi ăn táo Bắc Mỹ (*Rhagoletis pomonella*) vốn sống trên cây táo gai bản địa đã tách thành hai dòng quần thể sinh sản lệch mùa trên cây táo gai và cây táo trồng châu Âu ngay trong cùng một khu vườn địa lý là ví dụ của hình thành loài cùng khu (cách ly sinh thái / tập tính).","ans":true,"exp":"Chuyển đổi vật chủ kết hợp giao phối trên cây ký chủ có mùa chín quả khác nhau làm suy giảm dòng gen xuống vài phần trăm giữa hai nòi sinh thái."},{"key":"d","text":"Bằng con đường lai xa và đa bội hóa, loài mới (thể song nhị bội) hình thành RẤT NHANH chỉ qua vài thế hệ ngay trong cùng khu phân bố mà không cần cách ly địa lý kéo dài.","ans":true,"exp":"Thể song nhị bội ($2n_A + 2n_B$) cách ly sinh sản tức thì với cả hai loài bố mẹ nhờ sai khác bộ NST khi lai ngược trở lại."}],"summaryExp":""},{"id":"TF-070","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Học thuyết Darwin & Thuyết Tiến hóa Trung tính","stem":"Đối chiếu học thuyết Chọn lọc tự nhiên của Charles Darwin (1859), Thuyết tiến hóa tổng hợp hiện đại và Thuyết tiến hóa trung tính ở cấp độ phân tử của Motoo Kimura (1968). Xét các nhận định sau:","statements":[{"key":"a","text":"Ưu điểm lớn của Darwin là đã chỉ ra đúng vai trò trung tâm của chọn lọc tự nhiên và biến dị cá thể, song hạn chế lịch sử của ông là chưa hiểu được nguyên nhân phát sinh biến dị và cơ chế di truyền biến dị (do thời đó chưa có di truyền học Mendel).","ans":true,"exp":"Sự ra đời của di truyền học quần thể vào đầu thế kỷ 20 đã kết hợp di truyền học Mendel với chọn lọc Darwin thành thuyết tiến hóa tổng hợp."},{"key":"b","text":"Theo thuyết tiến hóa trung tính của Kimura, phần lớn các thay thế nucleotit ở mức độ phân tử không ảnh hưởng đến giá trị thích nghi (biến dị trung tính) và do đó sự cố định chúng chỉ do Chọn lọc tự nhiên định hướng chứ không liên quan yếu tố ngẫu nhiên.","ans":false,"exp":"Ngược lại: đối với các alen TRUNG TÍNH ($s = 0$), Chọn lọc tự nhiên không tác động tới chúng; số phận cố định hay biến mất của các đột biến trung tính hoàn toàn do <strong>phiêu bạt di truyền ngẫu nhiên</strong> quyết định!"},{"key":"c","text":"Tốc độ thay thế cố định các đột biến trung tính mới phát sinh trong quần thể theo thời gian đúng bằng tốc độ đột biến trung tính $u$ của mỗi giao tử và hoàn toàn ĐỘC LẬP với kích thước quần thể $N_e$.","ans":true,"exp":"Kỳ vọng phát sinh đột biến trung tính mới toàn quần thể mỗi thế hệ là $2N u$, nhân xác suất cố định $1/(2N)$ bằng đúng $u$! Đây là cơ sở toán học của 'đồng hồ phân tử'."},{"key":"d","text":"Các đoạn trình tự ADN không mã hóa, intron hoặc vị trí nucleotit thứ ba đồng nghĩa trong codon thường tích lũy đột biến nhanh hơn hẳn vùng trung tâm hoạt động của enzyme vì ít chịu sức ép của chọn lọc ổn định.","ans":true,"exp":"Vùng thiết yếu có bảo thủ tiến hóa cao do mọi đột biến sai hỏng ở đó đều bị chọn lọc loại bỏ ngay."}],"summaryExp":""},{"id":"TF-071","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Bằng chứng Tiến hóa Gián tiếp & Trực tiếp","stem":"Xét bảng tổng hợp các bằng chứng tiến hóa giúp tái dựng lịch sử phát sinh các loài từ tổ tiên chung:","statements":[{"key":"a","text":"Chi trước của người (cầm nắm), cánh chim (bay), chi trước cá voi (bơi) và chi trước chuột chũi (đào đất) có khung xương cấu tạo đồng nhất gồm xương cánh, xương quay-trụ, cổ-bàn-ngón tay là bằng chứng về cơ quan tương đồng phản ánh tiến hóa phân ly.","ans":true,"exp":"Cùng bắt nguồn từ chi $5$ ngón của tổ tiên động vật $4$ chân cổ đại nhưng biến đổi phục vụ chức năng sinh thái khác nhau."},{"key":"b","text":"Nhờ phương pháp xác định tuổi đồng vị phóng xạ (như $^{14}C$ cho hóa thạch trẻ $< 50\\,000$ năm hoặc $^{40}K/^{40}Ar$, $^{238}U$ cho đá cổ hàng trăm triệu năm), nhà cổ sinh vật học định tuổi chính xác các lớp hóa thạch chuyển tiếp như *Archaeopteryx* hay *Tiktaalik*.","ans":true,"exp":"*Tiktaalik* là hóa thạch chuyển tiếp nối giữa cá vây thùy và lưỡng cư 4 chân; *Archaeopteryx* mang đặc điểm trung gian khủng long có lông vũ và chim."},{"key":"c","text":"Gai xương rồng (biến dạng từ lá) và gai hoa hồng (biến dạng từ biểu bì thân) có cùng nguồn gốc phôi sinh nên là cơ quan tương đồng.","ans":false,"exp":"Khác nguồn gốc phát sinh cơ quan (lá vs biểu bì thân) nhưng thực hiện chung chức năng tự vệ với hình thái nhọn giống nhau $\\rightarrow$ cơ quan TƯƠNG TỰ."},{"key":"d","text":"Chuỗi axit amin của protein Cytochrome c ở hai loài càng sai khác nhiều chứng tỏ hai loài đó tách ra từ tổ tiên chung càng GẦN đây.","ans":false,"exp":"Sai khác phân tử càng ÍT thì phân ly càng GẦN; sai khác càng NHIỀU chứng tỏ hai nhánh đã tiến hóa độc lập tách rời từ rất XA nhau trong quá khứ."}],"summaryExp":""},{"id":"TF-072","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thắt cổ chai & Hiệu ứng Kẻ Sáng lập (Báo săn Cheetah)","stem":"Loài báo săn châu Phi (*Acinonyx jubatus*) nổi tiếng với mức độ đồng hợp tử di truyền cực kỳ cao (tương đương động vật cận huyết phòng thí nghiệm nhiều thế hệ: thậm chí hai cá thể báo săn không cùng họ hàng ghép mảnh da cho nhau cũng gần như không bị đào thải miễn dịch mạnh ở các locus MHC), dẫn tới tỉ lệ tinh trùng dị dạng cao và dễ bị diệt vong hàng loạt trước một virus mới. Xét các nhận định tiến hóa bảo tồn sau:","statements":[{"key":"a","text":"Nguyên nhân sâu xa khiến báo săn có độ đa dạng di truyền cực thấp là do chúng đang có kích thước quần thể khổng lồ hàng chục triệu con trải khắp các châu lục.","ans":false,"exp":"Báo săn từng trải qua ít nhất một hoặc hai sự kiện THẮT CỔ CHAI (genetic bottleneck) khốc liệt cuối kỷ Băng hà ($\\approx 10\\,000$ năm trước), tụt xuống chỉ còn vài cá thể sống sót."},{"key":"b","text":"Sự thiếu hụt đa dạng tại cụm gen hòa hợp mô chính (MHC) ở báo săn khiến quần thể thiếu kho kháng nguyên trình diện phong phú, làm giảm khả năng chống chịu tập thể trước các chủng virus đột biến mới.","ans":true,"exp":"Đa dạng MHC cao giúp trong quần thể luôn có những cá thể nhận diện và sống sót trước các mầm bệnh mới xuất hiện."},{"key":"c","text":"Trong bảo tồn sinh học, việc nuôi nhốt hoặc phân mảnh sinh cảnh thành các khu bảo tồn nhỏ biệt lập mà không có hành lang di cư nhân tạo có nguy cơ làm tăng tốc vòng xoáy tuyệt chủng (Extinction vortex) do giao phối cận huyết và phiêu bạt di truyền.","ans":true,"exp":"Quần thể nhỏ bị tách rời mất dòng gen làm $N_e$ giảm mạnh $\\to$ nội phối tăng $\\to$ suy thoái giống $\\to$ giảm sinh sản $\\to$ kích thước càng thu nhỏ thêm."},{"key":"d","text":"Giải pháp phục hồi di truyền khả thi nhất cho quần thể nhỏ suy thoái cận huyết là cấm tuyệt đối mọi sự trao đổi cá thể giữa các khu bảo tồn để giữ 'độ thuần' tối đa.","ans":false,"exp":"Trái lại: 'giải cứu di truyền' (Genetic rescue — đưa một vài cá thể từ quần thể lân cận cùng loài tới giao phối) giúp đưa alen mới vào xóa bỏ trạng thái đồng hợp lặn có hại và nâng cao sức sống quần thể."}],"summaryExp":""},{"id":"TF-073","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Kích thước Hiệu quả $N_e$ & Hệ số Nội phối $F$","stem":"Trong một chương trình bảo tồn loài hươu sao quý hiếm có $N = 100$ cá thể trưởng thành tham gia sinh sản: Trại A nuôi $50$ đực và $50$ cái; Trại B nuôi $5$ đực và $95$ cái. Biết kích thước hiệu quả tính theo công thức $N_e = \\frac{4 N_m N_f}{N_m + N_f}$ và tỷ lệ mất dị hợp tử mỗi thế hệ do phiêu bạt di truyền là $\\Delta F = \\frac{1}{2 N_e}$. Xét các phân tích định lượng sau:","statements":[{"key":"a","text":"Kích thước hiệu quả $N_e$ của Trại A bằng đúng $100$ cá thể, còn $N_e$ của Trại B chỉ còn xấp xỉ $19$ cá thể ($19.0$).","ans":true,"exp":"Trại A: $\\frac{4\\times 50\\times 50}{100} = 100$. Trại B: $\\frac{4\\times 5\\times 95}{100} = \\frac{1900}{100} = 19.0$!"},{"key":"b","text":"Mặc dù cả hai trại đều nuôi tổng cộng $100$ cá thể, nhưng tốc độ mất đa dạng di truyền (gia tăng hệ số nội phối $\\Delta F$) mỗi thế hệ ở Trại B diễn ra nhanh gấp hơn $5$ lần so với Trại A.","ans":true,"exp":"Trại A mất $\\frac{1}{200} = 0.5\\%$/thế hệ; Trại B mất $\\frac{1}{38} \\approx 2.63\\%$/thế hệ (tỷ số $100/19 \\approx 5.26$ lần)."},{"key":"c","text":"Nếu trong Trại A, người ta chọn từ nguồn ban đầu có $p = q = 0.50$ và thực hiện giao phối cận huyết đạt hệ số nội phối $F = 0.40$, thì cấu trúc di truyền hiện tại sẽ là $0.35 AA + 0.30 Aa + 0.35 aa = 1$.","ans":true,"exp":"$Aa = 2pq(1-F) = 0.50 \\times (1 - 0.40) = 0.30$; $AA = p^2 + pqF = 0.25 + 0.25(0.4) = 0.35$; $aa = 0.35$."},{"key":"d","text":"Sự sụt giảm mạnh kích thước hiệu quả $N_e$ ở Trại B là do khi có ít con đực tham gia phối giống thì tần số alen $A$ tự động tăng vọt lên $1.0$ ngay sau $1$ thế hệ ở mọi gen.","ans":false,"exp":"Ít con đực làm tăng biến động ngẫu nhiên (phương sai $\\frac{pq}{2N_e}$) chứ KHÔNG định hướng luôn đẩy alen trội lên $1.0$ ngay trong $1$ thế hệ."}],"summaryExp":""},{"id":"TF-074","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hiệu ứng Wahlund & Hòa nhập Quần thể","stem":"Giả sử có $2$ quần thể thực vật lớn kích thước BẰNG NHAU cùng loài nhưng tách biệt: Quần thể $1$ cân bằng ở $p_1(A) = 0.90, q_1(a) = 0.10$; Quần thể $2$ cân bằng ở $p_2(A) = 0.10, q_2(a) = 0.90$. Lấy tỷ lệ $50\\%$ hạt từ quần thể $1$ trộn đều với $50\\%$ hạt từ quần thể $2$ trồng chung tạo lô $P_{\\text{hỗn hợp}}$, rồi cho giao phấn ngẫu nhiên tự do. Xét các nhận định sau:","statements":[{"key":"a","text":"Ngay tại lô cây $P_{\\text{hỗn hợp}}$ trước khi giao phấn, tỉ lệ cây có kiểu gen dị hợp $Aa$ bằng $18\\%$, còn tỉ lệ đồng hợp $AA$ và $aa$ đều bằng $41\\%$.","ans":true,"exp":"QT1: $0.81 AA + 0.18 Aa + 0.01 aa$; QT2: $0.01 AA + 0.18 Aa + 0.81 aa$. Trung bình hỗn hợp: $0.41 AA + 0.18 Aa + 0.41 aa$."},{"key":"b","text":"Sự thiếu hụt thể dị hợp ($18\\%$ thực tế so với $50\\%$ lý thuyết tại $\\bar{p} = 0.50$) khi gộp $2$ quần thể phân hóa tần số alen gọi là hiệu ứng Wahlund.","ans":true,"exp":"Độ thiếu hụt dị hợp đúng bằng $2 \\text{Var}(p) = 2 \\times 0.4^2 = 0.32$ ($50\\% - 18\\% = 32\\%$)."},{"key":"c","text":"Sau khi cho lô $P_{\\text{hỗn hợp}}$ giao phấn ngẫu nhiên tự do qua $1$ thế hệ ($F_1$), tỉ lệ cây dị hợp $Aa$ vẫn bị giữ cố định ở mức $18\\%$ mà không tăng lên được.","ans":false,"exp":"Vì cả hạt phấn và noãn hỗn hợp đều mang $\\bar{p} = 0.5, \\bar{q} = 0.5$, ngay ở $F_1$ tỉ lệ dị hợp nhảy vọt từ $18\\%$ lên $50\\%$ (đạt cân bằng $0.25 AA : 0.50 Aa : 0.25 aa$)."},{"key":"d","text":"Quá trình hòa nhập ngẫu phối giữa $2$ quần thể trên làm tăng tần số alen $A$ từ $0.50$ lên $0.81$ chỉ nhờ tác động trộn gen.","ans":false,"exp":"Giao phấn ngẫu nhiên hoàn toàn bảo toàn tần số alen chung $\\bar{p}(A) = 0.50$ và $\\bar{q}(a) = 0.50$."}],"summaryExp":""},{"id":"TF-075","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phát sinh Sự sống & Các Đại Địa chất","stem":"Dựa trên bằng chứng địa chất, hóa thạch và thực nghiệm sinh hóa học về nguồn gốc sự sống và tiến trình phát triển sinh giới qua các đại địa chất trên Trái Đất:","statements":[{"key":"a","text":"Trong giai đoạn tiến hóa hóa học ở Trái Đất nguyên thủy, khí quyển giàu oxy phân tử ($O_2$) đóng vai trò chất xúc tác chính tổng hợp nên các hợp chất hữu cơ đơn giản như axit amin từ chất vô cơ.","ans":false,"exp":"Khí quyển nguyên thủy có tính KHỬ (hầu như KHÔNG có $O_2$ tự do, gồm $CH_4, NH_3, H_2, H_2O, CO_2...$) — chính sự vắng mặt của $O_2$ giúp các hợp chất hữu cơ mới sinh không bị oxy hóa phá hủy ngay."},{"key":"b","text":"Khi khí quyển tích lũy đủ $O_2$ từ quang hợp của vi khuẩn lam hình thành tầng ozon ($O_3$) chắn tia tử ngoại ở đại Cổ sinh (kỷ Silur), thực vật và động vật chân khớp bắt đầu di cư lên sống trên cạn.","ans":true,"exp":"Kỷ Silur chứng kiến thực vật mạch đầu tiên (như Quyết trần) và chân khớp tiến lên chinh phục đất liền."},{"key":"c","text":"Đại Trung sinh (gồm các kỷ Tam điệp, Jura, Phấn trắng) được mệnh danh là kỷ nguyên ngự trị của Bò sát khổng lồ (khủng long) và thực vật Hạt trần, đồng thời chứng kiến sự xuất hiện của Chim, Thú cổ và Thực vật có hoa (Hạt kín).","ans":true,"exp":"Cuối đại Trung sinh (kỷ Phấn trắng), thiên thạch rơi cộng hoạt động núi lửa làm tuyệt chủng khủng long phi điểu, mở đường cho đại Tân sinh."},{"key":"d","text":"Trong đại Tân sinh (cách nay $\\sim 66$ triệu năm đến hiện tại), các loài Thực vật Hạt kín, Côn trùng, Chim và Động vật có vú phát triển phân hóa bùng nổ, đỉnh cao là sự xuất hiện chi *Homo* và loài người *Homo sapiens* ở kỷ Đệ tứ.","ans":true,"exp":"Quá trình phát sinh loài người trải qua nhánh vượn người cổ, chi *Australopithecus*, *Homo habilis*, *Homo erectus* đến *Homo sapiens*."}],"summaryExp":""},{"id":"TF-076","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vận chuyển Nước & Thoát hơi nước","stem":"Thực vật trên cạn hấp thụ một lượng nước khổng lồ mỗi ngày qua rễ, đẩy theo mạch gỗ (Xylem) lên đỉnh tán cây cao tới cả trăm mét và thoát phần lớn qua lá. Xét các nhận định sinh lý về dòng mạch gỗ:","statements":[{"key":"a","text":"Động lực đẩy dòng nước từ dưới lên nhờ áp suất rễ có thể quan sát trực tiếp qua hiện tượng rỉ nhựa khi cắt ngang thân hoặc hiện tượng ứ giọt ở mép lá vào sáng sớm độ ẩm không khí bão hòa.","ans":true,"exp":"Khi thoát hơi nước ngừng vào đêm ẩm, áp suất rễ (chủ yếu do bơm ion vào mạch gỗ kéo nước theo thẩm thấu) đẩy nước thoát qua thủy khổng mép lá."},{"key":"b","text":"Cột nước liên tục trong mạch gỗ không bị đứt gãy ngay cả ở đỉnh cây gỗ cao hàng chục mét nhờ $2$ lực: lực liên kết giữa các phân tử nước với nhau (lực cố kết nhờ liên kết hiđrô) và lực bám dính giữa phân tử nước với thành mạch gỗ xenlulôzơ ưa nước.","ans":true,"exp":"Lực hút kéo từ sự thoát hơi nước tại lá tạo sức căng âm truyền suốt cột nước liên tục xuống tận lông hút rễ (thuyết sức căng - cố kết)."},{"key":"c","text":"Vào buổi trưa nắng gắt khi cây bị thiếu nước nghiêm trọng, thoát hơi nước qua bề mặt tầng cutin chiếm tới trên $90\\%$ tổng lượng nước bay hơi trong khi qua khí khổng dưới $10\\%$.","ans":false,"exp":"Khi khí khổng mở bình thường, thoát hơi nước qua KHÍ KHỔNG chiếm chủ yếu ($\\approx 90\\%$); chỉ khi cây đóng chặt khí khổng chống hạn thì lượng nhỏ qua cutin mới còn tồn tại (tầng cutin cản thấm rất mạnh, càng dày mất nước càng ít)."},{"key":"d","text":"Mạch gỗ cấu tạo từ hai loại tế bào chết (quản bào và mạch ống) có thành tế bào thấm lignin cực bền giúp ống dẫn không bị bẹp xẹp dưới áp suất âm lớn của dòng hút kéo.","ans":true,"exp":"Khác với mạch rây gồm tế bào sống (ống rây và tế bào kèm), tế bào mạch gỗ hóa gỗ chết rỗng hoàn toàn giúp giảm tối đa lực cản dòng nước."}],"summaryExp":""},{"id":"TF-077","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang hợp Thực vật $C_3$, $C_4$ và $CAM$","stem":"So sánh hiệu quả và cơ chế đồng hóa $CO_2$ pha tối của $3$ nhóm thực vật thích nghi với các điều kiện khí hậu khác nhau: lúa ($C_3$), mía ($C_4$) và dứa ($CAM$). Xét các nhận định sau:","statements":[{"key":"a","text":"Chất nhận $CO_2$ đầu tiên của thực vật $C_3$ là đường photphat $5$ cacbon ($RuBP$), còn chất nhận $CO_2$ đầu tiên cố định khí trời ở cả $C_4$ và $CAM$ đều là axit photphoenolpyruvic ($PEP$, $3$ cacbon).","ans":true,"exp":"Chu trình Calvin ở $C_3$ bắt đầu bằng RuBisCO gắn $CO_2$ vào $RuBP$; cả $C_4$ và $CAM$ đều bước đầu cố định nhờ enzyme PEP-carboxylase gắn $CO_2$ vào $PEP$ tạo $OAA$ ($4C$)."},{"key":"b","text":"Trong thực vật $C_4$, hai giai đoạn cố định $CO_2$ sơ cấp và chu trình Calvin xảy ra ở HAI THỜI ĐIỂM KHÁC NHAU (đêm và ngày) ngay trong cùng một loại tế bào mô giậu.","ans":false,"exp":"Đặc điểm tách biệt theo <strong>THỜI GIAN</strong> (đêm cố định qua PEPcase, ngày chạy Calvin) trong cùng tế bào là của thực vật <strong>$CAM$</strong>; còn thực vật <strong>$C_4$</strong> diễn ra cùng ban ngày nhưng tách biệt theo <strong>KHÔNG GIAN</strong> tại $2$ loại tế bào (tế bào mô giậu và tế bào bao bó mạch)!"},{"key":"c","text":"Do có cơ chế bơm $CO_2$ tập trung quanh RuBisCO nên nhóm $C_4$ hầu như triệt tiêu được hô hấp sáng, nhưng phải trả giá tốn thêm năng lượng ($\\approx 2\\text{ ATP}$ phụ cho mỗi phân tử $CO_2$ cố định để tái sinh $PEP$).","ans":true,"exp":"Vì tốn thêm $2\\text{ ATP}$ nên ở môi trường mát ẩm ít hô hấp sáng thì cây $C_3$ cạnh tranh tốt hơn, còn ở vùng nhiệt đới nắng nóng thì $C_4$ vượt trội hẳn."},{"key":"d","text":"Cả $3$ nhóm thực vật $C_3$, $C_4$ và $CAM$ cuối cùng đều BẮT BUỘC phải sử dụng chu trình Calvin (với enzyme RuBisCO) để tổng hợp nên đường glucozơ.","ans":true,"exp":"Mọi sinh vật quang hợp giải phóng oxy bậc cao đều dùng chu trình Calvin làm con đường tổng hợp cacbohiđrat thuần."}],"summaryExp":""},{"id":"TF-078","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Dinh dưỡng Nitơ & Chuyển hóa Khoáng","stem":"Thực vật không sử dụng được trực tiếp khí $N_2$ chiếm $78\\%$ khí quyển nếu không có quá trình cố định đạm sinh học hoặc lý-hóa, và trong mô cây nitơ đồng hóa thành axit amin theo những con đường chặt chẽ. Xét các nhận định sau:","statements":[{"key":"a","text":"Trong đất tơi xốp thoáng khí, nhóm vi khuẩn nitrat hóa (*Nitrosomonas* và *Nitrobacter*) oxy hóa lần lượt $NH_4^+ \\rightarrow NO_2^- \\rightarrow NO_3^-$ tạo dạng đạm dễ hấp thụ cho cây trồng.","ans":true,"exp":"Vi khuẩn hóa tự dưỡng thu năng lượng từ sự oxy hóa amôni và nitrit để cố định cacbon."},{"key":"b","text":"Sau khi rễ cây hấp thụ ion $NO_3^-$ vào tế bào, cây có thể gắn trực tiếp ngay gốc nitrat ($-NO_3$) vào khung cacbon axit hữu cơ để biến thẳng thành axit amin mà không cần khử thành $NH_4^+$.","ans":false,"exp":"Cây BẮT BUỘC phải thực hiện quá trình khử $NO_3^- \\xrightarrow{\\text{nitrat reductase}} NO_2^- \\xrightarrow{\\text{nitrit reductase}} NH_4^+$ rồi mới thực hiện amin hóa gắn $NH_4^+$ vào $\\alpha$-xêtôglutaric tạo axit amin."},{"key":"c","text":"Khi bổ sung dư thừa ion $NH_4^+$ trong tế bào thực vật, cây giải độc amoni bằng cách gắn vào axit amin dicarboxylic (tạo thành amit như Asparagin hoặc Glutamin) giúp dự trữ nitơ an toàn.","ans":true,"exp":"Hình thành amit vừa khử độc $NH_3$ vừa là kho dự trữ đạm cơ động cho nhu cầu sinh tổng hợp protein."},{"key":"d","text":"Các loài thực vật ăn sâu bọ (như cây nắp ấm, cây gọng vó sống ở đầm lầy đất chua nghèo khoáng) tiêu hóa côn trùng nhằm lấy chất hữu cơ thay thế hoàn toàn chức năng quang hợp.","ans":false,"exp":"Các loài cây này vẫn có diệp lục quang hợp tự tạo chất hữu cơ từ $CO_2$ bình thường; chúng bắt côn trùng chủ yếu để bổ sung nguồn <strong>Nitơ (đạm) và Phốt pho</strong> thiếu hụt trong đất ngập lầy."}],"summaryExp":""},{"id":"TF-079","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Điều hòa Hormone & Nảy mầm / Ra hoa Thực vật","stem":"Trong nông nghiệp và công nghệ sinh học thực vật, việc hiểu rõ cơ chế tác động đối kháng hay hiệp đồng của các nhóm phytohormone giúp điều khiển quá trình nảy mầm hạt, ra rễ giâm cành, tạo quả không hạt và ra hoa trái vụ. Xét các nhận định sau:","statements":[{"key":"a","text":"Ở hạt đại mạch đang nảy mầm, khi phôi hút nước đủ sẽ tổng hợp hormone $ABA$ để kích thích lớp tế bào alơrôn tiết mạnh enzyme $\\alpha$-amylase thủy phân tinh bột trong nội nhũ.","ans":false,"exp":"Hormone kích thích lớp alơrôn sản sinh $\\alpha$-amylase phá ngủ kích thích nảy mầm là <strong>Gibberellin ($GA$)</strong>; ngược lại $ABA$ là hormone gây ngủ nghỉ và ức chế nảy mầm!"},{"key":"b","text":"Cắt bỏ chồi ngọn ở cây thân thảo (như tỉa ngọn chè, bông, cà phê) làm mất nguồn sản sinh Auxin từ đỉnh sinh trưởng, từ đó giải phóng ức chế ưu thế ngọn giúp các chồi nách bật mọc mạnh tạo tán xum xuê.","ans":true,"exp":"Tỉ lệ Auxin cao từ đỉnh kìm hãm chồi nách; khi bấm ngọn, Cytokinin từ rễ thắng thế kích thích chồi bên phát triển."},{"key":"c","text":"Đối với cây ngày DÀI cần thời gian sáng trên $14\\text{ giờ}$ để ra hoa (tối tới hạn $< 10\\text{ giờ}$), trong điều kiện mùa đông đêm dài $13\\text{ giờ}$, nhà vườn thắp đèn ánh sáng đỏ ($660\\text{ nm}$) ngắt quãng giữa đêm khoảng $15$ phút sẽ thúc đẩy cây ra hoa trái vụ.","ans":true,"exp":"Một lóe ánh sáng đỏ giữa đêm chuyển phytochrome $P_r \\to P_{fr}$, chia đôi đêm dài $13\\text{ h}$ thành hai nửa $6.5\\text{ h} < 10\\text{ h}$ khiến cây ngày dài cảm nhận như đêm ngắn và ra hoa."},{"key":"d","text":"Phun dung dịch Auxin hoặc Gibberellin nồng độ thích hợp lên hoa cái chưa thụ phấn của cà chua hoặc nho có thể kích thích bầu nhụy phát triển thành quả không hạt (tạo quả đơn tính).","ans":true,"exp":"Thay thế nguồn hormone tự nhiên vốn do phôi hạt sinh ra sau thụ tinh bằng hormone ngoại sinh giúp bầu quả phình lớn mà không tạo hạt."}],"summaryExp":""},{"id":"TF-080","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh lý Tiêu hóa Hóa học ở Người","stem":"Theo dõi quá trình tiêu hóa hóa học các đại phân tử thức ăn (tinh bột, protein, lipid) khi đi dọc qua khoang miệng, dạ dày và tá tràng của ống tiêu hóa người:","statements":[{"key":"a","text":"Enzyme Amylase trong nước bọt bắt đầu thủy phân tinh bột chín thành đường đôi mantozơ ở khoang miệng (pH $\\approx 6.5 - 7.0$), nhưng khi xuống tới dịch vị dạ dày có $pH \\approx 1.5 - 2.0$ thì enzyme amylase nước bọt nhanh chóng bị bất hoạt.","ans":true,"exp":"pH axit mạnh của HCl làm biến tính mất hoạt tính amylase nước bọt, đồng thời diệt hầu hết vi khuẩn theo thức ăn."},{"key":"b","text":"Trong dạ dày, tế bào chính tiết tiền enzyme $Pepsinogen$ không hoạt động (tránh tự tiêu hóa tuyến dạ dày); khi tiếp xúc axit $HCl$, $Pepsinogen$ được cắt thành enzyme $Pepsin$ hoạt động thủy phân protein thành các chuỗi polipeptit ngắn.","ans":true,"exp":"Ngoài cơ chế tiết tiền chất bất hoạt (zymogen), lớp chất nhầy bicarbonat phủ niêm mạc bảo vệ dạ dày khỏi tự tiêu."},{"key":"c","text":"Tại tá tràng, enzyme $Trypsinogen$ do tuyến tụy tiết ra được hoạt hóa thành $Trypsin$ bởi enzyme Enterokinase bám trên vi nhung mao thành ruột non, sau đó chính $Trypsin$ lại tự hoạt hóa các zymogen tụy khác (như Chymotrypsinogen).","ans":true,"exp":"Cơ chế hoạt hóa dây chuyền chỉ khởi động ngay trong lòng ruột non giúp bảo vệ mô tuyến tụy khỏi viêm tụy cấp tự tiêu."},{"key":"d","text":"Muối mật do tế bào gan tiết ra và dự trữ ở túi mật chứa một loại enzyme Lipase rất mạnh trực tiếp cắt đứt các liên kết este trong phân tử triglixerit thành axit béo tự do.","ans":false,"exp":"Dịch mật HOÀN TOÀN KHÔNG chứa enzyme tiêu hóa! Muối mật chỉ đóng vai trò nhũ tương hóa cơ học chia giọt mỡ lớn thành hạt nhỏ để tăng diện tích tiếp xúc cho enzyme <strong>Lipase của dịch tụy</strong> cắt phân tử chất béo."}],"summaryExp":""},{"id":"TF-081","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh lý Tim & Huyết động học","stem":"Xét hoạt động cơ học và điều hòa của tim trong một chu kỳ chuẩn ($0.8\\text{ s}$) ở một người trưởng thành khỏe mạnh khi nghỉ ngơi (nhịp tim $75\\text{ nhịp/phút}$, $EDV = 120\\text{ ml}$, $ESV = 50\\text{ ml}$). Mỗi nhận định sau Đúng hay Sai?","statements":[{"key":"a","text":"Thể tích tâm thu của mỗi tâm thất ở người này bằng $70\\text{ ml}$ và cung lượng tim đạt $5.25\\text{ lít/phút}$.","ans":true,"exp":"$SV = 120 - 50 = 70\\text{ ml}$; $CO = 75 \\times 70 = 5250\\text{ ml/phút} = 5.25\\text{ lít/phút}$."},{"key":"b","text":"Tiếng tim thứ nhất ($T_1$ - 'bùm') xuất hiện do van động mạch chủ và phổi đóng lại, còn tiếng tim thứ hai ($T_2$ - 'tặc') xuất hiện do đóng van hai lá và ba lá.","ans":false,"exp":"Ngược lại: Tiếng $T_1$ do đóng <strong>van nhĩ-thất</strong> (hai lá và ba lá) khi bắt đầu thì tâm thất co; tiếng $T_2$ do đóng <strong>van tổ chim/bán nguyệt</strong> (động mạch chủ và động mạch phổi) khi bắt đầu thì tâm thất dãn."},{"key":"c","text":"Theo định luật Frank - Starling của tim, trong giới hạn sinh lý, máu tĩnh mạch đổ về tâm thất làm căng sợi cơ tim cuối tâm trương ($EDV$) càng lớn thì lực co bóp của tâm thất tăng tương ứng để tống lượng máu lớn hơn vào động mạch.","ans":true,"exp":"Kéo dãn sarcomer tới chiều dài tối ưu làm tăng độ nhạy với $Ca^{2+}$ và tăng số cầu nối actin-myosin giúp tự động cân bằng lượng máu tống ra với máu trở về."},{"key":"d","text":"Khi vận động thể lực mạnh, hệ thần kinh giao cảm giải phóng Noradrenalin gắn thụ thể $\\beta_1$ trên nút xoang nhĩ và cơ tim làm TĂNG cả tần số phát nhịp lẫn lực co bóp cơ tim giúp cung lượng tim có thể tăng lên $3-4$ lần.","ans":true,"exp":"Cơ chế giao cảm tăng cAMP mở kênh ion funny ($I_f$) đẩy nhanh khử cực tự phát nút xoang và tăng bơm $Ca^{2+}$ vào cơ tim."}],"summaryExp":""},{"id":"TF-082","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vận chuyển Khí & Hiệu ứng Bohr","stem":"Phân tích đường cong phân ly Oxyhemoglobin ($Hb-O_2$) biểu diễn mối quan hệ giữa phần trăm bão hòa $O_2$ của Hemoglobin ($Y\\%$) theo phân áp $O_2$ ($pO_2$, $\\text{mmHg}$). Xét các nhận định sau trong trạng thái sinh lý bình thường và khi cơ vân chạy cường độ cao:","statements":[{"key":"a","text":"Đường cong phân ly $Hb-O_2$ có dạng hình chữ $S$ (sigmoid) do cấu trúc tứ phân của phân tử Hemoglobin biểu hiện tính gắn hợp tác dương tính: khi tiểu phần thứ nhất gắn $O_2$ làm thay đổi cấu hình không gian giúp $3$ tiểu phần còn lại gắn $O_2$ dễ dàng hơn nhiều.","ans":true,"exp":"Chính tính chất hình chữ $S$ giúp $Hb$ bão hòa gần $98\\%$ ở phổi ($pO_2 \\approx 100\\text{ mmHg}$) nhưng chỉ cần $pO_2$ mô giảm xuống $40 \\to 20\\text{ mmHg}$ đã giải phóng nhanh lượng lớn $O_2$."},{"key":"b","text":"Tại mô cơ bắp đang chạy nước rút mạnh tạo ra nhiều axit lactic (làm $pH$ giảm), nồng độ $CO_2$ tăng và nhiệt độ cơ tăng cao, tất cả các yếu tố này đồng loạt làm dịch chuyển đường cong phân ly $Hb-O_2$ sang PHẢI (hiệu ứng Bohr), làm giảm ái lực với $O_2$ để nhả $O_2$ dồi dào hơn cho cơ.","ans":true,"exp":"Đây là cơ chế thích nghi tối ưu đưa $O_2$ đúng đến những mô đang chuyển hóa mạnh cần oxy nhất."},{"key":"c","text":"Chất $2,3$-BPG ($2,3$-bisphosphoglycerate) do hồng cầu tổng hợp tăng lên khi người leo núi cao giúp đường cong phân ly $Hb-O_2$ dịch chuyển mạnh sang TRÁI làm $Hb$ khóa chặt oxy không bao giờ nhả ra cho mô.","ans":false,"exp":"$2,3$-BPG gắn ổn định trạng thái T (deoxy-Hb), làm đường cong dịch sang PHẢI (giảm ái lực nhẹ ở mô) giúp giải phóng $O_2$ cho tế bào mô dễ dàng hơn ở độ cao trung bình."},{"key":"d","text":"Ở động mạch phổi đưa máu từ tim lên phổi có phân áp $O_2$ cao ($100\\text{ mmHg}$) hơn hẳn ở động mạch chủ đi nuôi cơ thể ($40\\text{ mmHg}$).","ans":false,"exp":"Động mạch phổi mang máu NGHÈO $O_2$ từ tâm thất phải lên phổi ($pO_2 \\approx 40\\text{ mmHg}$); chỉ sau khi trao đổi khí ở mao mạch phế nang thì máu tĩnh mạch phổi và động mạch chủ mới đạt $pO_2 \\approx 95 - 100\\text{ mmHg}$."}],"summaryExp":""},{"id":"TF-083","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Thận & Điều hòa Thể tích Dịch cơ thể","stem":"Đơn vị chức năng thận (Nephron) thực hiện $3$ quá trình chính là Lọc ở cầu thận, Tái hấp thu và Bài tiết thêm tại hệ thống ống thận để tạo nước tiểu và duy trì cân bằng nội môi. Xét các nhận định sau:","statements":[{"key":"a","text":"Ở người bình thường khỏe mạnh, toàn bộ $100\\%$ lượng glucose và protein albumin huyết tương đều được lọc tự do qua màng lọc cầu thận rồi sau đó tái hấp thu hết ở ống lượn gần.","ans":false,"exp":"Glucose lọc tự do và được tái hấp thu $100\\%$ qua đồng vận chuyển $Na^+$-glucose tại ống lượn gần; nhưng các đại phân tử protein huyết tương như Albumin gần như KHÔNG đi qua được khe lọc cầu thận do kích thước lớn và màng đáy tích điện âm đẩy lại!"},{"key":"b","text":"Hormone Aldosterone tiết ra từ lớp cầu vỏ tuyến thượng thận (kích hoạt qua hệ Renin - Angiotensin - Aldosterone khi huyết áp hoặc $Na^+$ giảm) kích thích tế bào chính ở ống lượn xa và ống góp tăng TÁI HẤP THU $Na^+$ kèm nước và tăng BÀI TIẾT $K^+$.","ans":true,"exp":"Do tái hấp thu $Na^+$ kéo nước theo thẩm thấu, Aldosterone giúp nâng thể tích máu và huyết áp."},{"key":"c","text":"Peptide lợi niệu tâm nhĩ ($ANP$) do tế bào cơ tâm nhĩ tiết ra khi huyết áp và thể tích máu tăng căng quá mức có tác dụng đối kháng với hệ RAAS: gây giãn tiểu động mạch đến cầu thận tăng lọc và tăng thải trừ $Na^+$ cùng nước qua nước tiểu.","ans":true,"exp":"Hệ RAAS/ADH (giữ muối, nước, tăng áp) đối trọng cân bằng tinh vi với ANP (thải muối, nước, hạ áp)."},{"key":"d","text":"Nếu thuốc lợi tiểu Furosemide ức chế đồng vận chuyển $Na^+-K^+-2Cl^-$ ở nhánh lên dày quai Henle, độ ưu trương của dịch kẽ vùng tủy thận sẽ giảm mạnh, kéo theo mất khả năng cô đặc nước tiểu và tăng lượng nước tiểu thải ra.","ans":true,"exp":"Làm giảm gradient thẩm thấu tủy thận khiến nước không thể tái hấp thu thụ động tại nhánh xuống và ống góp dù có $ADH$."}],"summaryExp":""},{"id":"TF-084","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Xinap Hóa học vs Điện học & Xử lý Thông tin","stem":"So sánh cơ chế truyền tin qua Xinap hóa học và Xinap điện học, cũng như cách một nơron trung gian tích hợp đồng thời nhiều tín hiệu đến:","statements":[{"key":"a","text":"Tại xinap hóa học, xung thần kinh chỉ truyền một chiều từ màng trước xinap sang màng sau xinap vì chỉ chùy xinap mới chứa bóng chất dẫn truyền thần kinh và chỉ màng sau xinap mới có thụ thể tiếp nhận tương ứng.","ans":true,"exp":"Tính chất một chiều và hiện tượng 'chậm xinap' ($\\approx 0.5-1\\text{ ms}$) giúp định hướng luồng thông tin thần kinh chính xác."},{"key":"b","text":"Chất dẫn truyền thần kinh ức chế như $GABA$ hoặc Glycine khi gắn vào thụ thể kênh ở màng sau xinap thường làm mở kênh $Cl^-$ (cho $Cl^-$ đi vào) hoặc mở kênh $K^+$ (cho $K^+$ đi ra), gây tăng phân cực màng (điện thế sau xinap ức chế $IPSP$).","ans":true,"exp":"Làm điện thế trong màng âm hơn nữa (ví dụ từ $-70\\text{ mV}$ xuống $-75\\text{ mV}$), đẩy màng ra xa ngưỡng kích thích $-55\\text{ mV}$."},{"key":"c","text":"Khác với xinap hóa học, xinap điện học nối hai tế bào trực tiếp qua các kênh liên kết khe (Gap junction), cho phép dòng ion truyền trực tiếp cực nhanh hầu như không có độ trễ xinap.","ans":true,"exp":"Xinap điện học có mặt phổ biến ở tế bào cơ tim (giúp tim đồng bộ hóa co bóp thành khối) và các phản xạ thoát hiểm siêu nhanh ở cá/giáp xác."},{"key":"d","text":"Sau khi chất dẫn truyền kích thích Acetylcholine bám vào màng sau xinap gây mở kênh ion, nó sẽ bám chặt vĩnh viễn tại thụ thể đó suốt đời để cơ bắp luôn giữ trạng thái co cứng liên tục.","ans":false,"exp":"Ngay sau vài phần nghìn giây, Acetylcholinesterase thủy phân Acetylcholine thành choline và axetat để kết thúc kích thích (chất truyền tin khác như serotonin/dopamine được tái hấp thu lại màng trước xinap)."}],"summaryExp":""},{"id":"TF-085","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hệ Miễn dịch Động vật có vú","stem":"Cơ thể người tự vệ trước vi khuẩn, virus và ký sinh trùng thông qua hai tuyến phòng thủ phối hợp: Miễn dịch không đặc hiệu (bẩm sinh) và Miễn dịch đặc hiệu (thích nghi). Xét các nhận định sau:","statements":[{"key":"a","text":"Lớp biểu bì da, chất nhầy niêm mạc, axit $HCl$ dịch vị, enzyme lysozyme nước mắt, tế bào thực bào và tế bào giết tự nhiên ($NK$) đều thuộc tuyến miễn dịch bẩm sinh (không đặc hiệu).","ans":true,"exp":"Tuyến miễn dịch bẩm sinh phản ứng nhanh ngay từ giờ đầu không cần ghi nhớ tiếp xúc trước."},{"key":"b","text":"Cả hai dòng tế bào miễn dịch đặc hiệu chính là Lympho B và Lympho T đều được sản sinh tại tủy xương và đồng loạt di cư tới tuyến ức (Thymus) để biệt hóa trưởng thành hoàn toàn.","ans":false,"exp":"Chỉ có tế bào <strong>Lympho T</strong> di cư tới <strong>tuyến ức (Thymus)</strong> để trưởng thành và chọn lọc âm-dương; còn tế bào <strong>Lympho B</strong> ở động vật có vú trưởng thành ngay tại <strong>tủy xương (Bone marrow)</strong>!"},{"key":"c","text":"Tế bào bị nhiễm virus thường tiết ra protein tín hiệu <strong>Interferon</strong> kích thích các tế bào lành lân cận sản sinh các enzyme phong tỏa sự nhân lên của virus.","ans":true,"exp":"Interferon loại I ($IFN-\\alpha, IFN-\\beta$) tạo trạng thái kháng virus cấp tính cho mô xung quanh và hoạt hóa tế bào NK."},{"key":"d","text":"Dị ứng quá mẫn tức thì (như sốc phản vệ hay dị ứng phấn hoa, hải sản) xảy ra khi dị nguyên gắn chéo các kháng thể $IgE$ bám sẵn trên bề mặt tế bào Mast (tế bào phì) làm vỡ hạt giải phóng ồ ạt <strong>Histamine</strong>.","ans":true,"exp":"Histamine gây giãn mạch nhanh, tăng tính thấm thành mạch, co thắt cơ trơn phế quản và nổi mề đay."}],"summaryExp":""},{"id":"TF-086","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điều hòa Nội tiết & Cơ chế Ngược âm tính","stem":"Xét sự điều hòa hoạt động nội tiết theo trục Hạ đồi (dưới đồi) $\\rightarrow$ Tuyến yên $\\rightarrow$ Tuyến giáp và cơ chế cân bằng đường huyết quanh mức sinh lý ($\\sim 0.8 - 1.2\\text{ g/L}$ hay $\\sim 4.4 - 6.1\\text{ mmol/L}$) ở người:","statements":[{"key":"a","text":"Khi trời lạnh kéo dài, vùng dưới đồi tăng tiết $TRH$ kích thích thùy trước tuyến yên tiết $TSH$, thúc đẩy tuyến giáp giải phóng $T_3, T_4$ nhằm tăng cường chuyển hóa cơ bản và sinh nhiệt duy trì thân nhiệt.","ans":true,"exp":"Hormone tuyến giáp làm tăng biểu hiện bơm $Na^+/K^+$ ATPase và tiêu thụ $O_2$ sinh nhiệt (calorigenic effect)."},{"key":"b","text":"Nồng độ hormone tuyến giáp $T_3, T_4$ trong máu tăng cao sẽ quay ngược lại kích thích dương tính dồn dập lên vùng dưới đồi và tuyến yên tiết thêm nhiều $TRH$ và $TSH$ lên vô hạn.","ans":false,"exp":"Đó là cơ chế điều hòa ngược <strong>ÂM TÍNH</strong> (Negative feedback): $T_3, T_4$ cao tự động ức chế lại thùy trước tuyến yên và vùng dưới đồi giảm tiết $TSH, TRH$ để giữ nồng độ ổn định."},{"key":"c","text":"Trong trường hợp người bị thiếu hụt hoàn toàn nguyên tố Iốt trong khẩu phần ăn kéo dài, tuyến giáp không tổng hợp đủ $T_3, T_4$ làm mất lực ức chế ngược lên tuyến yên khiến $TSH$ tăng tiết liên tục, kích thích mô tuyến giáp phì đại gây bệnh bướu cổ đơn thuần.","ans":true,"exp":"Thiếu nguyên liệu iốt dẫn tới $T_3/T_4$ thấp $\\rightarrow$ tăng $TSH$ kéo dài $\\rightarrow$ phì đại bù trừ nang giáp."},{"key":"d","text":"Khi đói xa bữa ăn đường huyết hạ xuống thấp, tế bào $\\alpha$ đảo tụy giảm tiết Glucagon đồng thời tế bào $\\beta$ tăng mạnh tiết Insulin để đẩy glucose từ máu vào tế bào mỡ.","ans":false,"exp":"Khi đường huyết GIẢM, tế bào <strong>$\\alpha$</strong> tăng tiết <strong>Glucagon</strong> kích thích gan phân giải glycogen tạo glucose giải phóng vào máu; ngược lại <strong>Insulin</strong> (tế bào $\\beta$) giảm tiết tối đa."}],"summaryExp":""},{"id":"TF-087","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Nội tiết Chu kỳ Kinh nguyệt & Thai kỳ","stem":"Theo dõi diễn biến nồng độ của $5$ hormone ($GnRH, FSH, LH, Estrogen, Progesterone$) ở phụ nữ trong chu kỳ kinh nguyệt bình thường $28$ ngày (rụng trứng ngày $14$) và khi có sự thụ tinh thành công:","statements":[{"key":"a","text":"Ở giai đoạn đầu chu kỳ (pha nang trứng), hormone $FSH$ từ tuyến yên kích thích nang trứng phát triển, và các tế bào hạt của nang trứng tăng cường bài tiết Progesterone ở mức cực đại gây bong niêm mạc.","ans":false,"exp":"Trong pha nang trứng (ngày $1-14$), nang trứng tiết chủ yếu <strong>Estrogen</strong> để tái tạo làm dày niêm mạc tử cung; <strong>Progesterone</strong> chỉ tăng vọt chủ yếu ở pha thể vàng SAU khi rụng trứng."},{"key":"b","text":"Sự tăng cao đột ngột nồng độ Estrogen vào cuối pha nang trứng chuyển tác động sang điều hòa ngược dương tính lên vùng dưới đồi-tuyến yên gây ra đỉnh $LH$ làm vỡ nang chín phóng thích noãn bào II.","ans":true,"exp":"Nồng độ Estrogen duy trì ngưỡng cao $> 200\\text{ pg/ml}$ trong $\\ge 50$ giờ kích hoạt đỉnh $LH$ phóng noãn."},{"key":"c","text":"Nếu không có sự thụ tinh xảy ra, thể vàng thoái hóa sau $\\sim 12 - 14$ ngày làm tụt giảm đột ngột nồng độ Progesterone và Estrogen, kéo theo co thắt tiểu động mạch xoắn gây bong tróc lớp chức năng niêm mạc tử cung (hành kinh).","ans":true,"exp":"Sự sụt giảm đột ngột hormone buồng trứng là tín hiệu trực tiếp khởi phát chu kỳ kinh mới."},{"key":"d","text":"Nếu trứng được thụ tinh và làm tổ tại niêm mạc tử cung, các tế bào lá nuôi của phôi sớm tiết ra hormone <strong>$hCG$</strong> (Human Chorionic Gonadotropin) giúp duy trì thể vàng tiếp tục sống và tiết Progesterone trong suốt giai đoạn đầu thai kỳ.","ans":true,"exp":"Que thử thai phát hiện nhanh sự có mặt của hormone $hCG$ (có cấu trúc tương tự $LH$) bài tiết ra trong nước tiểu mẹ sớm."}],"summaryExp":""},{"id":"TF-088","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Diễn thế Sinh thái & Độ Đa dạng Quần xã","stem":"So sánh diễn biến cấu trúc của một quần xã sinh vật trong suốt tiến trình diễn thế nguyên sinh (khởi đầu từ bãi tro tàn núi lửa đá trần không đất) tới giai đoạn quần xã đỉnh cực (rừng ôn đới/nhiệt đới trưởng thành), và cách đo độ đa dạng loài:","statements":[{"key":"a","text":"Trong tiến trình diễn thế từ quần xã tiên phong (địa y, rêu) hướng tới quần xã đỉnh cực, tổng sinh khối tích lũy, số lượng loài, độ phức tạp lưới thức ăn và khả năng tự điều chỉnh ổn định nhìn chung tăng dần theo thời gian.","ans":true,"exp":"Quá trình hình thành đất mùn dày dần kéo theo sự đa dạng hóa cấu trúc tầng tán và nhiều ổ sinh thái mới."},{"key":"b","text":"Nếu khu rừng đỉnh cực bị cháy rừng hoàn toàn hoặc chặt trắng nhưng lớp đất mùn, rễ cây và ngân hàng hạt giống dưới đất vẫn còn tồn tại, quá trình phục hồi sau đó diễn ra chậm hơn diễn thế nguyên sinh rất nhiều lần.","ans":false,"exp":"Đó là diễn thế THỨ SINH — vì đã có sẵn nền đất giàu dinh dưỡng và nguồn hạt mầm sống sót nên diễn thế thứ sinh diễn ra NHANH hơn rất nhiều so với diễn thế nguyên sinh trên đá trần."},{"key":"c","text":"Hai quần xã cùng có đúng $4$ loài cây ($S = 4$) nhưng Quần xã $1$ phân bố đồng đều ($25\\%, 25\\%, 25\\%, 25\\%$) sẽ có chỉ số đa dạng loài (theo cả Shannon-Wiener và Simpson) cao hơn hẳn Quần xã $2$ có $1$ loài chiếm tới $97\\%$ cá thể ($97\\%, 1\\%, 1\\%, 1\\%$).","ans":true,"exp":"Độ đa dạng loài là hàm kết hợp của cả Độ giàu loài (Species richness) và Độ đồng đều tương đối (Relative abundance / Evenness)."},{"key":"d","text":"Theo giả thuyết 'nhiễu loạn trung bình' (Intermediate Disturbance Hypothesis), mức độ xáo trộn môi trường ở cường độ và tần suất vừa phải thường duy trì độ đa dạng loài CAO hơn so với khi môi trường hoàn toàn yên tĩnh hoặc bị tàn phá quá khắc nghiệt liên tục.","ans":true,"exp":"Nhiễu loạn trung bình ngăn loài cạnh tranh ưu thế loại trừ sạch các loài khác nhưng vẫn đủ thời gian cho nhiều loài tái định cư."}],"summaryExp":""},{"id":"TF-089","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Dòng Năng lượng & Ngân sách Sinh học Hệ Sinh thái","stem":"Nghiên cứu dòng năng lượng chảy qua một hệ sinh thái rừng rụng lá ôn đới trong $1$ năm thu được số liệu thống kê tính trên $1\\text{ m}^2$: Tổng năng lượng bức xạ mặt trời chiếu tới là $1.5 \\times 10^6\\text{ kcal}$; Sinh vật sản xuất cố định được sản lượng sơ cấp thô $GPP = 24\\,000\\text{ kcal}$, trong đó thực vật tự hô hấp mất $R_a = 14\\,000\\text{ kcal}$. Động vật ăn cỏ (SVTT bậc $1$) ăn tiêu thụ $20\\%$ sản lượng $NPP$, phần còn lại rơi rụng vào lưới thức ăn mùn bã hoặc tích lũy trong thân gỗ. Xét các tính toán sau:","statements":[{"key":"a","text":"Sản lượng sơ cấp tinh ($NPP$) do hệ thực vật tích lũy thành chất hữu cơ mới trong năm bằng $10\\,000\\text{ kcal/m}^2\\text{/năm}$.","ans":true,"exp":"$NPP = GPP - R_a = 24\\,000 - 14\\,000 = 10\\,000\\text{ kcal/m}^2\\text{/năm}$."},{"key":"b","text":"Hiệu suất sử dụng năng lượng bức xạ mặt trời tính theo sản lượng sơ cấp thô ($GPP$) của thảm thực vật rừng là $1.6\\%$ và theo sản lượng tinh ($NPP$) là $6.67\\%$.","ans":false,"exp":"Hiệu suất theo $GPP$: $\\frac{24\\,000}{1\\,500\\,000} = 1.6\\%$ (ĐÚNG); nhưng hiệu suất theo $NPP$: $\\frac{10\\,000}{1\\,500\\,000} = 0.67\\%$ (gần $0.667\\%$), không phải $6.67\\%$!"},{"key":"c","text":"Tổng lượng năng lượng chứa trong thức ăn mà động vật ăn cỏ đã ăn vào ($I$) bằng $2000\\text{ kcal/m}^2\\text{/năm}$; giả sử $50\\%$ lượng đó mất qua phân ($F$) và $40\\%$ lượng đã ăn được dùng cho hô hấp tế bào ($R$), thì phần sinh trưởng tích lũy ($P$) của động vật ăn cỏ chỉ là $200\\text{ kcal/m}^2\\text{/năm}$.","ans":true,"exp":"$I = 20\\% \\times 10\\,000 = 2000\\text{ kcal}$. $F = 1000\\text{ kcal}$, $R = 800\\text{ kcal} \\Rightarrow P = 2000 - 1000 - 800 = 200\\text{ kcal}$. (Hiệu suất sinh thái truyền $200/10\\,000 = 2\\%$ tính từ tổng NPP hoặc $10\\%$ tính trên lượng ăn vào)."},{"key":"d","text":"Trong hầu hết các hệ sinh thái rừng trên cạn trưởng thành, lượng cacbon và năng lượng từ phần rụng lá rơi vào chuỗi thức ăn phế liệu (sinh vật ăn mùn bã và phân giải) thường lớn hơn nhiều so với luồng bị động vật ăn cỏ ăn sống trực tiếp.","ans":true,"exp":"Ở rừng ôn đới/nhiệt đới, $> 70-80\\%$ $NPP$ là gỗ và lá rụng đi trực tiếp vào hệ phân giải trong đất thay vì đi qua chuỗi gặm cỏ."}],"summaryExp":""},{"id":"TF-090","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh thái học Bảo tồn & Biến đổi Khí hậu","stem":"Trước thách thức suy giảm đa dạng sinh học toàn cầu do mất sinh cảnh và biến đổi khí hậu từ hoạt động con người, sinh thái học bảo tồn đưa ra các phân tích và giải pháp khoa học sau:","statements":[{"key":"a","text":"Khi một khu rừng nguyên sinh rộng lớn bị chia cắt thành hàng chục mảnh rừng nhỏ tách rời bởi đường cao tốc và nương rẫy, tổng diện tích 'vùng biên' (Edge effect) sẽ GIẢM đi đáng kể giúp các loài sống sâu trong lõi rừng phát triển mạnh hơn.","ans":false,"exp":"Phân mảnh sinh cảnh làm TĂNG vọt tỷ lệ chu vi/diện tích, mở rộng mạnh vùng biên chịu gió lốc, ánh sáng gắt và loài xâm lấn, thu hẹp nghiêm trọng vùng lõi bên trong khiến các loài đặc hữu vùng lõi suy thoái nhanh."},{"key":"b","text":"Xây dựng các hành lang sinh thái nối liền các khu bảo tồn bị tách rời giúp duy trì dòng di-nhập gen tự nhiên giữa các quần thể, giảm giao phối cận huyết và tăng khả năng sống sót khi loài phải dịch chuyển tránh biến đổi khí hậu.","ans":true,"exp":"Tuy nhiên cũng cần kiểm soát hành lang sinh thái cẩn thận để hạn chế phát tán mầm bệnh hoặc loài ngoại lai xâm hại."},{"key":"c","text":"Nồng độ $CO_2$ khí quyển tăng cao hòa tan nhiều vào đại dương tạo thành axit cacbonic ($H_2CO_3$) làm giảm độ pH nước biển (axit hóa đại dương) và làm giảm mạnh nồng độ ion cacbonat ($CO_3^{2-}$), đe dọa trực tiếp sự tạo bộ khung $CaCO_3$ của rạn san hô và động vật thân mềm.","ans":true,"exp":"$CO_2 + H_2O \\rightarrow H_2CO_3 \\rightarrow H^+ + HCO_3^-$; các ion $H^+$ dư kết hợp với $CO_3^{2-}$ thành $HCO_3^-$, làm cạn kiệt nguồn $CO_3^{2-}$ cho quá trình vôi hóa."},{"key":"d","text":"Hiện tượng nóng lên toàn cầu làm mất cân bằng nhịp sinh học (Phenological mismatch) giữa thực vật có hoa và côn trùng thụ phấn hoặc giữa thời điểm nở hoa-sâu non với mùa sinh sản của chim di cư ăn sâu.","ans":true,"exp":"Do một số loài phản ứng theo nhiệt độ (nở hoa/sâu nở sớm hơn) trong khi chim di cư lại định hướng thời điểm bay dựa trên quang chu kỳ (độ dài ngày cố định theo vĩ độ) dẫn đến lệch pha nguồn thức ăn."}],"summaryExp":""}];
